window.__D("text/keter-shem-tov/c005",{"p":[[300010844,"שיט\n\n<b>גאונותו</b>\n<b>שמעתי</b> בשם הבעש\"ט ז\"ל שאמר שאפילו יאמרו לי כל פשט שבעולם ופלפול וחריפות בגמרא ובפוסקים אקשה עליו קושיא<sup data-n=\"1\">101</sup>.",[["1","101","מאמרי אדמו\"ר הזקן ענינים ע' רצז-רצט (הובא בד\"ה וישלח יעקב תשמ\"ג), וממשיך שם:\nוהענין דהנה התורה נשתלשלה מעולם לעולם ובכל עולם הוא בפנים אחרות. והנה כל העולמות והבחי' הם בבחי' דכר ונוק', והנה כל עולם אצל מה שלמעלה ממנו הוא בחי' נוק' שמתאוה שישפיע עולם שלמעלה בה, וא\"כ בודאי הוא חסר איזה דבר שצריכה שימלא חסרונה מעולם שלמעלה, וא\"כ מוכרח להיות להיפוך וא\"כ בהתורה ג\"כ יש שבכל עולם ממטה למעלה לפי הפנים שיש לה באותו העולם מוכרח להיות לה איזה חסרון כנ\"ל, ובעולם שלמעלה לא קשיא קושיא זאת, וקשיא קושיא אחרת כנזכר עד שורש כל השרשים מהתורה שהיא חכמה שלמעלה ושם היא בשלימות גמור. אך כשצריכה להשתלשל צריכה להיות כך בכל העולמות.\nוהנה הצדיק שהוא יסו\"ע והוא ל' התקשרות שמקשר כל העולמות ולכן הי' יכול להשיב מה שיאמרו לו לפי הפשוט לפי שהוא ידוע מה שנחסר באותו העולם ויודע ג\"כ למלאות החסרון מעולם שלמעלה. וזה שהקשו לרב קושיא ואיתא ששתק רב, ואעפ\"כ בכל מקום ששתק הלכה כמותו, ולכאורה תמיה גדולה מהו. הענין שבאמת לפי העולם והפי' שהקשו לו היא באמת קושיא עצומה עד שאין יכולים לתרצה לפי אותו העולם, וזהו החסרון שבעולם הנ\"ל, ולכן שתק וד\"ל.\nנוסח אחר:\nענין מה ששמעתי מהבעש\"ט זלה\"ה כל פשט שיאמרו לו בחריפות ופלפול, הן בגמרא או פוסקים יקשה עליו תיכף ומיד קושיא על כל פשט וחריפות שיאמרו לו יתרץ ויקשה עוד קושי' עד אין קץ ותכלית. והענין הוא דהתורה נשתלשלה מעולם . . רצונו הפשוט כנ\"ל.\nוהנה הצדיק הוא יסוד עולם והוא לשון התקשרות שמקשר כל העולמות למטה ולמעלה עד שורש כל השרשים והוא קושי' שלמעלה מכל העולמות לכן הוא יודע כל החסרונות מהתורה של כל העולמות ולכן הי' יכול לתרץ כל קושי' וכל פשט שיאמרו לו הוא יודע החסרון מה שנחסר באותו העולם ויודע גם למלאות החסרון מעולם שלמעלה הימנו וכדאית' שתק רב בעגל שמודה מטרפה ואעפ\"כ הלכה כמותו בכל מקום ששתק כי האמת היא קושי' עצומה עד שאין באפשר לתרץ אותה לפי ערך העולם וזהו החסרון הוא בעולם שמחמת שאין העולם מכילו ולכן הוא שותק וד\"ל."]]],[300010845,"שכ\n\n<b>. . . מסורה</b> מרבי לרבי ועד לכ\"ק מו\"ח אדמו\"ר ע\"ד הגאוניות (כפשוטה, בנגלה) של הבעש\"ט ז\"ל<sup data-n=\"1\">102</sup> וכמו ששמע רבינו הזקן ממורו הרב המגיד בזה<sup data-n=\"2\">103</sup>.",[["1","102","ראה גם \"סיפורים נוראים\" להר\"י קאדאנער בתחילתו."],["2","103","מכתב חמשה עשר באב תש\"כ (אגרות-קודש חי\"ט ס\"ע שצט ואילך)."]]],[300010846,"שכא\n\n<b>הכיר כח האומן בכלי</b>\n<b>וכידוע</b> מהבעל שם טוב ז\"ל שהכיר בהכלי שהאומן הי' סומא בעין אחת, והיינו מכח הפועל שנשאר בהנפעל גם לאחר העשי'<sup data-n=\"1\">104</sup>.",[["1","104","ספר המאמרים תרמ\"ד ע' קעב. ראה כתבי קודש (לבוב, תרכ\"ב) לב, ד. וראה נוצר חסד (ירושלים, תער\"ב) פרק ו. בכ\"מ בחסידות הובא הנ\"ל בנוגע הרב המגיד – ראה שער האמונה ספכ\"ז. ספר המאמרים תרצ\"ו ע' 113. וש\"נ. ובאמרי בינה שער הק\"ש פל\"ד (לט, א): בגדולי הצדיקים. ובשיחת ש\"פ דברים תשד\"מ (התוועדויות ח\"ד ע' 2305) שכן הוא בכל רבותינו נשיאינו."]]],[300010847,"שכב\n\n<b>התפשטות הגשמיות</b>\n<b>בני</b> עלי' (ש)יש להם ממש התפשטות הגשמיות כמו אדמו\"ר הרב המגיד דמעזריטש והבעל שם טוב הם ראו עולמם בחייהם והשיגו מה שהשיגו<sup data-n=\"1\">105</sup>.",[["1","105","מאמרי אדמו\"ר הזקן פרשיות ח\"ב ע' תתכט. וממשיך שם: אבל אין אנו משיגים אפי' א' מני אלף מאותה ההשגה שהשיגו שם. הובא ונתבאר בד\"ה תקעו – כ\"ט אלול תשמ\"ג."]]],[300010848,"שכג\n\n<b>הבעש\"ט</b> כשהי' לו עליית הנשמה כו' הי' מופשט מכל הגשמת חיי חומריות גופו כמו המתעלף ממש<sup data-n=\"1\">106</sup> . . אשר לא ירגיש כל כאב והכאה . . וזהו למעלה מהפשטת חומר גופם שבנביאים בשעת הנבואה שאין שם כליון כלל אלא אדרבה שלימים בכל חושי גופם רק בלתי נרגשים מפני שנזדככו לקבלת האור האלקי וממילא נתבטל חומר הגסות כו'<sup data-n=\"2\">107</sup>.",[["1","106","הובא בספר המאמרים תרמ\"ט ע' רנו."],["2","107","שערי תשובה לאדמו\"ר האמצעי ח\"א מו, ד."]]],[300010849,"שכד\n\n<b>וכנודע</b> המעשה מהבעש\"ט ז\"ל אשר לא הי' יכול להשיב כהלכה במילי דעלמא בליל ש\"ק מחמת גודל עוצם התקשרותו בתכלי' הביטול האמיתי והתפלל ע\"ז שיתעלה ויוגבה למעלה להיות לו מוחי' דגדלו' כ\"כ עד שיוכל להשיב כהלכה אף במילי דעלמ' בליל שבת כי מחמת גדלות המוחי' אין תופס מקום כלל הענין דעלמא<sup data-n=\"1\">108</sup> ויוכל להשיב כהלכה באותו הענין שישאלוהו אף בשעת דביקותו הנפלאה ולא יבלבלו כלל<sup data-n=\"2\">109</sup>.",[["1","108","נו\"א: דמילי דעלמא."],["2","109","מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ע' קצג. ועד\"ז באוה\"ת מקץ ח\"ו תתשב, ב: וכנודע המעשה מהבעש\"ט ז\"ל שלא הי' יכול להשיב כהלכה במילי דעלמא בליל ש\"ק מחמת גודל ועוצם התקשרותו ודביקותו בה' והתפלל ע\"ז שיוגבה ויתעלה להיות לו מוחין דגדלות כ\"כ עד שיוכל להשיב כהלכה במילי דעלמא בליל ש\"ק כי מחמת גדלות המוחין אינו תופס מקום כלל הענין ויוכל להשיב כהלכה באותו ענין שישאלהו אף בשעת דביקותו הנפלאה ולא יבלבלנו כלל.\nועד\"ז במאמר ד\"ה ולא זכר תרל\"ג (ספר המאמרים תרל\"ג ח\"א ע' סו). עזר\"ת (ספר המאמרים עזר\"ת ע' קה). תרפ\"ח (ספר המאמרים תרפ\"ח ע' כו ואילך), ומסיים שם: והיינו שנתעלה במדרי' עליונה יותר במוחין דגדלות גופא דשם הנה אין זה מה שעניני עולם אינם מבלבלים ואינם מטרידים אלא עוד זאת אשר בעת עסקו בהם הוא מרכבה ממש לאלקות.\nובספר המאמרים תרכ\"ז ע' רצט: וזהו שפעל הבעש\"ט ז\"ל בסוף ימיו שאף שהי' למטה בעוה\"ז הגשמי לא יהי' לו שום סתירה כלל להיות ג\"כ בעולמות עליונים. וכנודע ממה שבליל ש\"ק הי' ב' שליש למעלה ושליש אחד למטה ובשאר ימי החול בהיפוך כו'. ובלקוטי שיחות חלק ד ע' 1310: ידוע אשר הבעש\"ט בסוף ימיו פעל שגם כשיהי' בעולמות עליונים יוכל לעשות ענין השייך לעוה\"ז (תו\"ח ויחי בסופו), וגם כשיעשה בעניני עוה\"ז יוכל להיות בשעת מעשה בעולמות עליונים. ובא' המאמרים מבואר אשר בימי החול הי' הבעש\"ט שליש א' למעלה וב' שלישים למטה וביום השבת הי' ב' שלישים למעלה ושליש א' למטה. ונמצא אשר תמיד, בין בחול בין בשבת, הי' חלק למטה וחלק למעלה.\nוראה גם בשם הבעש\"ט – מאמרי אדמו\"ר הזקן תקע\"א ע' קפא. תורת חיים שמות סה, ב. ספר המאמרים תרנ\"א ע' צז. ד\"ה ומקנה רב תש\"כ (ספר המאמרים תש\"כ ע' 163). ועוד."]]],[300010850,"שכה\n\n<b>מספרים</b> בשבחי<sup data-n=\"1\">110</sup> הבעש\"ט ז\"ל<sup data-n=\"2\">111</sup> שהתפלל כמה תפלות והתענ' תעניתי' שיוכל להשיב לשואלו דבר בעת עליות נשמתו בע\"ש בין השמשות בקבלת שבת דוקא ולא שהי' כוונתו שיהי' יכול להשיב לשואלו דוקא אלא הענין הוא דבשעת קבלת שבת אז עליות כל העולמות עד רום המעלות והי' נשמתו עולה במעלה ומדריגה גבוה מאד (כמו בבחי' יוסף ומשיח בחי' צ\"ע שבכל דור ודור כידוע) ולא הי' יכול להשפיל את עצמו למטה כלל להשיב לשואלו וכה\"ג שזהו ענין התיקון ובירור בדברים בטלים לגמרי שנשאר למטה דוקא בעת עליית הפנימי' (וכנ\"ל בענין השדים שנבראו בע\"ש בין השמשות וכמ\"ש בזוהר דקידוש השבת הפסיק שלא נברא גופים שלהם כו'<sup data-n=\"3\">112</sup>) ולזה התפלל כמה תפלות שיוכל לירד למטה דוקא בעת עליות נשמתו הגבה למעלה לפני קבלת שבת שיוכל לתקן גם מה שנשאר למטה בבחי' מותרות דריק ובטלה כמדריגות יוסף הנ\"ל שיש בכחו להשפיל את עצמו כ\"כ למטה בצירופי הדברים בטלים וריקים לבררם ג\"כ כי כל הגבוה יותר כו' כנ\"ל. וזהו שהי' יכול להשיב לשואלו דבר בדברים בטלים אחר שעשה כמה יחודים בתפלה ותענית ע\"ד זה שלא הי' בכחו תחלה לירד למטה כ\"כ לפי שלא הי' ברוממות המדריגה כ\"כ וד\"ל<sup data-n=\"4\">113</sup>.",[["1","110","נו\"א: בשבח."],["2","111","ראה שבחי הבעש\"ט (מהדורת הורודצקי – תש\"ז) ע' קד ואילך. ע' קס."],["3","112","ראה אבות פ\"ה, מ\"ו. זוהר בהקדמה יד, א. ביאורי הזוהר לאדמו\"ר האמצעי קרח צד, ד ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"ד ס\"ע א'תמז. וש\"נ."],["4","113","תורת חיים ס\"פ ויחי (קח, ג)."]]],[300010851,"שכו\n\n<b>זיווג רוחני</b>\n<b>האריז\"ל</b> והבעש\"ט והקדוש נ\"ע (ד)שרשם מבחי' זיווג רוחני הנ\"ל<sup data-n=\"1\">114</sup>.",[["1","114","המשך תער\"ב ח\"ג ע' א'רנז. ושם לפנ\"ז (ע' א'רנו ואילך): נשמות הנ\"ל הגם שהן גם ע\"י יחוד זו\"נ מ\"מ מפני ששרשם הוא מיחוד רוחני דאו\"א ה\"ה למטה ג\"כ בבחי' הרוחניות יותר משארי נשמות כו', והם הצדיקים שהולכים בהיכלות . . ואפשר דכמו\"כ בנשמות שלמטה הם מופשטים מהגשם לגמרי וכמו רב יהודא דלית דין בר אינש והן שנבקע עליהם הפרגוד כו' [ההמשך בפנים. וממשיך שם:] ועמ\"ש בלקו\"ת ד\"ה לויתן והבי'."]]],[300010852,"שכז\n\n<b>חכמים נבדלים</b>\n<b>בטבע</b> החכמים האמיתים שאינם מגלים דבר חכמתם ויותר אצלם בשתיקה והעדר הגילוי . . ולפעמים הרי באפשר שיסתירו עד שהוא כאלו אינם יודעים דבר חכ' כלל (וכמו הבעש\"ט כו')<sup data-n=\"1\">115</sup>, שזהו ג\"כ דרך הפלא ופלא<sup data-n=\"2\">116</sup>.",[["1","115","ראה ספר המאמרים תרפ\"א ע' קעז ואילך בשוה\"ג: . . . שהחכמים נבדלים, החכ' רק לעצמו, מדות לזולתו, ובלא הזולת תוכל להתבטל, והחכ' רק לעצמו, והעיקר התבודדות, האריז\"ל, הבעש\"ט ז\"ל, רבינו הזקן, עצמיים, בחי' ראשים כו'."],["2","116","ספר המאמרים תרפ\"ד ע' טז."]]],[300010853,"שכח\n\n<b>י\"ג תיקוני דיקנא</b>\n<b>כמדומה</b> יש בזה<sup data-n=\"1\">117</sup> ר\"ד מרבותינו שאינו הבעש\"ט נ\"ע – שע\"פ המסורה צ\"ל י\"ג (? – י\"ב) תק\"ד ניכר בהזקן<sup data-n=\"2\">118</sup>.",[["1","117","ע\"ד התמונה שמייחסים להבעש\"ט."],["2","118","לקוטי שיחות חלק יט ע' 531."]]],[300010854,"שכט\n\n<b>ידע לצרף אותיות כמו בצלאל</b>\n<b>אויפן</b> בעש\"ט זאָגט מען אַז ער איז געווען ע\"ד ווי עס שטייט<sup data-n=\"1\">119</sup> יודע הי' בצלאל לצרף אותיות שבהם נבראו שמים וארץ. הגם דאָס איז אַ ודאי אַ מעלה נשגבה, אָבער די שו\"א זיינען דאָך געווען פאַר בצלאל אויך, דער בעש\"ט האָט געוואוסט לצרף את האותיות – אויף מאַכן אַ אידן און ליב האָבן אים.\nידיעת התורה אַליין איז נאָך ניט די שלימות פון אַ אידן, נאָר דער עיקר השלימות איז אין די אותיות התורה און דער בעש\"ט האָט געוואוסט די אותיות מיט וואָס צו מקרב זיין אַ אידן און ליב האָבן אים<sup data-n=\"2\">120</sup>.",[["1","119","ברכות נה, א."],["2","120","ספר השיחות תש\"ב ע' 5."]]],[300010855,"של\n\n<b>יראתו</b>\n<b>וכידוע</b> במעלת היראה הפנימי' שהי' בבעש\"ט ז\"ל שהי' מעין יראה של משיח כו'<sup data-n=\"1\">121</sup>.",[["1","121","תורת חיים בשלח שכט, סע\"ב (בהוצאה החדשה – רכז, רע\"א)."]]],[300010856,"שלא\n\n<b>הרב</b> הבעש\"ט זלה\"ה סבבו אותו מכל פינה ולא פחד כלל, מפני יראת הרוממות כו' שבטלים אצלו כל היראות התחתונות<sup data-n=\"1\">122</sup>.",[["1","122","מאמרי אדמו\"ר הזקן ענינים ע' קפז. ומסיים שם: וכמ\"ש בח\"ה ארי' כו' ומה מאד גדולה זאת העבודה אשר בבוא הארי' לא יפחד ולא יזוע מפני יראתו כו' והבן זה כו' וד\"ל."]]],[300010857,"שלב\n\n<b>וכמו</b> שסיפרו על הבעש\"ט ז\"ל שגם בעת עוצם הפלגת שמחתו [ב]דביקות הי' נופל בפחד אלקי עד שהלבינו פניו עד שתשוב רוחו אליו<sup data-n=\"1\">123</sup>.",[["1","123","מאמרי אדמו\"ר האמצעי דרושי חתונה ח\"א ע' רסו."]]],[300010858,"שלג\n\n<b>לב הבעל שם טוב</b>\n<b>אין</b> דעם גילוי פון משיח וועט נתגלה ווערן די האַרץ פון בעש\"ט הקדוש, עס וועט נתגלה ווערן דער יקוד אש אין לב הגשמי צו אהבת ישראל, וואָס דער בעש\"ט איז צוגעקומען דערצו ע\"י עבודתו און ניט דורך אַ גילוי מלמעלה<sup data-n=\"1\">124</sup>.",[["1","124","ספר השיחות תש\"ב ע' 5."]]],[300010859,"שלד\n\n<b>יודע מחשבות</b>\n<b>ידוע</b> שיש בחי' חכמה לחכימין להכיר כל מה שחבירו חושב במחשבתו, כמו שידוע ומפורסם זה על הבעש\"ט ז\"ל<sup data-n=\"1\">125</sup>.",[["1","125","חנה אריאל (למהרי\"א הלוי עפּשטיין מהאָמיל תלמיד רבינו הזקן) מאמר השבת ז, א. וממשיך שם: \"כי באמת ענין החכמה הזאת . . שהחכם מקשר א\"ע עם נפש החושב [וזה פשוט וידוע שיש בכח החכמה לקשר נפש עם נפש מי שהוא רוצה אפילו שלא בפניו, ונקל זאת בעיני החכמים האמתיים לקשר נפשם עם נפש נמוכה במדרי' מהם כידוע], וע\"י התקשרות היטיב בעצמות נפש החושב הוא מתפשט וצופה בצפייתו אל מקום שמתפשטות לשם נפש החושב והולך דרך ההתפשטות ההוא ומרגיש את כל מה שחושב וכו'\" (הובא ב\"רשימות\" חוברת קנא)."]]],[300010860,"שלה\n\n<b>כמוהו לא הי'</b>\n<b>בדור</b> שלפנינו הבעש\"ט ז\"ל אשר כמוהו לא הי' מימות הראשונים פלאי פלאות ניסים היוצאים מהטבע היו נראים על ידו כאשר שמעתי מאאזמו\"ר נ\"ע<sup data-n=\"1\">126</sup> שהוא ותלמידו הה\"מ נ\"ע היו רואים מסוף העולם ועד סופו ממש בעין ראי' והיו אומרים מה שהיו רואים כאשר הי' נראה בעליל לתלמידיהם, והיינו ע\"י שהי' גלוי לפניהם אור שנברא ביום ראשון שהשי\"ת גנזו בתורה<sup data-n=\"2\">127</sup>, הנה כל אלה המופתים האמיתים מגלים גילוי א\"ס ב\"ה הבלתי בעל גבול<sup data-n=\"3\">128</sup>.",[["1","126","אדמו\"ר הזקן."],["2","127","ראה לקמן סימן שלח ואילך."],["3","128","ספר החקירה להצ\"צ סה, א. וממשיך שם: גם מזקיני נ\"ע שמענו עתידות קולע אל השערה. – נתבאר בלקו\"ש ח\"ד ע' 1137 ואילך. וראה ספר החקירה שם נ, סע\"א: והאריז\"ל והבעש\"ט והה\"מ שראו מסוף העולם עד סופו."]]],[300010861,"שלו\n\n<b>כתר חכמה בינה</b>\n<b>באחד</b> הפעמים – מספר הרה\"ח ר\"ל נ\"ע<sup data-n=\"1\">129</sup> – שהייתי על יחידות אצל כ\"ק אדמו\"ר<sup data-n=\"2\">130</sup> . . . אמר לי, לייבע דו טראַכסט מכח דעם בעש\"ט וואָס ווילסטו פרעגן, פרעג, ואמרתי באַ מיר איז עפּעס אָפּגעלייגט אַז דער בעש\"ט דער מעזריטשער מגיד און דער אַלטער רבי, איז כח\"ב פון חסידות<sup data-n=\"3\">131</sup>.\nכ\"ק אדמו\"ר השתנה בפני קדשו והתלהב במאד, ועמד מלא קומתו ואמר, דאָס איז אַזוי נאָר אין דעם כללות הגילוי מלמעלה, היינו אין דעם סדר התגלות תורת החסידות בדרך מלמעלה למטה, איז באַ אונז דער בעש\"ט דער מעזריטשער מגיד און דער רבי דער כח\"ב פון חסידות, און אַזוי איז במוחש בפּועל, דער סדר פון התגלות הבעש\"ט איז ווי דער סדר פון גילוי הכתר, מתעלם ומתגלה ובהתגלותו הוא כתר ומקיף עומק רום ועומק תחת כחדא, און אַזוי איז געווען דער סדר ההתגלות פון בעש\"ט תחלה נסתר ונעלם ואח\"כ התגלה ובהתגלותו איז דאָס געווען מקיף הכללי, וואָס ער איז סובב ומקיף עומק רום און עומק תחת כחדא, עליית הנשמה און אַ מופת בהשואה גמורה.\nדעם מגיד האָט דער בעש\"ט ניט גענומען ניט מיט מופתים און ניט מיט מקיפים, דער מגיד האָט געזוכט השכלה נקודת החכמה און אַז ער האָט דאָס געפונען באַ דעם בעש\"ט איז ער געוואָרן זיינער.\nווי דער סדר ההנהגה פון השגחה עליונה, אין דעם מקום המדריגות, אין סדר העבודה איז דער בעש\"ט דער מעזריטשער מגיד און דער רבי, חב\"ד, און האָט מסיים געווען מיט דעם פּסוק הוי'<sup data-n=\"4\">132</sup> וכו', הוי' אַז עס זאָל זיין דער דערהער פון שם הוי' אין עולם מיט הבנה וקליטה איז בחכמה יסד ארץ דער בעש\"ט, כונן שמים בתבונה איז דער מעזריטשער מגיד, בדעתו וואָס דאָס איז דער דעת פון דער גליא שבתורה וחסידות מיט דער עבודה שבלב במס\"נ בפּועל, תהומות יבקעו דאָס איז דער רבי, וואָס דורך דעם איז ושחקים אַלע רביים וואָס בעבודתם והדרכתם צורייבן זיי דעם לב אבן און מאַכן אַ לב בשר ירעפו טל ביז ביאת המשיח<sup data-n=\"5\">133</sup>.",[["1","129","ר' יהודה לייב האָפמאַן. ראה אודותו – ספר השיחות תרצ\"ו ע' 135. תרצ\"ט ע' 302. ועוד."],["2","130","מהר\"ש."],["3","131","דשני ענינים באדמו\"ר הזקן – א' מנשיאי תורת החסידות הכללית, ומייסד תורת חסידות חב\"ד. ויש לומר, שזהו החילוק בין שני האופנים בדרגות הנשיאים בספירות: (א) הבעש\"ט, הה\"מ ואדה\"ז – כח\"ב, (ב) הבעש\"ט והה\"מ – כתר (עתיק ואריך), אדה\"ז חכמה, אדמו\"ר האמצעי – בינה, והצ\"צ – דעת. – לקוטי שיחות חלק לה ע' 105 הערה 37."],["4","132","משלי ג, יט-כ."],["5","133","לקוטי דיבורים ח\"א לו, א ואילך."]]],[300010862,"שלז\n\n<b>דער</b> בעש\"ט און דער מגיד זיינען אין דער בחי' פון כתר, אין כתר איז פאַראַן עתיק און אריך; דער בעש\"ט איז בחי' עתיק און דער מגיד בחי' אריך<sup data-n=\"1\">134</sup>.",[["1","134","ספר השיחות תש\"ה ע' 60. וממשיך שם: הוד כ\"ק רבינו הזקן – חכ'*, הוד כ\"ק אדמו\"ר הרה\"ק האמצעי – בינה, הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ – דעת. דאָס האָב איך געהערט ברבים. ביחידות האָב איך געהערט ביז נצח והוד און ווייטער. – זאָגט אַ ניגון. ובספר השיחות תש\"ב ע' 19: מורנו הבעש\"ט והרב המגיד זיינען כתר דחסידות, עתיק ואריך. הוד כ\"ק רבינו הזקן חכמה, הוד כ\"ק אדמו\"ר האמצעי בינה, הוד כ\"ק אדמו\"ר הרה\"ק צמח צדק דעת. ביי דעם טאַטן – סיים הוד כ\"ק אאמו\"ר הרה\"ק – האָט דער עצמי'דיקער חב\"ד מאיר געווען אין אַלע עשר כחות, חב\"ד חג\"ת נהי\"מ. וראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' תטז: מורנו הבעש\"ט כתר דחסידות, המלאך עתיק, הרב המגיד ממעזריטש אריך, רבינו הזקן חכמה דתורת החסידות, רבינו האמצעי בינה, הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק דעת, ובהם ועל ידם התיסדה תורת ועבודת החסידות, והוד כ\"ק בניהם אדמור\"י חב\"ד המשיכו אור החב\"ד להאיר דרכי החסידי חב\"ד לדורותיהם בפנס אור בהיר.\nוראה ספר השיחות תרצ\"ו ע' 141. תרצ\"ז ע' 215. תרצ\"ט ע' 322.\n-----שולי הגליון-----\n*) <i>ראה לעיל סימן שלו בהערה</i>."]]],[300010863,"שלח\n\n<b>למעלה מזמן ומקום</b>\n<b>ומזה</b> יובן המעשה דבעש\"ט ז\"ל שהגיד לאדם א' שבא לשאול על בנו שהי' מרחוק ממנו מאות פרסאות ואמר שראה אותו ממש איך הוא עומד כעת בברעסלע והיינו ע\"י שקראו לפניו בזוהר ונפתח ונתגלה האור הגנוז שם שרואים בו מסוף העולם ועד סופו<sup data-n=\"1\">135</sup>.",[["1","135","מאמרי אדמו\"ר הזקן כתובים ח\"א ס\"ע רד ואילך. אוה\"ת שבועות ס\"ע רכא. וראה שיחת כ\"א אלול תשל\"ד. ש\"פ בראשית תשל\"ה."]]],[300010864,"שלט\n\n<b>וכידוע</b> סיפור הבעש\"ט ששאלוהו בענין טבעי הקשור עם שוורים, פתח הבעש\"ט ספר הזוהר וענה היכן נמצאים השוורים, ושאלוהו ע\"ז מהו קשר הענינים, וע\"ז ענה שאור שנברא ביום הראשון אדם מביט בו מסוף העולם ועד סופו<sup data-n=\"1\">136</sup>, ולאח\"ז גנזו לצדיקים<sup data-n=\"2\">137</sup> . . והיכן גנזו, בתורה<sup data-n=\"3\">138</sup> גנזו<sup data-n=\"4\">139</sup>.",[["1","136","חגיגה יב, א."],["2","137","ראה זח\"א מה, ב. מו, א."],["3","138","ראה זוהר חדש פה, א ואילך (וראה תנחומא נח ג). כתר שם טוב סימן פד. ועוד."],["4","139","ד\"ה זה היום כ\"ט אלול תשל\"ג (ספר המאמרים תשל\"ג ע' 484). וראה שיחות שבהערה 135."]]],[300010865,"שמ\n\n<b>ועד\"ז</b> הוא בזמן ומקום כשמאיר בהם הארה מבחי' שלמעלה מזמן ומקום אז הזמן ומקום בטלים כו' (וכידוע בהבעש\"ט ז\"ל אשר הזמן ומקום לא הי' מגביל ומעלים לפניו כלל וראה בהוה מה שיהי' במשך זמן וכן ראה מה שבריחוק מקום ממנו בראיית הדבר ממש כו', ואפשר י\"ל מה שא' שמואל לשאול אנכי הרואה<sup data-n=\"1\">140</sup> (דהנביא נק' רואה לפנים כו' ומה שנענש זהו על שאמר אנכי ולא אני כו') שהנביא רואה בעיניו ממש את הדבר ואין המקום מעלים לפניו וראה את האתונות כו', והיינו מצד גילוי בחי' למעלה מזמן ומקום בזמן ומקום כו', ובמדרי' זאת הי' הבעש\"ט ז\"ל<sup data-n=\"2\">141</sup>.",[["1","140","שמואל-א ט, יט."],["2","141","המשך תרס\"ו ס\"ע רכז."]]],[300010866,"שמא\n\n<b>והבעש\"ט</b> ז\"ל לא הי' המקום מסתיר אצלו כלל ומה שרחוק במקום ראה בראי' ממש (ולא בנבואה כו') וצ\"ל שהוא זיכך ותיקן המקום עד שהי' בטל ממש ולא הסתיר כלל מפני שלא הי' בבחי' יש כלל (כל' סש\"ב הנ\"ל) וכמו מקום ארון אינו מן המדה<sup data-n=\"1\">142</sup> שעם היותו בבחי' מקום הי' בטל בתכלית לגבי למעלה מן המקום כו', שהי' המקום בעצם מקום קדוש לית<sup data-n=\"2\">143</sup> דין אתר הדיוט<sup data-n=\"3\">144</sup>.",[["1","142","יומא כא, א."],["2","143","תרגום אונקלוס ויצא כח, יז."],["3","144","ספר המאמרים תרס\"ג ח\"א ע' נח."]]],[300010867,"שמב\n\n<b>נמצא</b> בחי' א' דבי\"ע כולל חלקים רבוא רבבות דעולם השפל ולכן בסקירה א' יוכללו עשרה או ט\"ו שנים ומזה מובן המעשה דבעש\"ט שצפה והשיג בר\"ה מה שהי' אח\"כ כידוע המעשה של גיסו ר' גרשון קוטעבר עם החכם באה\"ק שכתב לו הבעש\"ט כל המעשה טרם שהיתה בפועל והגם שלא היתה עלית נשמתו בכלל הקדום דא\"ק הנ\"ל אלא בהיכלות דיצירה מ\"מ הרי גם שם יוכל להיות נכללים ט\"ו שנים בסקירה אחת כנ\"ל<sup data-n=\"1\">145</sup>.",[["1","145","דרך מצותיך נט, א. וממשיך שם: ולכן הנה בר\"ה שנמשך בו חלק החיות על כל השנה שלכן נק' ראש כשם שהראש כולל חיות כל הגוף הנה כולל ג\"כ כל הזמן בסקירה א' וכן עד\"ז בר\"ח לגבי כל החודש. ומועתק בזה הערת כ\"ק אדמו\"ר זי\"ע (בסו\"ס דרך מצותיך ע' 404. ובהוצאת תנש\"א ושלאח\"ז – רח, א) אודות סיפור הנ\"ל:\nמ\"ש הבעש\"ט לגיסו ר\"ג קוטעוור: ראיתי שדנו אותך בהיכל אחד ורצו לדין אותך למיתה ח\"ו מפני שהעזת פניך נגד הרב אב\"ד, ורציתי לילך להיכל לטעון עבורך וסגרו ההיכל בעדי ולא יכולתי לכנוס שם. ואמרתי רבש\"ע הוא עשה לקנאתך. ויצא קול הניחו לו כי קנא קנאת ד' צבאות. ועכ\"ז פסקו לך שתהי' סומא חדש אחד וסומא חשוב כמת. ובכן מהיום והלאה לא תהי' קשה כ\"כ. ישראל בעש\"ט.\nוהשיב ר\"ג להבעש\"ט איני יודע מה אדון בך כי המעשה אמת, אבל אתפלא כי ראית שדנו אותי קודם המעשה כפי היום אשר נרשם על מכתבך.\nובדרוש אתה הראית [ביאורי הזוהר להצ\"צ ח\"א ע' רנח]: ומזה יובן המעשה דהבעש\"ט ז\"ל במכתבו לר\"ג קוטעבער איך שראה עליו קטרוג על שנידה חכם א' שלא כדין. וכתב לו ר\"ג יפה דברת אך שלא בזמנו דברת, כי המעשה הי' אחר שנכתב האגרת כו'. והשיב לו שאין אתה יודע איך רואים למעלה. דאף שבודאי בעליית הנשמה שלו לא הגיע לעלי' בכלל הקדום דא\"ק הכולל כל ההשתלשלות, כי גם באצילות נאמר כי לא יראני האדם וחי וגם הנבואה ממש הוא ע\"י התלבשות גמור דאצילות בבריאה או ביצירה כו', אלא עליות שלו הי' ביצירה וכמ\"ש בשע\"ק להרח\"ו בד' שנכנסו לפרדס היינו בהיכלות דיצירה, אך גם ביצירה יוכלל הכלל עשרה או טו שנים שלנו בבת אחת [גנזי נסתרות ח\"א ע' מב].\nוראה אוה\"ת תולדות קע, א: \"ובזה מובן מ\"ש הבעש\"ט ז\"ל לגיסו ר\"ג מקיטעב שבמשנה זו שלמד מבואר ב' מעשיות שאירעו אח\"כ כו'\". הובא בשיחת ש\"פ בהר-בחוקותי תשי\"ג ס\"ט (תורת מנחם – התוועדויות ח\"ח ע' 174 ואילך).\nוראה גם מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ע' שכא. ע' של. סה\"מ תרס\"ח ע' קפד. המשך תער\"ב ח\"ג ע' א'שמו. לקוטי שיחות חלק א ע' 50. חלק ב ע' 444."]]],[300010868,"שמג\n\n<b>\"מחשבות זרות\" שלו</b>\n<b>וכידוע</b> בשם הבעש\"ט ז\"ל שאמר דמח\"ז שלו בתפילה וכל היום פוגמי' יותר מכל העוונות משום דצ\"ג הנופלי' מעט ממדריגתם יותר קשה מפגם הרשעים בעוונות בפו\"מ<sup data-n=\"1\">146</sup>.",[["1","146","מאמרי אדמו\"ר האמצעי במדבר ח\"ד ע' א'תקצה. וראה מאמרי אדמו\"ר הזקן תקס\"ב ח\"א ע' רלה: פגם המחשבה דנשמות הצדיקים דברי' גדולה מפגם העשי' ברע גמור דנפש דעשי' כו' (וכמאמר הבעש\"ט והמגיד ז\"ל כו'). וראה עד\"ז בשם הרב המגיד – לקו\"ת בלק עד, ב. מאמרי אדמו\"ר הזקן תקס\"ב ח\"ב ע' תצח."]]],[300010869,"שדמ\n\n<b>וכידוע</b> בשם הבעש\"ט מעשה שאמר מכל מחשבה זרה שלו נולדו אנשים שלמים<sup data-n=\"1\">147</sup>.",[["1","147","מאמרי אדמו\"ר הזקן הקצרים ע' קמה. וממשיך שם: פי' דאף הפסולת מהרע שלו שהצדיק המופלג הוא נשמה וחיות לאנשים שפלים."]]],[300010870,"שדמ-א\n\n<b>מרה שחורה</b>\n<b>הרחיק</b> מאד הבעש\"ט את השחורים, מפני שמקורם ממקום גבוה דנפלו כו', קשה להגביהם<sup data-n=\"1\">148</sup>.",[["1","148","מאמרי אדמו\"ר הזקן הקצרים ע' תמח. ושם לפנ\"ז: \"כל מי שאינו בוכה בימים נוראים אין נשמתו שלימה. בזהר איתא על ר\"ע כשהגיע ר\"א הגדול לפרש לו פסוק סמכוני באשישות לא יכול ר\"ע למסבל וזלגו עיניו דמעות ולכן הרחיק\" ההמשך בפנים."]]],[300010871,"שמה\n\n<b>משה רבינו</b>\n<b>מורנו</b> הקדוש הבעש\"ט נ\"ע איז דער משה רבינו ע\"ה פון תורת החסידות הכללית, דאָס הייסט אַז אַזוי ווי משה רבינו ע\"ה דער בחיר הוי', אַז על ידו איז נתגלה געוואָרען תורתנו הקדושה, אָט אַזוי איז מורנו הבעש\"ט נ\"ע דער בחיר הוי' אַז על ידו איז נתגלה תורת החסידות הכללית.\nאין מדרש<sup data-n=\"1\">149</sup> אויפן פּסוק<sup data-n=\"2\">150</sup> ומשה הי' רועה שטייט הוי' צדיק יבחן<sup data-n=\"3\">151</sup>, ובמה הוא בוחנו במרעה צאן, און רז\"ל{149} דערציילען אונז די מעשה וואָס עס האָט געטראָפען באַ משה ע\"ה בעת ער האָט גיפיטערט צאן יתרו, וואָס פון דער מעשה זעהט מען אַרויס די מדות טובות וואָס משה רבינו ע\"ה האָט געהאַט.\nמורנו הבעש\"ט נ\"ע איז בעוואוסט מיט זיין אהבת ישראל, ער האָט געזעהן אין יעדער אידן אַ מעלה און אין יעדער פּועל פון א אידן הן אַ מצוה אָדער אַ מדה טובה האָט ער געזעהן דעם אמת'ן ליכטיקען שיין.\nמורנו הבעש\"ט קוקט מיט זיינע ליכטיקע אויגן אין דעם פינסטערן גלות, זעהט ווי אידן זיינען מקיים תורה און מצוות מיט גרויס מסירות נפש און פּיין, ווערן געדריקט און גערודפ'ט פון פערשידענע שלעכטע מענשן.\nמורנו הבעש\"ט זעהט ווי אידן זיינען מקיים דעם בקולו של הקב\"ה תשמעו מיט מס\"נ, ווערט באַ איהם די שאלה פאַר וואָס קומט ניט משיח, גואל צדק, און וויל בעשליסן אַז ער מיט דער חבריא קדישא, הצדיקים הנסתרים נ\"ע זאָלין בריינגען משיח'ן.\nעס איז בעוואוסט די פערשידענע אסיפות הצדיקים הנסתרים וואָס זיינען געווען מזמן לזמן בימי מורנו הבעש\"ט, און די כמה מיני התעסקות און שתדלנות וואָס זיי פלעגען טאָהן בנוגע דער מצב הרוחני און אויך דעם מצב הגשמי פאַר דעם כלל ישראל.\nאון אין יענער צייט איז געווען די עליית הנשמה של מורנו הבעש\"ט וואָס ער איז געווען אין היכל המשיח און האָט געפרעגט אימתי קאתי מר.\nדער אימתי וואָס דער בעש\"ט נ\"ע פרעגט באַ משיח'ן איז דאָס ווי דער מאמר אם לא עכשיו אימתי וואָס עס שטייט אין אבות (פ\"א מי\"ד).\nדאָס הייסט, אַז דער בעש\"ט רעדט מיט משיח'ן, אין דעם ענין פון דער גמרא סנהדרין, וואו משיח ענטפערט אַז היום אם בקולו של הקב\"ה תשמעו, און אויף דעם פרעגט דער בעש\"ט עס איז דאָך ב\"ה בקולו תשמעו.\nאון אויף דערויף ענטפערט משיח דעם בעש\"ט לכשיפוצו מעיינותיך חוצה, ברחבות פּלגי מים (משלי ה' ט\"ז) יפוצו מעיינותיך חוצה, סוף שתקנה תלמידים ותורה הוראות ברבים, ויצא לך שם, רש\"י, ברחבות, עיר תפוצנה פלגי מימיך, רש\"י.\nחסידות<sup data-n=\"4\">152</sup> ווייס צו מאַכן אַ חילוק פון אַ מעין און נהר, נהר הוא התפּשטות לאורך ורוחב ומחזיק שטח גדול, והמים בו בריבוי והילוכם הוא בשפע ורעש גדול, והמעין הוא נמשך כגיד בכווץ תפיסת מקום שאינו תופס מקום גם לעצמו, ומימיו נובעין טיפּין טיפּין.\nחוצה<sup data-n=\"5\">153</sup> הייסט דאָך אין דרויסען, ד. ה. ניט אין דעם מקום המוכשר<sup data-n=\"6\">154</sup>, וואָרום דער מקום המוכשר איז דאָך ניט קיין חוצה, ער איז דאָך דער ריכטיגער מקום המוכשר, וואָדען אויב ער איז אַ חוצה, דאָס הייסט אַז ער איז ניט קיין מקום מוכשר, איז ווי איז דאָרטן דער אָרט פון אַ מעין, איז דאָך דער פּסוק זעהר ניט פאַרשטאַנדיק, עס איז דאָך סותר איינע די אַנדערע, איז דאָס אַ מעין פאַרוואָס רופט מען חוצה? איז דאָס חוצה, ווי קומט אַהין אַ מעין, וואָדען עס איז ביידע זאַכן, איז ווי איז ביידע זאַכן?\nמפרשים<sup data-n=\"7\">155</sup> טייטשן דעם פּסוק יפוצו מעיינותיך חוצה, עס וועלן אַזוי שטאַרק זיין די וואָס קומען אַרויס פון דיינע קוועלן אַז זיי וועלן זיך צו שפּרייטן אפילו חוצה ביז אַז ברחבות אפילו אין די גאַסן וועלן זיין פּלגי מים, און חאָטש עס וועט זיין חוצה גאָר אין דרויסן, פונדעסטוועגן וועט מען וויסן אַז דאָס קומט פון דיינע מעיינות.\nפון משיח'ס ענטפער אויף דעם בעש\"ט'ס פראַגע פאַרשטעהט מען, אַז תורת רבינו הבעש\"ט נ\"ע, און די התגלות שכל אלקי, וואָס דער בעש\"ט ותלמידיו ותלמידי תלמידיו אבותינו רבותינו הק' נ\"ע זי\"ע האָבן אונז געגעבן, האָט דאָס אַ שייכות צו ביאת המשיח (יבא בב\"א)<sup data-n=\"8\">156</sup>.",[["1","149","שמו\"ר פ\"ב, ב."],["2","150","שמות ג, א."],["3","151","תהלים יא, ה."],["4","152","ראה לקו\"ת שה\"ש לט, א ואילך. ובכ\"מ."],["5","153","ראה ספר השיחות תורת שלום ע' 113."],["6","154","ראה לקוטי שיחות חלק טו ע' 287. וראה שם ע' 282. ועוד."],["7","155","ראה ראב\"ע ומצו\"ד עה\"פ."],["8","156","לקוטי דיבורים ח\"ב שי, ב ואילך. ספר השיחות תר\"ץ ע' 111 ואילך. ושם שט, סע\"ב ואילך. ספר השיחות שם: דער בעש\"ט נ\"ע פרעגט באַ משיח'ן אימתי קאתי מר, אין פלוג האָט דאָך קיין אָרט ניט די שאלה עס איז דאָך אַ קלאָר אָפענע גמרא (סנהדרין דצ\"ח ע\"א) ר' יהושע בן לוי האָט זעך געטראָפען מיט אלי' הנביא אין דער מערה פון ר' שמעון בן יוחאי פרעגט ריב\"ל באַ אליהו'ן ווען וועט קומען משיח, ענטפערט אלי' ר' יהושע בן לוי'ן, גיי פרעג באַ איהם אַליין, פרעגט ריב\"ל וואו קאָן איך איהם טרעפין, האָט איהם אלי' געזאָגט דעם אָרט אין גן עדן, וואו משיח זיצט.\nווי עס איז ניכר איז באַ ריב\"ל דער אָרט געווען גוט בעקאַנט און די וועג אַהין אַדורך גיטראָטענע, אַז ער איז געקומען אַהין איז נאָך די סימנים וואָס אליהו האָט איהם גיגעבן האָט ער דערקענט ווער איז משיח, פרעגט ריב\"ל באַ משיח'ן לאימת אתי מר, צו וואָס פאַר אַ צייט וועט קומען דער האַר, ענטפערט משיח, היום היינט.\nריב\"ל איז גיווען זייער צופרידן מיט דעם ענטפער און געגאַנגען צוריק זעהן זיך מיט אליהו'ן דערווייל איז דורך געגאַנגען דער טאָג, און משיח איז ניט געקומען, איז ריב\"ל געוואָרן פאַרביטערט, אַז ער איז געקומען צו אליהו'ן, פרעגט איהם אליהו וואָס האָט דיר משיח געזאָגט.\nריב\"ל זייענדיק זייער פאַרביטערט און פאַר עגמת נפש פון דעם וואָס משיח איז ניט געקומען דעם טאָג, זאָגט ער אליהו'ן אַז משיח האָט איהם געענטפערט היום קומט ער, דער טאָג איז דורך און משיח איז ניט געקומען.\nאליהו הנביא ערקלערט ר' יהושע בן לוי דעם ריכטיקן זין פון משיח'ס ענטפער – אויף ריב\"ל פראַגע צו וואָס פאַר אַ צייט וועט קומען דער האַר – היום אם בקולי תשמעו.\nאין דעם סיפּור המעשה פון ריב\"ל מיט אליהו'ן זעהן מיר קלאָהר און דייטלעך אַז דער זין פון ביאת המשיח (בב\"א) איז פאַרבונדען מיט דעם היום אם בקולו של הקב\"ה תשמעו, וואָס נאָך דעם קלאָהרין ענטפער איז דאָך ניט מובן די שאלה פון בעש\"ט אימתי קאתי מר, עס איז דאָך אַ גמרא מפורשת, אַז ביום אשר בקולו של הקב\"ה תשמעו, קומט משיח גואל צדק, היינט וואָס פרעגט דער בעש\"ט נ\"ע אימתי קאתי מר [ההמשך בפנים. וממשיך שם:] יעדער חכמה, אויך די חכמה פון שכל אלקי, האָט איהר שטייגער בסדר ואופן השכלתה והשגחתה על פי דער הבנה און הסברה פון חסידות, איז דער יחס און שייכות פון אַ זאַך צו נאָך אַ זאַך, כמו אָט ווי דאָ, די שייכות פון תורת הבעש\"ט נ\"ע און ביאת המשיח, מוז איין זאַך זיין אַ אור, און די צווייטע זאַך אַ כלי צו דעם אור אין אור וכלי, איז דאָך פון דער כלי קאָן מען פאַרשטעהן וואָס איז דער אור וואָס איז שייכות צו דער כלי און פון דעם אור קאָן מען פאַרשטעהן וואָס פאַר אַ כלי מ'דאַרף האָבען צו אַזאַ אור, וואָרום אור וכלי האָבען דאָך אַ שייכות זה לזה . . .\nאין משיח'ס ענטפער וואָס ער ענטפערט אויף דער פראַגע פון מורנו הבעש\"ט נ\"ע אימתי קאתי מר, לכשיפוצו מעיינותיך חוצה, איז קלאָהר פאַרשטאַנדיג, אַז תורת הבעש\"ט נ\"ע איז דאָס די כלי צו דעם אור פון גילוי המשיח, בב\"א. וע\"ש בארוכה.\nוראה שם שכח, א ואילך. ספר השיחות שם ע' 130:\nאון דאָס איז דער ענטפער פון משיח'ן, לכשיפוצו מעינותיך חוצה, אָט די והאמונה וואָס די זיידעס און די טאַטעס האָבען געלאָזט בירושה זייערע קינדער און אייניקלעך, איז אין דעם גלות שטראָם צעשפּרייט און צעזייט געוואָרען במרחבי תבל און מדינות שונות.\nאון אויך באַ אַזעלכע וואָס איבער פערשידענע סבות זיינען זיי פאַרשטויסען געוועאָרן אין חוצה. אַז מען איז אָפּגעריסן פון אידישקייט, אַז עס רעדט זיך ניט וועגען חסידות און הנהגות פון חסידים, עס רעדט זיך מכח טהרת המשפּחה, הנחת תפילין, שמירת שבת, מאכלות כשרות.\nאַלס איינער פון גזע ובא כח הוד כ\"ק אבותינו רבותינו הקדושים זצוקללה\"ה נבג\"מ זי\"ע פאַל איך ביי זיך ניט אַראָפּ מיט די גזע החסידים וואָס זיינען אַוועק חוצה, וויסנדיק אַז אין זיי פליסט די בלוט פון זייערע עלטערן און אור עלטערן.\nאון דאָס זאָגט משיח, אַז אין דעם חוצה איז פאַראַן מעינותיך, די האָבען אין זיך אויך די גרויסע ירושה פון זייערע זיידעס און טאַטעס און אין זיי קאָן זיך אויפוועקען די פּינטעלע פון דעם והאמונה, וואָס זייערע עלטערען האָבען זיך מוסר נפש געווען.\nמשיח'ס ענטפער איז, אַז יפוצו מעינותיך חוצה, די תורת רבינו הבעש\"ט נ\"ע און די עבודה טהורה בבירור וזיכוך המדות וועט זיך סוף כל סוף צעשפּרייטען, אַז אַלע וועלען דערקאָנען דעם אמת, און אויך אפילו די וואָס געפינען זיך אין חוצה איז דער מסירות נפש פון זייערע עלטערען און זיידעס וועט זיי אויפוועקען, אַז זיי זאָלען זיך בענוצען אין פערגעניגען פון הנהגות טובות מיט די קלאָהר ריינע ירושה, וואָס זייערע זיידעס און טאַטעס האָבן זיי איבערגעלאָזען.\nושם רפו, ב ואילך. ספר השיחות שם ע' 84 ואילך:\nאין דער עלית הנשמה פון רבינו הבעש\"ט בשנת תק\"ז, איז ער געווען אין היכל המשיח, האָט מורנו הבעש\"ט גיפרעגט באַ משיח'ן, אימתי קאתי מר, האָט משיח געענטפערט, לכשיפוצו מעיינותיך חוצה.\nשאלה ותשובה, איז דאָס אַ געוויסע השכלה און השגה געביידע, אין יעדער געביידע איז פאַראַן דער עצם הבנין, און דער תוך פון דעם בנין, וואָס אַזוי איז אויך אין דער השכלה געביידע, די שאלה איז דער בנין, אין שכל וועלט הייסט דאָס די השכלה, און די תשובה הייסט דער תוך, די בעלייכטונג פון דעם בנין, וואָס אין שכל וועלט הייסט דאָס די השגה, וואָס די ביידע – השכלה און השגה – שטאַרקן און בעלייכטען איינע די אַנדערע.\nהשכלה איז דער גרונדשטיין און דער וואָרצל פון השגה, און השגה איז די רעזידענץ פּאַלאַץ פון השכלה.\nמיט דעם וועט מען פאַרשטיין די טיפקייט פון דעם מאמר החכם, שאלת חכם חצי תשובה*, און שאלות החכמה חצי החכמה**.\nדי צוויי נוסחאות א) שאלת חכם חצי תשובה – די פראַגע ווי אַ קלוגער פרעגט איז דער אופן פון דער פראַגע אַליין אַ האַלבער ענטפער – ב) שאלות החכמה חצי החכמה – די וויסנשאַפטליכע פראַגעס זיינען אַליין אַ האַלבער טייל פון וויסענשאַפט. –\nאיז דייטלעך קלאָר אַז די צוויי נוסחאות איז דאָס צוויי בעזונדערע השכלה אינהאַלטן, וואָס יעדע איינע פון זיי האָט אַ ברייטע פערשטאַנדיקע ערקלערונג מיט אַ געוויסע בעדייטונג, אָבער איצטער וועלען מיר זיך ניט פערטיפן אין דעם, מיר וועלן מער ניט ווי לערנען פּירוש המלות.\nאין דעם וואָרט אַז שאלת חכם חצי תשובה, איז פאַראַן אַ מעלה און אַ חסרון, די מעלה איז, וואָס עס איז אַ חצי תשובה, און דער חסרון איז, וואָס עס איז מער ניט ווי אַ חצי תשובה, אָבער דאָס בעווייזט אויף דער התאחדות פון השכלה והשגה, השכלה איז דער מקור האור דהשגה, און השגה בעלייכט די השכלה.\nאַז דער בעש\"ט נ\"ע האָט געפרעגט משיח'ן, און משיח האָט געענטפערט, הייסט דאָס אַז אין דעם ענין פון ביאת המשיח, איז שאלת הבעש\"ט נ\"ע די השכלה, און תשובת משיח די השגה.\nדי השכלה איז, אימתי קאתי מר, ווען קומט משיח און די השגה, וואָס הייסט דער פאַרשטאַנד, איז לכשיפוצו מעיינותיך חוצה, וואָס עס האָט אַ צווייענדיקע בעדייטונג, א) אַז עס וועלן זיך צושפּרייטן דיינע קוועלן אין דרויסן ב) און אַז דיינע דרויסענדיקע קוועלן וועלן זיך צושפּרייטען.\nווי געזאָגט, אַז אַ שאלה ותשובה, איז די שאלה דער בנין, און די תשובה איז די בעלייכטונג פון דעם בנין, אין דעם בעש\"ט'ס נ\"ע שאלה, די השכלה פון דעם בנין ביאת המשיח בב\"א און די תשובה פון משיח'ן, די בעלייכטונג אין דעם בנין ביאת המשיח בב\"א, דאָס מיינט דעם פאַרשטאַנד. ועיי\"ש בארוכה.\n– בכהנ\"ל ראה גם לקוטי שיחות ח\"ד ע' 20-1120 ובהערות שם. ע' 1303. ח\"י ע' 243 ואילך. חט\"ו ע' 281 ואילך. וש\"נ.\n-----שולי הגליון-----\n*) <i>מובא בספר ר\"ש בן גבירול</i>.\n**) <i>מובא במבחר הפנינים שערי החכמה</i>."]]],[300010872,"שמו\n\n<b>נוני ימא</b>\n<b>יש</b> ב' מיני צדיקים הא' אותן שהם בסתר שעבודתם ברוחניות, פי' בכוונת הלב לייחד יחודים עליונים ובבחינת עליות, וכגון רבי שמעון בן יוחאי כשהי' במערה . . וכן האריז\"ל הי' ג\"כ בבחי' זו . . [וכן הבעל שם טוב]<sup data-n=\"1\">157</sup>.",[["1","157","לקוטי תורה שמיני יח, א ובהגהת כ\"ק אדמו\"ר הצ\"צ – הובא בהגהות כ\"ק אדמו\"ר מהורש\"ב בהוספות ללקו\"ת שם יח, ב. וראה גם ד\"ה שלח לך תשי\"א (ספר המאמרים תשי\"א ע' 75. תורת מנחם – התוועדויות ח\"ג ע' 165)."]]],[300010873,"שמז\n\n<b>יש</b> בכל דור ודור כת הצדיקים הללו שנק' בני עלי' מבחי' עלמא דאתכסייא ונק' נוני ימא (כמו האריז\"ל וחביריו בדורו והבעש\"ט ז\"ל וחביריו בדורו וכך בכל דור ודור)<sup data-n=\"1\">158</sup>.",[["1","158","מאמרי אדמו\"ר הזקן על מארז\"ל ע' קמה."]]],[300010874,"שמח\n\n<b>פעולתו בדצ\"ח</b>\n<b>הרב</b> המגיד נ\"ע הי' יכול להמשיך יר\"ע בתינוק בן יומו כו' והבעש\"ט הי' יכול להמשיך גם בדומם כו'<sup data-n=\"1\">159</sup>.",[["1","159","בית רבי סוף ח\"א. ראה לקוטי שיחות חלק ו ע' 285: \"עצמיות ענינו של הבעש\"ט, לעורר את העצם\", ובהערה שם: בזה יש להסביר, בדרך אפשר, פתגם רבנו הזקן [ההמשך בפנים]."]]],[300010875,"שמט\n\n<b>בגלל</b> עבודתו – לקרב את כולם [ועד שהי' מקרב גם אינם יהודים ופחותי הערך שבהם, וכידוע שהראה קירוב ואהבה לגזלנים, ויתירה מזו: שאהבתו היתה גם לחי וצומח], זכה להמשיך גילוי אלקות גם בחי [כידוע הסיפור שבעת תפלתו הרי העיזים שראו אותו נעמדו על רגליהם – שזהו גילוי בסוג החי], ובצומח, ואפילו גם בדומם [כידוע<sup data-n=\"1\">160</sup> שהציצית של הבעש\"ט התנועעו מעצמם<sup data-n=\"2\">161</sup> – שזהו גילוי בסוג הדומם]<sup data-n=\"3\">162</sup>.",[["1","160","ראה דברי שלום פ' תבוא."],["2","161","ראה מאמר ד\"ה כי תבוא תשד\"מ: וכנודע סיפור החסידים, שאצל הבעש\"ט נ\"ע היו הציצית שבטליתו מתנועעות. דהחידוש שבזה הוא, דהגם שכל ישראל ע\"י שלובשים ציצית מקיימים את המצוה, שעי\"ז ממשיכים בה חיות וכו', הנה אצל הבעש\"ט נ\"ע הי' זה נראה בגלוי בהציצית, שהציצית הגשמיים התנועעו."],["3","162","שיחת יום ב' דחג הסוכות תשכ\"ג."]]],[300010876,"שנ\n\n<b>אין</b> דעם זמן ווען דער בעש\"ט נ\"ע איז געוועזען אַ נסתר, איז זיין הנהגה אויך געוועזן ווי אַ נסתר. די מעלת רוממות והפלאת נשמת הבעש\"ט האָבן דערהערט אפילו ציגן, זיי האָבן זיך אויפגעשטעלט אויף די אונטערשטע פיס, און די אויבערשטע פיס האָבען זיי געהאַלטן אין די הויך בקומה זקופה, ווי אַ אדם. דער בעש\"ט האָט ממשיך געוועזן אין זיי ווי מצד זייער שרש ווי זיי זיינען למעלה, אָבער למטה זיינען זיי געבליבען ציגן, חאָטש בע\"ש'סקע ציגן וואָס באַ זיי איז געוועזן אַ הבדל פון חצי התחתון ביז חצי העליון, און עס האָט זיך דערהערט באַ זיי מעלת העליון על התחתון, ניט ווי באַ אַנדערע וואָס באַ זיי איז דער תחתון גלייך ווי דער עליון – אָבער דאָך ציגן<sup data-n=\"1\">163</sup>.",[["1","163","ספר השיחות תש\"ט ע' 284."]]],[300010877,"שנא\n\n<b>עס</b> איז דאָך ידוע דער סיפור, אז ביי דעם בעש\"ט – בעת תפלת קבלת שבת – פלעגען זיך די ציגן אויפשטעלען \"דובאם\" (שהגביהו רגליהם שמלפנים)<sup data-n=\"1\">164</sup>.",[["1","164","שם ע' 279. וממשיך שם: \"דאָס איז אַ ציור, ווי מיר האָבען דעמאָלסט געהערט דעם וואָרט פון טאַטען, טאַקע ציגען אָבער אויפגעהויבען. כי, הלא בעזים יש פנים ואחור אלא כשהולכים כרגיל אז הכל בשוה, משא\"כ כשמגביהים את רגליהם שלפניהם, אז ניכר הפנים שבהם\".\nבהנחה אחרת משיחה הנ\"ל: \"אין תרנ\"ט זיינען מיר געזעסן ביים טאַטן און ער האָט געזאָגט [. . .] און מיר זיינען דעמאָלט געווען ווי די ציגען, כידוע הסיפור אַז ווען דער בעש\"ט האָט געדאַווענט האָבן זיך די ציגען אויסגעשטעלט, הגם ביי ציגען איז פניהם כאחורם בשוה, נאר אז זיי האבן זיך געשטעלט איז ניכר געווען [אצלם] הפנים. פון דעם קען מען פאַרשטיין ווי מען האָט געהערט אַ וואָרט פון רבי'ן, מען איז געווען ווי ציגען, דער וואָרט האָט פאָרט געהויבן. ובד\"ה הנה ישכיל עבדי תשל\"ב (ספר המאמרים תשל\"ב ע' 154): פעם אחת כשאמר [הבעש\"ט] קבלת שבת בשדה הרי העיזים שבשדה שראו אותו נעמדו על רגליהם, שזהו פעולה בדרך ראי'\"."]]],[300010878,"שנא-א\n\n<b>פרנסה, כלי לפרנסה</b>\n<b>וכמסופר</b> אויף בעש\"ט – ותוכנו – אַז ער האָט אַמאָל געזאָגט צו איינעם אַז ער דאַרף האָבן אַ סכום געלט, און גלייך (לאחרי אמירתו) איז ער אַוועקגעגאַנגען. יענער איז אים נאָכגעלאָפן מיט דעם סכום און געזאָגט צו אים: ווען איר וואָלט צוגעוואַרט אַ וויילע, וואָלט איך אַייך דאָך געגעבן די געלט גלייך אויפן אָרט? האָט אים דער בעש\"ט געענטפערט, אַז דער אויבערשטער האָט געהייסן \"בכל אשר תעשה\" – האָט ער געזאָגט אַז ער דאַרף האָבן דעם סכום. וואַרטן אויף דעם – איז ער פאַרנומען מיט בעסערע זאַכן<sup data-n=\"1\">165</sup>.",[["1","165","לקו\"ש ח\"ה ע' 344. ושם לפנ\"ז: אויפן פּסוק וברכך הוי' אלקיך בכל אשר תעשה, שטייט אין חסידות [מצות תגלחת מצורע (מספר המצוות להצמח צדק) פ\"ב ואילך. קונטרס ומעין מאמר יז. כג ואילך. ובכ\"מ], אַז אַ איד דאַרף מאַכן כלים צו פּרנסה, כלים בדרך הטבע, וואָס אין זיי זאָל אַראָפּקומען ברכת הוי'. אעפּ\"כ, כאָטש מען דאַרף טאַקע מאַכן כלים, דאַרף מען אָבער וויסן אַז ניט דאָס איז דער עיקר, ס'איז ניט מער ווי כלים, ובמילא דאַרף מען ניט זיין מושקע (פאַרטרונקען און פאַרזונקען) אין דעם. (ופּשוט, אַז די כלים דאַרפן זיין עפּ\"י תורת הוי', ער זאָל זיך אויסהיטן משמץ אונאה וכו', בכדי זיי זאָלן זיין כלים ראוים לברכת הוי').\nוויפל איז ער פאַרנומען אין עשיית הכלים? איז עס תלוי אין אים אַליין, ווי ער שטעלט זיך אַוועק (ולא ברשיעי, ח\"ו, עסקינן): ער קען זיך איינשטעלן אין אַן אופן, אַז ער זאָל זיין מושקע אַ גאַנצן טאָג אין עסק ביז אַז עס בלייבט קוים צייט אויף פרק אחד שחרית ופרק אחד ערבית, און ער קען זיך אַיינשטעלן אין אַן אופן, אַז אין דעם עסק זאָל ער טאָן נאָר אויף יוצא זיין דעם \"תעשה\", און כל היום איז – תורתו אומנתו. וואָרום וויבאַלד אַז דער \"בכל אשר תעשה\" איז נאָר אַ כלי, איז דאָך די כמות שבזה ניט אַן עיקר."]]],[300010879,"שנב\n\n<b>קין</b>\n<b>יש</b> סימנים להכיר אותם שמסט' דקין או מסט' דהבל כמ\"ש בספר הכוונות<sup data-n=\"1\">166</sup> כאשר באה\"ר מעוטף בטלית מימין לשמאל ומשמאל לימין הוא מבחי' הבל וכאשר דרכו וטבעו להקפיל ב' צדדי טליתו על ב' כתיפיו הוא בחי' קין כו' (והבעש\"ט הי' דרכו לקפל טליתו על כתפו ואפשר הי' מבחי' קין)<sup data-n=\"2\">167</sup>.",[["1","166","ראה פרי עץ חיים שער הק\"ש פ\"ג. מ\"ח מס' תפלת הבריאה פ\"ג מ\"ג ומ\"ד."],["2","167","מאמרי אדמו\"ר הזקן הקצרים ע' מח. ועד\"ז במאמרי אדמו\"ר הזקן תקע\"א ע' קכא."]]],[300010880,"שנג\n\n<b>רוממותו כמלך</b>\n<b>רבינו</b> הזקן אמר פעם: ווען דער רבי האָט געוואָלט מצייר זיין די רוממות פון זיידן (הבעש\"ט), אמר: כי רוממות מלך אדיר, הוא כלא נגד די רוממות פון דעם רבי'ן. און אַז ער האָט גערעדט וועגן דעם ביטול פון בעש\"ט, אמר: כי איש עני מדוכא השפל ונבזה ביותר בעיני עצמו אינו בערך לגבי הביטול של הבעש\"ט. וכשסיפר זה רבינו הזקן אמר: הערט אידן וואָס דער רבי האָט געזאָגט: דאָס איז דער ענין אוא\"ס למעלה מעלה עד אין קץ ולמטה מטה עד אין תכלית<sup data-n=\"1\">168</sup>. און האָט זיך פאַרקייקלט אין דביקות זמן מרובה<sup data-n=\"2\">169</sup>.",[["1","168","ראה תיקוני זוהר תיקון יט (מ, ב). שם סוף תיקון נז. זוהר חדש יתרו לד, סע\"ג. ספר הערכים-חב\"ד ח\"ד ערך אוא\"ס (ד) ע' שסה ואילך. וש\"נ."],["2","169","ספר השיחות תרצ\"ו ע' 134."]]],[300010881,"שנד\n\n<b>משה</b> דוד און דער בעש\"ט זיינען געווען יעדערער א נשיא ומלך . . דעריבער געפינט מען ביי זיי (נוסף אויף עשירות אין גשמיות<sup data-n=\"1\">170</sup> – אויך) ממשלה ושליטה אויף טבע – ביי זיי איז געווען אַ הנהגה שלמעלה מן הטבע<sup data-n=\"2\">171</sup>.\n**********",[["1","170","משה – נדרים לח, א. דוד – ראה דברי הימים-א כט, ב ואילך (ועיין רמב\"ם הל' מלכים פ\"ג ה\"ד ובכס\"מ שם). הבעש\"ט – כמפורסם בסיפורי הבעש\"ט."],["2","171","לקוטי שיחות חלק יח ע' 37."]]],[300010882,"שנה\n\n<b>פעולתו אשר עבד בה</b>\n<b>אבות</b>\n<b>וענין</b> גילוי הבעש\"ט והה\"מ היו הכנה לגילוי עצם פנימיות התורה שנתגלה על ידי רבינו הזקן – בדוגמת עבודת האבות (ריחות<sup data-n=\"1\">172</sup>) שהיו הכנה לגילוי העצמות דמתן תורה<sup data-n=\"2\">173</sup>.",[["1","172","שהש\"ר פ\"א, א (ג). ראה סה\"מ תרע\"ח ע' קסד ואילך. ועוד."],["2","173","ספר השיחות תרפ\"ח ע' 18 ואילך – הועתק בלקוטי שיחות ח\"ד ע' 1139 וחט\"ז ע' 56."]]],[300010883,"שנו\n\n<b>אברהם אבינו</b>\n<b>דער</b> אַלטער רבי, האָט געזאָגט: \"דער זיידע, דער בעש\"ט נ\"ע, איז דער אברהם אבינו פון חסידות, אויף אברהם אבינו שטייט<sup data-n=\"1\">174</sup>, אַז ער איז געווען אַ נדיב בממונו, בגופו ובנפשו, אברהם אבינו האָט זיך מוסר נפש געווען מקרב צו זיין גאָר אַ פּשוט'ן מענטשן צו געטליכקייט, און אַזוי האָט געטאָן דער זיידע, דער בעש\"ט נ\"ע, ער איז געווען אַ נדיב בממונו, בגופו ובנפשו, ער האָט זיך מוסר נפש געווען צוליב מקרב זיין אַ פּשוט'ן אידן.\n\"אויף אברהם אבינו – זאָגט דער זיידע צום פאָטער<sup data-n=\"2\">175</sup> – בשם זיין זיידן, דעם אַלטן רבי'ן – שטייט<sup data-n=\"3\">176</sup> עד אברהם הי' העולם מתנהג באפילה בא אברהם התחיל להאיר, ביז אברהם אבינו זיינען דאָך אויך געווען גרויסע צדיקים, אָבער עס זיינען אַלץ געווען אפילה צדיקים. אברהם אבינו איז געווען דער ערשטער צדיק וואָס התחיל להאיר. ביז דעם זיידן דעם בעש\"ט נ\"ע איז די וועלט געווען אַ בית אפל. ביי די בני תורה איז געווען אור במושבותם, אָבער ביי די מיטעלע בעלי בתים בכלל און ביי די פּשוט'ע אידן בפרט איז די וועלט געווען אַ בית אפל, איז געקומען דער זיידע דער בעש\"ט נ\"ע און התחיל להאיר\".\n\"דער זיידע, דער בעש\"ט נ\"ע, האָט געמאַכט פענסטער אין דעם בית אפל פון דער וועלט. אַ אמן איז אַ פענסטער, אַ אמן יהא שמי' רבא איז אַ פענסטער, אַ ברוך הוא וברוך שמו איז אַ פענסטער און מיט דער שיטה אמיתית אַז דער דאַוונען און אמירת תהלים פון די פּשוט'ע אידן איז זייער חביב ביי השי\"ת האָט ער באַלויכטן דעם בית אפל פון דער וועלט מיט דעם אור האותיות פון תורה, תפלה און תהלים\"<sup data-n=\"4\">177</sup>.",[["1","174","אורחות צדיקים שער יז (שער הנדיבות). נתבאר לעיל סימן קכז."],["2","175","כ\"ק אדמו\"ר הצ\"צ לכ\"ק אדמו\"ר מהר\"ש."],["3","176","ראה ב\"ר פ\"ב, ב. שמו\"ר פט\"ו, כו. וראה לעיל סימן קכה."],["4","177","לקוטי דיבורים ח\"ד תשצא, ב ואילך. ספר השיחות תש\"ב ע' 147."]]],[300010884,"שנז\n\n<b>אהבת ישראל</b>\n<b>דער</b> בעש\"ט האָט מגלה געווען דעם ענין פון התקשרות אהבת השם, אהבת התורה ואהבת ישראל<sup data-n=\"1\">178</sup>.",[["1","178","לקוטי דיבורים ח\"ג תקיד, ב ואילך. ספר השיחות תש\"ח ע' 225 (הועתק בספר המאמרים תש\"ט ע' ב). וממשיך שם: דער מעזריטשער מגיד האָט מגלה געווען די השכלה והשגה אין דער התחברות פון די דריי אהבות מיט דעם ביאור פּנימי פון די דריי אופני אהבה בכל לבבך ובכל נפשך ובכל מאדך, און רבינו הזקן האָט מגלה געווען דעם דרך ווי יעדער איינער קאָן דאַרף און מוז ברענגען אָט די ג' אהבות אין אַ בפּועל. זאָגנדיק אַז אהבת ישראל איז דער שער העלי', וואָס אויף דעם שער איז אָנגעשריבן מיט ליכטיקע אותיות \"דא תרעא לאעלאה\"."]]],[300010885,"שנח\n\n<b>מורנו</b> הבעש\"ט האָט אַ פולע גערעדט וועגן אהבת ישראל, אהבת התורה ואהבת השם, און האָט מגלה געווען דעם מהות פון אַ אידן<sup data-n=\"1\">179</sup>.",[["1","179","ספר השיחות תש\"א ע' 33. וממשיך שם: הגם על פּי חיצוניות נגלית התורה איז דאָס לכאורה ניט אויסגעהאַלטן, כמו משחק בקוביא איז פּסול לעדות, ויש כאלו דאין עונין אמן אחריו, אָבער על פּי פּנימיות איז דאָך מהותו טוב. נאָר עס איז אלי' וקוץ בה. וואָרום עס איז דאָך כל ישראל ערבים זה בזה, קאָן קיינער ניט זאָגן, איך בין אַ למדן, איך בין אַ חסיד און לייג דריי פּאָר תפלין ומה איכפּת לי' הזולת. אָט אַזוי ווי ביי שותפים, זאָגט דאָך איינער צום צווייטן, די זאַך איז דאָך נוגע צו אונז ביידן, דיין ענין איז דאָך מיין ענין, און זיי קריגן זיך ניט איינער מיטן אַנדערן. אַזוי דאַרף אויך זיין אין דער זאַך. אויסער דעם איז דאָך מה' מצעדי גבר כוננו, און יעדער באשר הוא גיט מען אים דאָך כחות אויף אויספירן די כוונה, און אַזוי איז בענין הנסיון גיט מען אים כחות אויף דעם."]]],[300010886,"שנט\n\n<b>מורנו</b> הבעש\"ט האָט מגלה געווען אַ ענין עצמי אין דער מצוה פון אהבת ישראל. אַז דער אופן הקיום דמצות אהבת ישראל איז ווי דער אופן הקיום פון מצות אהבת התורה און ווי דער אופן הקיום פון מצות אהבת השי\"ת.\nדער ענין עצמי, וואָס מורנו הבעש\"ט האָט מגלה געווען אין די שלש אהבות, אהבת ה' אהבת התורה ואהבת ישראל איז, דאָס אַזוי ווי אהבת השם איז מצד העצם, העכער פון הבנה והשגה, נאָר אהבת העצמות, אַזוי איז אויך אהבת התורה ניט מצד השגת עניני התורה נאָר ווייל עס איז תורת ה', און אַזוי איז אויך אהבת ישראל ניט מצד המעלה הפּרטית פון שכל, השגה ומדות טובות, נאָר ווייל ער איז אַ ישראל<sup data-n=\"1\">180</sup>.",[["1","180","ספר השיחות תש\"א ע' 92."]]],[300010887,"שס\n\n<b>ביז</b> דעם בעש\"ט איז געווען אהבת ישראל מצד התורה, דאָס הייסט מען האָט ליב געהאַט אַ אידן אַ בן תורה.\nדער בעש\"ט האָט מחדש געווען אהבת ישראל, ליב האָבן אַ איד ווייל ער איז אַ איד, אהבת ישראל מצד הנשמה<sup data-n=\"1\">181</sup>.",[["1","181","ספר השיחות תש\"ה ע' 117 ואילך. וממשיך שם: הוד כ\"ק רבינו הזקן האָט מחדש געווען אהבת ישראל – אהבת הצדיקים, וואָס דאָס איז שייך ביי יעדן פּשוט'ן אידן. וראה גם לקוטי דיבורים ח\"ג תקיא, סע\"ב ואילך. ספר השיחות תש\"ט ע' 300. וראה לעיל סימן קלה. קלט."]]],[300010888,"שסא\n\n<b>מורנו</b> הבעש\"ט האָט זוכה געווען צו מגלה זיין דעם דרך עבודה אין אהבת ישראל, האָלט האָבן אַ אידן ווייל ער איז אַ איד<sup data-n=\"1\">182</sup>.",[["1","182","מכתב כ\"ק אדמו\"ר מהוריי\"צ – ספר המאמרים קונטרסים ח\"ג ע' כז. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' רטז. ושם לפנ\"ז:\nבאוצר השיחות אשר חנני השי\"ת ישנה רשימה מדבורי קדש אשר הואיל הוד כ\"ק אאמו\"ר הרה\"ק לאמר באחת הסעודות בשמחת הבר מצוה שלי, ותוכנה:\nמשה רבינו האָט זוכה געווען אַז על ידו האָט ה' אלקינו געגעבן אידן תורה ומצות. [ההמשך בפנים. וממשיך שם:] מורנו רבינו הזקן האָט אויסגעברייטערט דעם אהבת ישראל, האָט געלייגט זיינע כחות עצמיים אַריינצוטראָגן דעם אור החסידות און דרכי העבודה אין סתם אידן, וואָס דורך עבודתו הקדושה האָט ער מחי' געווען דעם כלל ישראל מיט דעם אור העבודה בדרכי החסידות.\nהוד כ\"ק אבותינו רבותינו הקדושים לדורותיהם, בניהם ובני בניהם האָבן, בחסדי א-ל עליון ובברכתם, מעמיד געווען דורות ודורי דורות בעלי מסירת נפש על דרכי לימוד ועבודת החסידות."]]],[300010889,"שסב\n\n<b>אהבת</b> ישראל איז דאָך על פּי תורה. דער בעש\"ט האָט אויפגעטאָן אין אהבת ישראל \"פאַרוואָס\" מען דאַרף האָלט האָבן אַ אידן, און ביי יעדער אידן איז פאַראַן דער \"פאַרוואָס\" מען דאַרף אים האָלט האָבן.\nווי עס איז ידוע, אַז דער בעש\"ט פלעגט זייער מקרב זיין אנשים פּשוטים, ווייל ביי זיי, ביי די אנשים פּשוטים, איז פאַראַן די תמימות און ער פלעגט שיקן די חבריא קדישא זיי זאָלן זיך לערנען פאַרשידענע ענינים ביי אנשים פּשוטים. ווי עס איז ידוע די מעשה אַז דער בעש\"ט האָט געשיקט איינעם פון זיינע גרויסע תלמידים לערנען זיך די מדה פון בטחון פון אַן איש פּשוט<sup data-n=\"1\">183</sup>.\nבעיקר וואָס דער בעש\"ט האָט געהייסן זיינע תלמידים לערנען זיך ביי אנשים פּשוטים איז אין דעם ענין המדות און אין מדות גופא, בעיקר די השתלמות המדות. וואָרום מדות הגם זיי נעמען זיך פון מוחין, מכל מקום בשרשן זיינען זיי למעלה מן המוחין. ע\"ד חכמה ובינה, הגם בינה קומט פון חכמה פונדעסטוועגן בשרשה איז בינה העכער פון חכמה. ווי עס איז ידוע אַז בינה האָט אַ שרש מיוחד אין כח המשכיל. חכמה איז נאָר אַ נקודה, משא\"כ בינה איז אין אַ רוחב, אַזוי אויך דער גילוי העונג איז אין בינה. אין חכמה איז נאָר דער ראשית גילוי העונג און אין בינה איז דאָ די התגלות העונג. גילוי העתיק איז בבינה, היינו מעלתו העצמי של עתיק און בינה ווערט דאָך אָנגערופן אם הבנים וואָס דאָס איז מעלתה העצמי פון בינה.\nשרש המדות איז למעלה מהמוחין, נאָר בכדי אַז די מדות זאָלן אַראָפּקומען אין אַ סדר מסודר דאַרף עס זיין ע\"י המוחין<sup data-n=\"2\">184</sup>. אָבער נאָכדעם ווי די מדות קומען אַראָפּ ע\"י המוחין דאַרף זיין די התגלות המדות ווי זיי זיינען בעצם. ע\"ד ווי עס רעדט<sup data-n=\"3\">185</sup> זיך אין בראשית ברא אלקים, וואָס דאָס איז דער צמצום, אַז די כוונה איז אַז דורך עבודה זאָל נתגלה ווערן דער א\"ס שלפני הצמצום. און דאָס איז דער ענין פון השתלמות המדות, אַז די מדות זאָלן נתגלה ווערן ווי זיי זיינען בעצם.\nאון צוליב דעם האָט דער בעש\"ט געשיקט זיינע תלמידים צו אנשים פּשוטים זיי זאָלן ביי זיי לערנען השתלמות המדות<sup data-n=\"4\">186</sup>.",[["1","183","ראה גם לעיל סימן רסד."],["2","184","ראה ספר המאמרים תרצ\"ז ע' 181. ובכ\"מ."],["3","185","ראה אור התורה בא ע' רסב. ד\"ה בראשית ברא תשל\"ח (ספר המאמרים מלוקט חלק א ע' רסז ואילך. בהוצאה החדשה – ע' רלז ואילך)."],["4","186","ספר השיחות תש\"ה ע' 109. וראה ספר השיחות תש\"ח ע' 185."]]],[300010890,"שסג\n\n<b>דער</b> בעש\"ט האָט אויפגעטאָן צו זען די מעלות פון יענעם און אויב ער זעט ניט די מעלות איז ניט דער חסרון מצד יענעם נאָר מצד דעם איש הרואה, וואָס ער זעט ניט יענעמס מעלות{186}.\n----- הערות -----"],[300010891,"שסד\n\n<b>אור בכלי</b>\n<b>תכליתו</b> הי' התיישבות אור בכלי<sup data-n=\"1\">187</sup>.",[["1","187","ספר השיחות תורת שלום ע' 70."]]],[300010892,"שסה\n\n<b>אנשים פשוטים</b>\n<b>מורנו</b> הבעש\"ט האָט מגלה געווען אַז אפילו די פּשוטים פון בני יעקב וואָס אויף זיי שטייט<sup data-n=\"1\">188</sup> לא כליתם, לא מיבעי די בעלי צורה ווי דער רשב\"י נאָר אפילו די אנשים פּשוטים זיינען אויך בני אלקים<sup data-n=\"2\">189</sup>.",[["1","188","מלאכי ג, ו."],["2","189","ספר השיחות תש\"ד ע' 118."]]],[300010893,"שסו\n\n<b>דער</b> בעש\"ט האָט געוויזן אַז אַ בן תורה דאַרף זיך שעמען פאַר די גרייזיקע אידן, אָט די אידן וואָס זאָגן עברי מיט גרייזן איז אָבער זייערע פּשיטות און תמימות באין ערוך העכער פון אַ בן תורה<sup data-n=\"1\">190</sup>.",[["1","190","ספר השיחות תש\"ב ע' 8."]]],[300010894,"שסז\n\n<b>גילוי אלקות בעולם</b>\n<b>הגם</b> עס איז פריער אויך געווען התגלות פון קבלה ווי אין די צייטן פון ר' יואל בעל שם. אָבער דעמאָלט איז געווען דער זמן פון נסתרים, כאָטש דער סוד פון נסתרים איז דאַן שוין געווען בהתגלות מער ווי אין די צייט פון ר' אלי' בעל שם, וואָס דעמאָלט איז געווען אַלץ בהסתר, הגם זייער ענין איז געווען אויף מגלה זיין דעם לימוד הקבלה, ווי עס איז ידוע אַז זיי האָבן געמאַכט פיל ישיבות צו לערנען תורה און זייער כוונה איז געווען מגלה זיין דעם לימוד הקבלה. ניט קבלה מעשיות נאָר לימוד הזוהר, קבלת הרמ\"ק ועוד, אָבער דאָס איז געווען בהסתר ניט בגילוי און מורנו הבעש\"ט האָט דאָס מגלה געווען בהתגלות.\nווי עס איז ידוע אַז מורנו הבעש\"ט ענינו איז געווען מגלה זיין אלקות בעולם און ער האָט זיך ניט משתמש געווען מיט שמות הק'. הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ האָט געזאָגט, אַז די וועלכע זאָגן אַז מורנו הבעש\"ט האָט זיך משתמש געווען מיט שמות הקדושים זיינען זיך טועה, ווייל בכלל אַ איד וואָס פירט זיך עפ\"י תורה איז בכח צו מאַכן די וועלט אויך עפּ\"י תורה און בפרט דער וואָס איז אַליין תורה. נאָר דאָס איז בנוגע צו הצלה פּרטית אָבער אין אַן ענין פון הצלה דרבים דאַרף מען האָבן תפלה דרבים און אין אַזאַ פאַל – לצורך הצלת הכלל – האָט ער זיך יאָ לפעמים משתמש געווען מיט שמות הקדושים און דאָס אויך ניט בביטוי השמות בדבור נאָר מיט די כוונת השמות.\nוואָרום אין שמות הקדושים איז פאַראַן כידוע דריי מדריגות: מחשבה דבור און מעשה און מורנו הבעש\"ט האָט זיך לפעמים באַנוצט לצורך הצלת הכלל מיט שמות הקדושים, און אפי' דעמאָלט נאָר מיט די כוונת השמות, אָבער עיקר ענינו פון מורנו בעש\"ט איז געווען אויף מגלה זיין אלקות אין עולם<sup data-n=\"1\">191</sup>.",[["1","191","ספר השיחות תש\"ד ע' 109 ואילך."]]],[300010895,"שסח\n\n<b>גילה דרך בעבודת השם</b>\n<b>מורנו</b> הבעש\"ט נ\"ע גילה דרך בעבודת השי\"ת ופתח צנור המס\"נ בעבודה זו. ומורנו רבינו הגדול נ\"ע סלל מסילה רחבה בדרך עבודת השי\"ת כהוראת מורנו הבעש\"ט נ\"ע ומסר נפשו הק' על זה.\nבמלות קצרות<sup data-n=\"1\">192</sup>, מורנו הבעש\"ט נ\"ע, הראה איך צריכים, ויא דאַרף מען לעבוד את השי\"ת.\nומורנו רבינו הגדול נ\"ע הראה איך אפשר, ויא קאָן מען, לעבוד את השי\"ת<sup data-n=\"2\">193</sup>.",[["1","192","נתבאר בלקוטי שיחות חלק יט ע' 251 ואילך. שם ע' 246 ואילך. וז\"ל (שם ע' 247 ואילך): אין דעם חיות האדם, וואָס איז זיך מתפּשט אין גוף זיינען פאַראַן צוויי מדריגות<sup data-n=\"3\">1</sup>: א) דער חיות כללי וואָס באַלעבט דעם גאַנצן גוף, מיט אַלע זיינע אברים, <i>בשווה</i>; אין דעם חיות איז ניטאָ קיין חילוקים פון איין אבר ביזן צווייטן.\nב) דער חיות<sup data-n=\"4\">2</sup> פּרטי, וואָס איז אויסגעמאָסטן אין יעדן אבר לויט זיינע תכונות [וואָס מצד דעם חיות ווערט דער עקב שברגל אָנגערופן<sup data-n=\"5\">3</sup> דער \"מלאך המות\" שבאדם, וויבאַלד אַז דער חיות איז ניט מאיר בגילוי].\nוי\"ל אַז דער אונטערשייד צווישן דעם \"חיות\" החסידות וואָס איז נמשך ונתגלה געוואָרן דורך דעם בעש\"ט און דעם \"חיות\" וואָס איז נמשך ונתגלה געוואָרן דורכן אַלטן רבי'ן – איז ע\"ד דער חילוק צווישן די צוויי אופני חיות<sup data-n=\"6\">4</sup>:\nדער בעש\"ט האָט מגלה געווען אַ חיות <i>כללי</i> אין תומ\"צ, וואָס בכללות האָט זיך דאָס אויסגעדריקט אין דעם ענין פון <i>אמונה</i>. און הגם אַז דער כח האמונה נעמט דורך אַלע כחות הנפש און פּועל'ט אויף זיי אין אַן אופן פון <i>חיות</i>, וואָס נעמט זיי דורך <i>אינגאַנצן</i>, וכמש\"נ<sup data-n=\"7\">5</sup> \"וצדיק <i>באמונתו יחי'</i>\" – מיינט עס אָבער ניט אַז דער חיות האמונה נעמט דורך יעדן כח אויך מצד ענינו <i>הפּרטי</i>, נאָר מצד דעם ענין כללי פון יעדן כח, וואָס איז פאַרבונדן מיט דער נקודת האמונה פון דער נשמה.\nאון ע\"ד ווי דער חיות כללי, וואָס נעמט דורך אַלע אברים און ווערט פאַראיינציקט מיט זיי – איז עס אָבער ניט פאַרבונדן מיטן ענין <i>פּרטי</i> פון יעדן אבר, נאָר מיט דער נקודה כללית פון אַלע אברים (וואָס זיי זיינען אַ טייל פון גוף האדם)<sup data-n=\"8\">6</sup>.\nדער אַלטער רבי האָט אָבער ממשיך געווען אַ חיות אין יעדן כח פון דער נשמה (און אין יעדער עבודה אין תומ\"צ) אויך מצד דעם תוכן פּרטי פון דעם כח; ע\"ד ווי דער חיות פּרטי וואָס איז אויסגעמאָסטן לויטן ענין פּרטי פון יעדן אבר; וואָס דערפאַר איז עס פאַרבונדן מיט <i>חב\"ד</i>, וואָס שכל און די פּעולה פון שכל איז דורך תופס זיין די פּרטים (קצוות) פון דעם מושכל און אין אַן אופן וואָס ער איז זיך מתלבש אין די כוחות הנפש און פּועל'ט אין זיי אין אַן אופן פּנימי, אויך מצד דעם תוכן פּרטי פון דעם כח.\nוראה גם ספר השיחות תרצ\"ו ע' 121. ספר המאמרים אידיש ע' 202. לקוטי שיחות חלק יד ע' 177. חלק כד ע' 181 ואילך. לקמן סימן רס."],["2","193","\"התמים\" חוברת ב' ע' נח [עו, ב] – מכתב כ\"ק אדמו\"ר מהוריי\"צ שכתב לחתנו הרב שי' (נדפס גם באגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' שסב ואילך).\nמועתק בזה ריש המכתב השייך לזה:\nבדבר שאלתך, במה ניכר יחס דרכי החסידות ותורתו של רבינו הגדול וכ\"ק האדמורי\"ם נשיאי חב\"ד, אל דרכי החסידות ותורתו של מורנו הבעש\"ט, אשר לעין הרואה, הלא דרכי החסידות ותורתן של אדמור\"י ואהלין פוילין וגאַליציען קרובים יותר לדרכי החסידות ותורתו של מורנו הבעש\"ט מכמו תורת חב\"ד, ובפרט עניני המופתים.\nתשובה על שאלתך זאת דורשת עריכת מאמר שלם, תוכני ומעובד, ואין הזמן גרמא, ובכן ארשום רק איזה שרטוטים כוללים.\nכן הדבר; אם לדון עפ\"י ספרי רבותינו תלמידי הבעש\"ט, ותלמידי תלמידיו, הצדיקים הגאונים ראשי אלפי ישראל, זי\"ע, הערוכים לפנינו באותיות הכתב, יש מקום גדול אף רחב לשאלתך העמוקה.\nאמנם עלינו לדעת בטוב טעם ודעת כל דבר בעיקרו ושרשו, ואז נבין הענין באשר הוא.\nנודע כי כ\"ק רבינו הגדול קרא עצמו נכד מורנו הבעש\"ט במובן רוחני, וכהא דאמר על הרה\"ק הצדיק ר' ברוך, כי הוא נכד בשרי, ואני נכד רוחני.\nהוד כ\"ק אאמו\"ר הרה\"צ זצוקללה\"ה נבג\"מ זי\"ע, סיפר לי, אשר שמע מהוד כ\"ק אביו אאזמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע, אשר שמע מכ\"ק אאזמו\"ר אדמו\"ר בעל צמח צדק זצוקללה\"ה נבג\"מ זי\"ע, ששמע מפי קדש הקדשים, רבינו הגדול, שאמר אַז ער האָט זעך מוסר נפש גיווען בפּועל, אויף ניט זיין אַ נפרד פון דעם בעש\"ט'ס אַ תנועה אפילו לשעה קלה און אפילו רק למראית עין . . .\nועתה שמע נקודת המענה על שאלתך העמוקה, לאמר הסבא והנכד, דער זיידע און דער אייניקל, שניהם מקושרים ומשולבים בהתאחדות גמורה [ההמשך בפנים].\nוראה לקוטי שיחות חלק ד ע' 1136 ואילך – הביאור בזה שאדמו\"ר הזקן קרא עצמו נכד הבעש\"ט.\n-----שולי הגליון-----"],["3","1","<i>ראה בארוכה ד\"ה אשרינו ה'ש\"ת ספ\"א ואילך</i>.<i> המשך ר\"ה תש\"ח ספ\"ב ואילך</i>.<i> ובכ\"מ</i>."],["4","2","<i>כי נוסף על זה שבכל אבר יש כח פרטי השורה בו</i>,<i> יש ג\"כ חיות פרטי המיוחד לאבר ההוא (ראה המשך תרס\"ו ע' רעו</i>.<i> ספר המאמרים תש\"ג ע' 14</i>.<i> ועוד</i>)."],["5","3","<i>אדר\"נ ספל\"א</i>.<i> ועייג\"כ נזיר נא</i>,<i> א ובתוס' ופי' הרא\"ש שם</i>."],["6","4","<i>להעיר ג\"כ ממשנ\"ת (לקוטי שיחות חלק ב ע' 463 ואילך</i>)<i> בביאור ב' הלשונות שבאגה\"ק דכ\"ק אדמו\"ר מהורש\"ב נ\"ע בנוגע לי\"ט כסלו – \"אור וחיות נפשנו ניתן לנו\"</i>."],["7","5","<i>חבקוק ב</i>,<i> ד</i>.<i> וראה מכות בסופה</i>.<i> תניא פל\"ג</i>."],["8","6","<i>ראה ספר הערכים-חב\"ד ע' אברים ס\"א</i>.<i> וש\"נ</i>."]]],[300010896,"שסט\n\n<b>גילה הקוץ ואופן התיקון</b>\n<b>בדורו</b> של הבעש\"ט איז גיווען אַזעלכע וואָס האָבען גילערענט תורה און האָבען ניט גיוואוסט פון זייער גיזונד און פון זייער לייב און לעבען, זיי האָבען ניט גיוואוסט וואָס אַרום זיי איז, און ניט וואָס אין זיי, דער הונט איז געווען באַגראָבען און זיי האָבען דערפון אליין ניט געוואוסט, וואָס ממילא איז יעמאָלט איז טאַקע גיווען דער עצמי אויך בהעלם, און אזוי האָט דער קוץ עוקץ גיווען ביז ער איז נתגלה געוואָרין, און דאָ האָט אים דער בעש\"ט פאפאדיעט און האָט אים מכחד געווען מן העולם . . דער בעש\"ט האָט מגלה גיווען דעם קוץ, און האָט אים מתקן געווען<sup data-n=\"1\">194</sup>.",[["1","194","ספר השיחות תורת שלום ע' 176."]]],[300010897,"שע\n\n<b>גילה מהות כל דבר</b>\n<b>ר'</b> פנחס רייזעס<sup data-n=\"1\">195</sup> האָט דערציילט להוד כ\"ק אדמו\"ר האמצעי שקיבל מהחסיד הישיש ר' ברוך שמשון בשם אביו אחד הנסתרים, אשר מורנו הבעש\"ט בהתגלותו האָט מגלה געווען דעם חיות פּנימי פון יעדער זאַך וואָס דאָס איז מהותו<sup data-n=\"2\">196</sup>.",[["1","195","ראה אודותו – ספר השיחות תרצ\"ו ע' 55. וש\"נ."],["2","196","ספר השיחות תש\"א ע' 33."]]],[300010898,"שעא\n\n<b>גילה פנימיות התורה</b>\n<b>חשף</b> ה' את זרוע קדשו ויאר לנו על ידי מורנו הבעש\"ט ותלמידיו הקדושים כ\"ק אבותינו רבותינו הקדושים זצוקללה\"ה נבג\"מ זי\"ע את תורת החסידות המחברת הסתים והגליא בביאורים שונים, ובמדה ידועה מגלה את התוך והפנימיות דתורה ומצות, ומעוררת רגש אלקי בלב ישראל החי<sup data-n=\"1\">197</sup>.",[["1","197","קונטרס תורת החסידות ע' 5. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' שיג."]]],[300010899,"שעב\n\n<b>גילוי פנימיות התורה</b>\n<b>אין</b> געציילטע טעג אַרום, דעם ערשטן טאָג שבועות, זמן מתן תורתנו, וועט ווערן צוויי הונדערט יאָר זינט דער הייליגער בעל-שם-טוב האָט פאַרענדיגט זיין נשמה-שליחות – צו פאַרשפּרייטן און מאַכן צוגענגלעך צו אַלע אידן די אינערלעכע ליכטיקייט פון תורה און מצוות דורך תורת החסידות. די ג-טלעכע קוואַלן וואָס רבי שמעון בן יוחאי האָט געעפנט פאַר יחידי סגולה, האָט דער בעל-שם-טוב ברייט צעעפנט פאַר אַלעמען. דערמיט האָט דער אויבערשטער געוויזן נאָך אַ גרעסערן חסד צו זיין אויסדערוויילטן פאָלק אין אַ גאָר קריטישע גלות-צייט<sup data-n=\"1\">198</sup>.",[["1","198","לקוטי שיחות ח\"ז ע' 348."]]],[300010900,"שעג\n\n<b>הסיר ההסתר דהעולם</b>\n<b>דער</b> בעש\"ט האָט געמאַכט לעכער אין דעם הסתר והעלם פון דער וועלט, דער אַלטער רבי מיט חסידות חב\"ד האָט אַריינגעבראַכט אור אין די לעכער<sup data-n=\"1\">199</sup>.",[["1","199","ספר השיחות תש\"ב ע' 7."]]],[300010901,"שעד\n\n<b>העמיד הסולם לעלות למעלה</b>\n<b>מורנו</b> הבעש\"ט האָט אַוועקגעשטעלט דעם סולם און הוד כ\"ק רבינו הזקן האָט געגעבן די כחות אויף אַרויפצוגיין אויפ'ן סולם, אַז יעדער איד זאָל קענען צוקומען למעלה<sup data-n=\"1\">200</sup>.",[["1","200","ספר השיחות תש\"ה ע' 120. וראה שיחת ח\"י אלול ה'שי\"ת (תורת מנחם – התוועדויות ח\"א ע' 190)."]]],[300010902,"שעה\n\n<b>הציב יסוד מוסד בכל עניני העולם</b>\n<b>דער</b> בעש\"ט האָט אויפגעטאָן ניט נאָר באַ די תלמידים און חסידים, נאָר ער האָט געלייגט אַ יסוד מוסד אין אַלע ענינים פון וועלט. ער האָט געוויזן די תלמידים ווי איינער אַ רב עסט שבת פלייש לשם שבת און ער אַליין זעט אויס בשעת מעשה ווי אַ אָקס<sup data-n=\"1\">201</sup>, וויילע ער האָט געגעסן בשר שור. מיט דעם האָט ער געוויזן אַז וואו דער רצון פון אַ מענטשן איז דאָרטן איז ער אינגאַנצן<sup data-n=\"2\">202</sup>.",[["1","201","ראה לעיל בהערה לסימן מח. וש\"נ."],["2","202","ספר השיחות תש\"ב ע' 7. וראה גם ספר השיחות תורת שלום ע' 258."]]],[300010903,"שעו\n\n<b>הרגש חסידותי</b>\n<b>ההרגש</b> החסידותי בא מצד עצם הנשמה, ומה שאנו אומרים ההרגש החסידותי הוא לפי שהצנור של סוג הרגש זה פתח מורנו הבעש\"ט נ\"ע, וכמו שאברהם אבינו ע\"ה פתח הצנור דמס\"נ על פרסום אלקות בעולם כן מורנו הבעש\"ט נ\"ע פתח את הצנור של סוג הרגש זה<sup data-n=\"1\">203</sup>.",[["1","203","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ו ע' ערב."]]],[300010904,"שעז\n\n<b>התגלות אור אין סוף</b>\n<b>דרך</b> הבעש\"ט והמגיד שהמשיכו בחי' התגלות אא\"ס בריבוי אופני גילויים מבחי' ומבשרי אחזה שהוא מחיות הנפש בגוף הבא ונמשך בדרך העלם וגילוי משא\"כ המקובלי' דברו בבחי' אור ומאור כו'<sup data-n=\"1\">204</sup>.",[["1","204","פלח הרמון בא ע' עח."]]],[300010905,"שעח\n\n<b>התגלותו</b>\n<b>התגלות</b> הבעש\"ט נ\"ע הי' שיהי' התגלות פנימיות התורה, והי' ההתגלו' שלא בבחי' התלבשות (וידוע דהמגיד נ\"ע בעת אמירת דא\"ח הי' אומר שמעו סודות התורה), ולא הי' העולם יכול לקבל. והי' עבודה נעלית וגבוה מאד אבל אין זה עדיין התגלות עצם פנימיות התורה. ובא ע\"י רבינו נ\"ע<sup data-n=\"1\">205</sup> בהתלבשות בהשגה ובזה נמשך בחי' העצם כו'<sup data-n=\"2\">206</sup>.",[["1","205","אדמו\"ר הזקן."],["2","206","רשימת כ\"ק אדמו\"ר מהורש\"ב נ\"ע י\"ט כסלו עטר\"ת (ספר המאמרים עטר\"ת ע' תרעג). הובא ונתבאר בד\"ה פדה בשלום תרפ\"ה (ספר המאמרים תרפ\"ה ע' עט). שיחת י\"ט כסלו תשי\"ב (תורת מנחם – התוועדויות ח\"ד ע' 195 ואילך). ובספר המאמרים תרס\"ט ס\"ע רנב: ואמיתית הכוונה של הבעש\"ט נשלם ע\"י רבינו ז\"ל. וראה לקוטי שיחות ח\"ד ע' 1138 ואילך. ח\"ט ע' 158 ואילך. חט\"ו ע' 286. חט\"ז ע' 56. חל\"ה ע' 105 ואילך. קונטרס ענינה של תורת החסידות ס\"ו ואילך."]]],[300010906,"שעט\n\n<b>חיות בלימוד התורה וקיום המצוות</b>\n<b>מורנו</b> הבעל שם טוב האָט מקנה געווען באַ די תלמידים הקדושים אַ חיות פּנימי אין לימוד התורה און קיום המצוות, אַז אַלץ וואָס מען טוט זאָל זיין מיט אַ הרגש פּנימי, צי האַלט מען באמת באַ דעם אופן עבודה, אָדער ניט. ד. ה. צי האַלט מען באמת באַ דעם וואָס מען טוט.\nווי דער סיפּור הידוע<sup data-n=\"1\">207</sup>, וואָס מורנו הבעל שם טוב האָט באַוויזן די תלמידים הקדושים, ווי אַן אָקס אין אַ שטריימל עסט לכבוד שבת<sup data-n=\"2\">208</sup>.",[["1","207","ראה לעיל בהערה לסימן מח. וש\"נ."],["2","208","ספר השיחות תש\"א ע' 39."]]],[300010907,"שפ\n\n<b>מדריך ומנהל כללי</b>\n<b>מורנו</b> הבעל שם טוב איז געווען אַ מדריך און מנהל כללי פון עם אלקי ישראל אין אַלע ענינים כלליים און אין אַלע ענינים פרטים ופרטי פרטים, וועלכע האָבן נאָר אַ שייכות צו דעם עם ישראל, הן אין עניני תורה ועבודת השי\"ת און הן אין עניני מדות ומנהגי ישראל פון אַלע מפלגות, פון דעם גדול שבגדולים אין ידיעות התורה בנגלה, במחקר ובדרוש ביז דעם איש הפּשוט אנשים, נשים, ילדים וילדות, רייך אָדער אָרעם, אָן אונטערשייד וואו זיי געפינען זיך אין זייערע וואוין ערטער, גרויסע שטעט אָדער קליינע שטעט, דערפער, קליינע ישובים, מיהל-הייזער און קרעטשמעס.\nמורנו הבעש\"ט איז געווען אַ מנהיג און אַ מדריך פאַר אַלע אידן און אַ מעורר רחמי שמים על עם ישראל, אַ מליץ יושר פאַר אלקי ישראל על עם קדשו, אַז הוא יתברך זאָל יעדן אידן, מענער און פרויען, משפּיע זיין אַ שפע ברכה והצלחה אין בני חייא ומזונא רויחא<sup data-n=\"1\">209</sup>.",[["1","209","ספר השיחות שם ע' 92."]]],[300010908,"שפא\n\n<b>מעלת בני ישראל</b>\n<b>כ\"ק</b> אדמו\"ר הצ\"צ אמר בשם אדמו\"ר הזקן שאמר וועגן דעם זיידן – הכוונה על הבעש\"ט נ\"ע – אַז אַלעס וואָס ער האָט אויפגעטאָן איז לגלות וואָס אַ איד איז. נאָך אַלע תורות און סודות ששמעו מרבם הבעש\"ט וואָס אפי' נאצלים ופרצופים העליונים וואָלטן זיך ווינטשן הערען דאָס, איז דער עיקר וואָס דער בעש\"ט האָט מגלה געווען איז וואָס אַ איד איז<sup data-n=\"1\">210</sup>.",[["1","210","ספר השיחות שם ע' 115. וממשיך שם: אַ איד וואָלט וויסן וואָס פאַר אַן אָרט ער פאַרנעמט למעלה עד אין סוף וואָלט ער געשטאַנען גאָר אין אַ אַנדער ציור, זיין חב\"ד חג\"ת נה\"י אויך לבושי הנפש מחדו\"מ וואָלט געווען גאָר אין אַנדערע זאַכן, בני חייא ומזונא – דאָס וואָלט ממילא געווען, מען דאַרף נאָר האָבן אַ כלי, די השפּעה וואָלט געווען בדרך ממילא, אָבער ער אַליין וואָלט געווען גאָר אַנדערש."]]],[300010909,"שפב\n\n<b>דער</b> בעל שם טוב האָט מגלה געווען, אַז יעדער איד האָט בכח אויפצוטאָן גדולות אין דעם אויספירן די כוונת הבורא ב\"ה אין דער בריאה<sup data-n=\"1\">211</sup>.",[["1","211","לקוטי דיבורים ח\"ג תכז, א. ספר השיחות תש\"ג ע' 79. וממשיך שם: און דער רבי – רבינו הזקן – און די רביים האָבן מגלה געווען מיט וואָס יעדער קען אַרויסברענגען דעם כח אויף אויפצוטאָן אין דער בריאה די כוונת הבורא ב\"ה."]]],[300010910,"שפג\n\n<b>מעלת נשמות ישראל</b>\n<b>די</b> מעלה עצמית פון נשמה וואָס אין דער מעלה זיינען אַלע נשמות ישראל גלייך, ווי דער רבי זאָגט<sup data-n=\"1\">212</sup> כל הנשמות מתאימות, האָט מורנו הבעש\"ט מגלה געווען.\nמורנו הבעש\"ט האָט מפרסם געווען די מעלה עצמית פון אידן, און האָט דערביי מטעים געווען, אַז די מעלה עצמית איז מער בגילוי באַ פּשוט'ע אידן, מער ווי באַ די לומדים<sup data-n=\"2\">213</sup>.",[["1","212","ראה תניא פל\"ב."],["2","213","ספר השיחות תש\"א ע' 33."]]],[300010911,"שפד\n\n<b>דער</b> זיידע – מיינענדיג מורנו הבעש\"ט – האט מגלה געווען די מעלות פון נשמות, ווי די מעשה הידוע<sup data-n=\"1\">214</sup> פון מורנו הבעש\"ט, וואָס אַמאָל זיצענדיג בסעודה מיט די תלמידים האָט ער זיי געוויזן ווי אַ רב, אַ גאון וצדיק, עסט סעודת שבת לשם שמים<sup data-n=\"2\">215</sup>.",[["1","214","ראה לעיל בהערה לסימן מח. וש\"נ."],["2","215","ספר השיחות תש\"ב ע' 5. ושם לפנ\"ז: במוצש\"ק ווען חסידי כ\"ק רבינו הזקן האָבן גע'חזר'ט די תורה וואָס דער רבי האָט געזאָגט, און זיינען געווען דורכגענומען מיט די עבודה פּנימית, איז צו זיי אַריינגעקומען הוד כ\"ק רבינו הזקן און געזאָגט [ההמשך בפנים. וממשיך שם:] דער רבי – מיינענדיג הרב המגיד ממעזריטש – האָט מגלה געווען די מעלות אין אלקות ע\"ד שש מעלות לכסא, און דאַמאָלסט איז דער ענין נתיישב געוואָרן ביי די תלמידים."]]],[300010912,"שפה\n\n<b>ספרי רפואות לכל המחלות</b>\n<b>גם</b> מלפנים היו חולים אבל לא ידעו שהם חולים, ובא מורנו הבעש\"ט הרב המגיד ממעזריטש וכ\"ק אדמו\"ר הזקן ואחריהם הוד כ\"ק אבותינו רבותינו הק' זצוקללה\"ה נבג\"מ זי\"ע ויגלו את המחלות ויכתבו ספרי רפואות לכל התחלואים<sup data-n=\"1\">216</sup>.",[["1","216","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' רכג."]]],[300010913,"שפו\n\n<b>פתח הצינור של חסידות</b>\n<b>דער</b> בעש\"ט האָט פותח גיווען דעם צינור פון חסידות. פאַר דעם בעש\"ט זיינען אויך געווען כמה וכמה צדיקים חסידים און האָבין מדריך גיווען כמה וכמה תלמידים בדרכי החסידות, אָבער דאָס איז גיווען יחידי סגולה אידין צדיקים וואָס זיינען געווען חסידים.\nדער בעש\"ט נ\"ע האָט אַרויס געטראָגין די חסידות פון רשות היחיד און אַריין געטראָגין אין רשות הרבים, אַז ניט נאָר די יחידי סגולה קאָנען זיין חסידים, נאָר דער רבים דאַרפן זיין חסידים, און האָט געוויזן די דרכי החסידות וואָס אפילו פּשוט'ע מענטשין קאָנען זיין חסידים<sup data-n=\"1\">217</sup>.",[["1","217","אגרות-קודש שם ע' תנ. וממשיך שם: דער רבי האָט פותח געווען דעם צינור פון מסירת הגוף אויף חסידות."]]],[300010914,"שפז\n\n<b>פתח צינור היכולת בעבודת השם</b>\n<b>מורנו</b> הבעש\"ט נ\"ע פתח צנור היכולת בעבודת השי\"ת, בהוראה והדרכה אשר כל אחד ואחד מישראל יכול הוא לעבוד את הוי' באהבה וביראה. גם אנשים פשוטים הנה על ידי תמימות עבודתם באמירת תהלים – אף גם כשאינם יודעים פירוש המילות – ואהבת ישראל מתקרבים המה בהתקרבות פנימית אל ה', להיות כי העיקר הוא המעשה והעבודה בתום לב<sup data-n=\"1\">218</sup>.",[["1","218","קונטרס תורת החסידות ע' 5 ואילך. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ס\"ע שיג."]]],[300010915,"שפח\n\n<b>פתח שערי פנימיות התורה</b>\n<b>דער</b> בעש\"ט האָט גיעפינט שערי פּנימיות התורה און דער אַלטער רבי האָט גיעפינט שערי חב\"ד<sup data-n=\"1\">219</sup>.",[["1","219","לקוטי דיבורים ח\"א לד, ב."]]],[300010916,"שפט\n\n<b>ראש המחנכים</b>\n<b>הבעש\"ט</b> הוא ראש המחנכים ורבינו הזקן ראש המדריכים<sup data-n=\"1\">220</sup>.",[["1","220","ספר השיחות תש\"ג ע' 187 בשם אביו כ\"ק אדמו\"ר מהורש\"ב נ\"ע."]]],[300010917,"שצ\n\n<b>שליח השם</b>\n<b>מורנו</b> הבעש\"ט האָט אַליין, און אויך דורך זיינע תלמידים און תלמידי תלמידים רבותינו הקדושים, איינגעקריצט אין בני ובנות ישראל, אַז אַ איד פאָרט ניט אַוועק. אַ איד פאָרט, און יעדער איד איז אַ שליח פון עצמות, פון פּשיטות עצמות א\"ס ב\"ה<sup data-n=\"1\">221</sup>.",[["1","221","לקוטי דיבורים ח\"ג תצג, א. ספר השיחות תש\"ז ע' 138."]]],[300010918,"שצא\n\n<b>שמחה</b>\n<b>הוד</b> כ\"ק אאזמו\"ר הרה\"ק צ\"צ פלעגט לערנען און מדייק זיין אין די אותיות פון אדמו\"ר הזקן. דער אַלטער רבי האט געזאָגט, אַז צדיקים זיינען דומים לבוראם. האָט הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק מדייק געווען, אַז כשם ווי אין מתן תורה, אין די עשרת הדברות, איז געווען צוויי ענינים מצות עשה און מצות לא תעשה, אַזוי איז אויך אין דעם ענין פון התגלות הבעש\"ט, איז דאָס געווען אין דעם צוויי ענינים, מ\"ע און מל\"ת די ל\"ת איז וואָס דער בעל שם טוב האָט צוגענומען טרערן ביי אידן, ווי עס איז ידוע פון די עניני הבעש\"ט, אַז ער האָט זיך משתדל געווען אין דעם ענין פון שמחה, מאַכן אַ אידן ער זאָל זיין בשמחה וואָס ער איז אַ איד<sup data-n=\"1\">222</sup>.",[["1","222","ספר השיחות תש\"א ע' 132."]]],[300010919,"שצב\n\n<b>שמחה וכובד ראש</b>\n<b>די</b> טרערן וואָס דער בעש\"ט האָט צוגענומען ביי אידן, דאָס איז נאָר וועגן גשמיות בבני, חיי ומזונא, אָבער אין דער עבודה רוחנית וואָס אין תורה ותפלה בעדאַרף זיין כובד ראש<sup data-n=\"1\">223</sup>.\n**********",[["1","223","ספר השיחות שם ע' 133."]]],[300010920,"שצג\n\n<b>שיטתו ותורתו</b>\n<b>שיטתו</b>\n<b>שיטת הבעש\"ט:</b>\nא) <i>הבנת התורה</i>. התורה כולה שמותיו של הקב\"ה<sup data-n=\"1\">224</sup>. וכשם שענין השם הוא רק ידיעה ולא השגה מוחלטת, הנה כן התורה, גם ההלכות המבוארות לפנינו, אינן אלא ידיעה ולא השגה מוחלטת, להיות דלפנימיותה אין סוף.\nב) <i>השגחה פּרטית</i><sup data-n=\"2\">225</sup>. לא זו בלבד שהיא על כל נברא בפרט בפרטי פּרטיות, אשר הקב\"ה מוציא רוח מאוצרותיו לגלגל את הקש והתבן, שבכל זה יש כוונה מיוחדת, הנה לבד זאת הכוונה היא חיות הנברא במעלתו לבד החיות – שהוא מקיימו בלבד.\nג) <i>מעלת ישראל</i><sup data-n=\"3\">226</sup>. גם איש פּשוט שבישראל נעלה הוא בעצם מהות מעלתו כמו גאון הגאונים ממש. כתיב<sup data-n=\"4\">227</sup> בנים אתם לה' אלקיכם וכתיב<sup data-n=\"5\">228</sup> אלה תולדות יצחק בן אברהם אברהם הוליד את יצחק שהי' דמות דיוקנו של הבן כדמות דיוקנו של האב<sup data-n=\"6\">229</sup>. וזהו בנים אתם לה' אלקיכם שדמות דיוקנם של הבנים – ישראל – רחמנים ביישנים גומלי חסדים<sup data-n=\"7\">230</sup>, כדמות דיוקנו כביכול של אביהם – הקב\"ה – רחום וחנון ומרבה לסלוח לשבים. מה הוא ית' נצחי ותורתו ומצותיו נצחי' כן עמו ונחלתו נצחיים. והקטן שבישראל מעטיר עטרת תפארת לגדול ה' ומהולל מאד<sup data-n=\"8\">231</sup>.\nד) <i>אהבת ישראל</i><sup data-n=\"9\">232</sup>. מדת אהבת ישראל לפי שיטת הבעש\"ט ותורתו הוא לא רק מצד מדת הטוב והחסד, אשר כל אחד מישראל צריך לעבוד עם עצמו לגרש את המדות רעות דגאוה שקר קנאה ושנאה והדומה ולהקנות בעצמו המדות טובות דיראת שמים, אהבת התורה, חיבת המצות, ענוה, אמת ואהבת הבריות והדומה אשר כל זה נכלל בשלש מעלות הכוללות שמנו רז\"ל רחמנים ביישנים וגומלי חסדים<sup data-n=\"10\">233</sup>.",[["1","224","ראה זח\"ב פז, א. רמב\"ן בהקדמה לפירושו עה\"ת. יונת אלם פכ\"ט."],["2","225","ראה לעיל סימן קעט ואילך."],["3","226","ראה לעיל סימן מ. קנה ואילך. שפ ואילך."],["4","227","פ' ראה יד, א."],["5","228","תולדות כה, יט."],["6","229","פרש\"י שם."],["7","230","יבמות עט, א."],["8","231","דברי הימים-א טז, כה."],["9","232","ראה לעיל סימן קלב. ואילך."],["10","233","ספר השיחות תש\"ג ע' 161-160."]]],[300010921,"שצד\n\n<b>מורנו</b> הבעל שם טוב האָט זיין תורה לעהרע געשאַפען און געגרינדעט אויף די צוויי יסודות פון ידיעת הבורא (בעגרייפען געטליכקייט – און אהבת ישראל – ליעב האָבען אידן), און די ביידע זאַכען געמאַכט צוגענגליך אויך פאַר גאַנץ איינפאַכע אידען<sup data-n=\"1\">234</sup>.",[["1","234","לקוטי דיבורים ח\"ג ע' 770. ספר השיחות תש\"א ע' 153. וראה לקוטי שיחות חכ\"א ע' 213."]]],[300010922,"שצה\n\n<b>שיטת</b> מורנו כ\"ק הבעש\"ט נ\"ע היא תורה אחת בשתי נוסחאות<sup data-n=\"1\">235</sup>: א) אלקות הוא הכל, דער אויבערשטער איז אַלץ, ב) הכל הוא אלקות, אַלץ איז דער אויבערשטער<sup data-n=\"2\">236</sup>.",[["1","235","ראה גם ספר השיחות תר\"ץ ע' 86. וש\"נ."],["2","236","רשימת המאסר – לקוטי דיבורים ח\"ד תרסא, ב. ספר השיחות תרפ\"ז ע' 229. ושם: ועל יסוד זה הולך וסובב כל עניני התורה והמצוה בביאורים והסברים שונים ע\"פ דרכי הבנת תורת החסידות בכל חיי האדם על פני האדמה."]]],[300010923,"שצו\n\n<b>חסידות ומוסר</b>\n<b>שאלו</b> את רבינו הזקן מה חידש הבעש\"ט, הרי הי' הראשית חכמה והשל\"ה והיו צדיקים גדולים גם קודם.\nוהשיב: כי שני אופנים בחושי הבעה\"ב, איך להשמר מגנב – בעה\"ב הוא שיש לו שדה וגינה, חצר, בהמה, דיר לבהמה, בית וכלי בית – וישנו כזה אשר תיכף בראותו את הגנב בחצירו מתחיל לצעוק: \"אַ גנב\". ובורח הגנב. ויש עוד דרך אשר מניחין לגנב לכנוס בביתו ותופסו ומוסרו למשפט. ההפרש בין שניהם הוא כי באופן הא' כשבורח הגנב הרי צריך לחשוש כי הלא יכול לחזור ולגנוב אצלו, אבל כשמוסר הגנב למשפט הלא לא יכול לגנוב עוד, אבל לדרך השני' צריכים בעה\"ב חכם ובעל כח. וכן הוא ברוחניות שעד הבעש\"ט: דרכי המוסר הוא ע\"ד הצעקה עס איז אַן עבירה, וממילא פועל זה לא לעשות, כי בכלל היו אומרים אַמאָל, ווי איז שייך אַ איד צו אַ תאוות היתר, ובפרט לאיסור. אבל דרך הבעש\"ט הוא לתפוס הגנב ולמוסרו למשפט<sup data-n=\"1\">237</sup>.",[["1","237","ספר השיחות תרצ\"ו ע' 131. נתבאר בלקוטי שיחות חלק ב ע' 474. וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע חלק טו ע' רלה. חלק יז ע' רטו."]]],[300010924,"שצז\n\n<b>עבד</b>\n<b>מבואר</b> בתניא פי\"ד שעבודת הבינוני הוא בדרך מלחמה, וכמו שאמר שם פט\"ו שיש שני מדרי' עבדו ולא עבדו, ודרך הבעל שם טוב הוא עבדו<sup data-n=\"1\">238</sup>.\n**********",[["1","238","ספר השיחות שם."]]],[300010925,"שצח\n\n<b>משיח</b>\n<b>מורנו</b> הבעל שם איז דער זה ינחמנו<sup data-n=\"1\">239</sup> פון עקבות משיחא תקופה. ער – דער בעל שם טוב – איז דער טרייסט וואָרט זאָגער און דער ערמוטיקער צו דעם עם ישראל אין שווערסטער תקופה, פון דעם ביטערען גלות פון זיין צייט ביז דעם גליקליכסטען טאָג פון ביאת המשיח<sup data-n=\"2\">240</sup>.",[["1","239","בראשית ה, כט."],["2","240","לקוטי דיבורים ח\"ג שפו, א. ספר השיחות תש\"א ע' 154."]]],[300010926,"שצט\n\n<b>שלא</b> יכבה נרו לעולם ועד אַז דער אור הבעש\"ט איז תמיד מאיר, חסידות וועט זיין ביז משיח בלתי ספק, וואָרום עס איז דאָך דוד מלך ישראל חי וקיים<sup data-n=\"1\">241</sup>, וואָס דאָס איז גיווען דער בעש\"ט און דער מגיד און דער רבי, און אזוי שטענדיק וואָס מיר זיינען דאָך פון דוד'ן וועט דאָס שטענדיק זיין ביז משיח'ן<sup data-n=\"2\">242</sup>.",[["1","241","ר\"ה כה, א."],["2","242","ספר השיחות תורת שלום ע' 176."]]],[300010927,"ת\n\n<b>מאז</b> שהתחילו לדבר דא\"ח מזמן הבעש\"ט ואילך נתרבו האפיקורסים דוקא<sup data-n=\"1\">243</sup> . . ולכן בסוף הגלות הוא תגבורת קליפת אפיקורסות שהו\"ע מלחמת גוג ומגוג כידוע בענין תער השכירה<sup data-n=\"2\">244</sup>, ומכחישים מציאות אלקות לגמרי, הגם שהאיר מעין גילוי דלעתיד ע\"י דא\"ח . . עד שיוכלו לומר בחוצפה אפילו על מציאות גילוי אלקות הנגלה ע\"י תורת הבעש\"ט ותלמידיו שהם דברי שקר ח\"ו . . וזהו סימן שהאור חדש דלעתיד כבר נגלה למעלה<sup data-n=\"3\">245</sup>.",[["1","243","על האפיקורסים בימי הבעש\"ט – ראה גם מאמרי אדמו\"ר האמצעי קונטרסים ע' עדר: וכמ\"ש במ\"א בארוכה בענין האפיקורסים המפורסמים שהיו בימי הבעש\"ט הקדוש ז\"ל נ\"ע."],["2","244","ראה לעיל סימן קסג."],["3","245","ד\"ה איתא בפסיקתא כו' להר\"ה מפּאַריטש (קונטרס פלח הרמון – מאמרים ורשימות (ירושלים, תשנ\"ב) ע' לט ואילך). ושם לפנ\"ז: וכידוע דבעקבות משיחא דוקא חוצפה יסגי כו', והו\"ע מלחמת גוג ומגוג שהו\"ע תגבורת קליפת אפיקורסות . . וכן עתה [ההמשך בפנים]."]]],[300010928,"תא\n\n<b>והאלקים</b> אשר ברא שמים וארץ, אשר שלח לנו את משיחו, מורנו הבעש\"ט, אשר פדה בשלו' נפשינו הוד כ\"ק אדמו\"ר הגדול והזקן ותורת החסידות מרדת שחת<sup data-n=\"1\">246</sup>.\n**********",[["1","246","אגרות-קודש כ\"ק אדמו\"ר מהוריי\"צ חי\"ד ע' קמה. וממשיך שם: ואשר הוריד נשמת קודש כ\"ק אאמו\"ר הרה\"ק להורות לעם קודש, ארחות חיים, ויקחהו אליו בהיכלו, הוא ישלח מלאכו כו'."]]],[300010929,"תב\n\n<b>שונות</b>\n<b>אור החיים</b>\n<b>כמ\"ש</b> הבעש\"ט ז\"ל על בעל האוה\"ח שתמיד הי' מוצאו בהיכל דמשיח כו'<sup data-n=\"1\">247</sup>.",[["1","247","מאמרי אדמו\"ר האמצעי בראשית ע' תנ. ושם לפנ\"ז: וכמו שידוע שיש נשמות גם עכשיו שהם זריזים יותר לענין העליי' בהיכלות העליונים אף לנשמות הגבוהות מהם [ההמשך בפנים. וממשיך שם:] ויש נשמות גבוהות בחכמה דתורה יותר ואין עולים בג\"ע העליון כמ\"ש אכתי לוי מאבראי (ראה ברכות יח, ב)."]]],[300010930,"תג\n\n<b>אמונת צדיקים</b>\n<b>דער</b> ענין פון אמונה באַשטייט אין דעם אַז מ'גלויבט אין דעם אויבערשטן, מ'גלויבט אין דעם אויבערשטנ'ס תורה, און מ'גלויבט אין דעם אויבערשטנ'ס שלוחים<sup data-n=\"1\">248</sup> – אָנהויבנדיק פון משה רבינו<sup data-n=\"2\">249</sup>, און דערנאָך דער \"משה רבינו\" פון יעדן דור<sup data-n=\"3\">250</sup>, וואָס דאָס זיינען די נשיאי ישראל פון יעדן דור<sup data-n=\"4\">251</sup>, אַזוי ווי דער בעש\"ט אין זיין דור, און כ\"ק מו\"ח אדמו\"ר – אין אונזער דור<sup data-n=\"5\">252</sup>.",[["1","248","ד\"שלוחו של אדם כמותו\" (ברכות לד, ב. וש\"נ), ועד\"ז שלוחו של אדם העליון – כמותו (לקו\"ת ויקרא א, ג).\nוראה זח\"ב לח, א: מאן פני האדון הוי דא רשב\"י. וכעין זה בנגלה דתורה – ראה ירושלמי ביכורים פ\"ג ה\"ג: והוי' בהיכל קדשו דא ר' יצחק בר' לעזר בכנישתא מדרשא דקיסרין. וראה בחיי תשא לג, ז."],["2","249","ראה מכילתא עה\"פ בשלח יד, לא: ויאמינו בה' ובמשה עבדו . . שכל מי שמאמין ברועה נאמן כאילו מאמין במאמר מי שאמר והי' העולם. ולהעיר מאבות (פ\"ד מי\"ב) מורא רבך כמורא שמים."],["3","250","ד\"אתפשטותא דמשה בכל דרא ודרא\" (תקו\"ז תס\"ט (קיב, א. קיד, א)), ו\"אין דור שאין בו כמשה\" (ב\"ר פנ\"ו, ז).\nוראה לקו\"ש ח\"ו ע' 255."],["4","251","ראה תקו\"ז שם (קיד, א): בכל צדיק וצדיק."],["5","252","לקוטי שיחות חלק כד ע' 291."]]],[300010931,"תד\n\n<b>בטחון</b>\n<b>ואם</b> הי' בטחון אמיתי הי' באמת הכל טוב וכידוע המעשה מהבעש\"ט ז\"ל<sup data-n=\"1\">253</sup>.",[["1","253","אגרות-קודש אדמו\"ר מהורש\"ב ח\"ב ע' תתא."]]],[300010932,"תד-א\n\n<b>דער</b> בעש\"ט האָט געמאַכט מאין ליש. אַמאָל האָט דער בעש\"ט געהערט ווי איין איד זאָגט צום אַנדערן: דער אויבערשטער וועט געוויס העלפן. איז דער בעש\"ט אַוועקגעגאַנגען צו זיין חבריא קדישא און האָט דערפון געמאַכט אַ גאַנצען געריכט און האָט דערביי געזאָגט, אַז מיט דעם וואָס אַ איש פּשוט האָט געזאָגט, השי\"ת וועט געוויס העלפן האָט ער געראַטעוועט צענדליגער און הונדערטער טויזענטער פון גזירות רעות<sup data-n=\"1\">254</sup>.",[["1","254","ספר השיחות תש\"ד ע' 4."]]],[300010933,"תה\n\n<b>גילוי הבעל שם טוב</b>\n<b>גילוי</b> הבעש\"ט איז אַ סך גרעסער ווי גילוי אלי'<sup data-n=\"1\">255</sup>.",[["1","255","ספר השיחות תש\"ד ע' 113 (הובא בתורת מנחם – התוועדויות תשי\"ט ח\"ב ע' 238 ואילך). ושם שאמר אדה\"ז: עס איז אַ גמרא מפורשת . . די רז\"ל זאָגען (כתובות עז, ב) מכריז אלי' קמי' פנו דרך לבר ליוואי. דער פירוש ליוואי איז מל' התחברות, די התחברות פון אלקות מיט נשמות ישראל. מורנו הבעש\"ט האָט מחבר געווען אלקות מיט נשמות ישראל, וואָס דער גילוי דערפון וועט זיין בביאת המשיח און מורנו הבעש\"ט האָט דאָס מגלה געווען. עס איז דאָך ידוע (ב\"מ פה, ב), אַז ווען אלי' ז\"ל האָט מגלה סוד געווען, מחיוהו שתין פולסי דנורא, און מורנו הבעש\"ט וואָס האָט מגלה געווען דעם סוד פון משיח, איז לבד זאת וואָס מען האָט אים ניט מעניש געווען, נאָר אדרבא ער האָט מקבל געווען אַ ברכה אויף דעם, אַז זיינע גילוים זאָלען זיין עד עולמי עד ביז משיח צדקנו – נמצא אַז גילוי הבעש\"ט איז גרעסער ווי גילוי אלי' ז\"ל. וברשימת היומן של כ\"ק אדמו\"ר מהוריי\"צ – ח\"י אלול תרס\"ג (\"מבוא\" לקונטרס ומעין ע' 57): עס זיינען געווען זמנים באַ די רביים וואָס גילוי הבעש\"ט איז געווען אָנגעלייגטער ווי גילוי אליהו."]]],[300010934,"תו\n\n<b>החליף עשירות בבן</b>\n<b>מעשה</b> מהבעש\"ט שבא אליו אדם חשוכי בנים לבקש שיתפלל לה' שיהי' לו בנים והי' האדם עשיר ואמר לו שאם ירצה שיהי' עני יהי' לו בנים וקבל על עצמו והי' לו בנים ונעשה עני, והענין שהבעש\"ט ראה שחלק החסד שנקצב על נפשו שכשימשיכו לעוה\"ז לא יספיק על בנים ועושר יחד אלא על אחד מהם וזאת פעל שהחליף שיהי' מחסד זה בנים ולא עושר<sup data-n=\"1\">256</sup>.",[["1","256","סהמ\"צ להצ\"צ קז, ב. וראה גם מאמרי אדמו\"ר הזקן תקס\"ה ח\"ב ע' תרנ. ע' תרנב. אוה\"ת ראה ע' תשכד. קונטרס ומעין מאמר יט בסופו. ד\"ה והנה פרח מטה אהרן תשל\"ג (ספר המאמרים מלוקט ח\"ד ע' רצב. בהוצאה החדשה – ח\"ג ע' רצב). גנזי נסתרות ע' ד. וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע חי\"ח ע' תמז: במש\"כ בדרמ\"צ ע\"ד הבעש\"ט (הובא בתוס' פרטים בקונטרס ומעין סמי\"ט) דלמה לא המשיך בשנה הב' והג' – הנה כמה ענינים שאין מתחדשים בכל שנה ושנה משרשם הראשון, וכמו מספר שני האדם (ראה יבמות ספ\"ד) וראה עט\"ר איך שכל שנה הוא פרט הנמשך מהכלל דאלף שנה."]]],[300010935,"תז\n\n<b>התקשרות אליו</b>\n<b>צו</b> דעם בעש\"ט איז געווען גענוג אַז מ'איז געווען אַ מקושר, ענין ההתקשרות הוא לעשות דבר פועל כפי הוראתו, כמו בענין אמירת אותיות שבתורה או השקידה באהבת ישראל<sup data-n=\"1\">257</sup>.",[["1","257","רשימת היומן של כ\"ק אדמו\"ר מהוריי\"צ – כ' מ\"ח תרנ\"ו (ספר המאמרים תש\"ט ע' 89).\nושם לפנ\"ז: דעם עלטער זיידן האָט מען געדאַרפט פאַרשטיין, דזהו ההפרש בין שלשה אלה, הבעש\"ט הה\"מ ממעזריטש וכ\"ק אדמו\"ר הזקן [ההמשך בפנים. וממשיך שם:] צו דעם מגיד – האָט מען געדאַרפט לערנען ולא הספיק ענין ההתקשרות בלבד. כ\"א היו צריכים להיות אצלו לראותו ולהתלמד מאתו ההנהגה, ואצל כ\"ק אאזמו\"ר הזקן לא הספיק ענין ההתקשרות וגם לא ענין הראי' וההתלמדות מדרכיו, מי האָט אים געדאַרפט פאַרשטיין, און די וואָס האָבן אים פאַרשטאַנען זיינען געווען גאָר אַנדערע פון די אַנדערע חסידים, ניט נאָר פון די מקושרים, נאָר אויך אַפילו פון די גרויסע בעלי השכלה."]]],[300010936,"תח\n\n<b>זכות הזכרתו</b>\n<b>אַז</b> דער רבי פלעגט וועלן איבער זאָגן דעם בעש\"ט'ס אַ תורה פלעגט ער פריער זאָגן מיט אַזאַ נוסח \"דעם זיידענס\"<sup data-n=\"1\">258</sup> אַ תורה, איז די ווערטער אַליין אַ סגולה צו השכלה, הבנה און יראת שמים, און אַז מי דערציילט אַ סיפּור המעשה פון זיידן איז דאָס אַ סגולה צו אריכות ימים און פּרנסה בשפע<sup data-n=\"2\">259</sup>.",[["1","258","כן הי' אדמו\"ר הזקן קורא את מורנו הבעש\"ט."],["2","259","לקוטי דיבורים ח\"ב רנד, ב ואילך. ספר השיחות תרצ\"ו ע' 79."]]],[300010937,"תט\n\n<b>לשם שמים</b>\n<b>דער</b> בעל שם טוב האָט מבטיח געווען מיט זיין עוה\"ב און זיין גילוי לעתיד אַז דער וואָס וועט אַריינטראָגן אין זיינע ענינים הגשמיים אַ לש\"ש, לעשותם לש\"ש, הבטיח כי יצליח, און דער בעש\"ט האָט געוואוסט וואָס הייסט זיין עוה\"ב וגילוי לעתיד, כידוע מה שאמר אאמו\"ר ההפרש בין עניו ושפל, כי שפל הוא שהוא בעצם שאינו מכיר מעלות עצמו, אבל עניו הוא שמכיר מעלתו ומדריגתו<sup data-n=\"1\">260</sup>.",[["1","260","ספר השיחות תרצ\"ו ע' 149."]]],[300010938,"תי\n\n<b>משל שלו – תורה</b>\n<b>רבינו</b> הזקן אמר: אַז דער זיידע (הבעש\"ט) הי' אומר משל – איז דאָס געווען תורה, און אַז דער רבי<sup data-n=\"1\">261</sup> פלעגט זאָגן תורה – איז דאָס געווען אַ חידה<sup data-n=\"2\">262</sup>.",[["1","261","הרב המגיד ממעזריטש."],["2","262","ספר השיחות תרצ\"ו ע' 134. וממשיך שם: דבר זה שמע אדמו\"ר האמצעי יחד עם הרה\"צ הר\"א משטראַשעליע, והרבה חשב בזה אדמו\"ר האמצעי, כי כבד הי' לו להבין, כי: ידוע ההפרש בין משל לחידה, שמשל הוא ענין זר להשכל אבל עכ\"פ המשל בעצמו הוא ג\"כ ענין שכלי בסדר מסודר, אבל ענין החידה הוא שאינו שכל מסודר, וא\"כ איך הוא כשהבעש\"ט הי' אומר משל הוא תורה, ותורה של הרב המגיד אשר הי' ביאור ע\"פ סדר עם מאמרי חז\"ל הנהו חידה. ונכנס לשאול, ואמר לו ביאור ע\"ז. וכשסיפר אדמו\"ר האמצעי להצ\"צ מזה, אמר לו כי הביאור שאמר לו רבינו הזקן ע\"ז, כתבו שלשה חדשים."]]],[300010939,"תיא\n\n<b>נפתחו השמים</b>\n<b>הרב</b> המגיד האָט געזאָגט: אַז מיר זיינען געווען חג השבועות ביים רבי'ן – מורנו הבעש\"ט – איז געווען נפתחו<sup data-n=\"1\">263</sup> השמים ואראה מראות אלקים<sup data-n=\"2\">264</sup>.",[["1","263","יחזקאל א, א."],["2","264","ספר השיחות תש\"ג ע' 120. וממשיך שם: און הוד כ\"ק אדמו\"ר הזקן האָט געזאָגט: אַז מיר זיינען געווען ביים רבי'ן – הרב המגיד ממעזריטש – חג השבועות האָט מען געזען און דערהערט.\nדער בערדיטשעווער איז געווען אַ עמקן גדול. אַמאָל האָט ער געזאָגט אַ ענין אין נגלה און האָט אָנגעהויבן מיטן פּסוק הנה ד' רוכב על \"עב\" \"קל\", האָט ער געזאָגט ע\"ב קושיות און ק\"ל פּירוקים. הוד כ\"ק אדמו\"ר הזקן האָט אויף דערויף געשריבן פיר הונדערט בויגן. און האָט געזאָגט דערנאָך, אַז דאָס קומט ניט צו דעם וואָס מ'האָט געזען שבועות ביים רבי'ן.\nהוד כ\"ק אאזמו\"ר הרה\"ק הצ\"צ האָט אויסגעפירט: דאָס איז ניט נאָר ביים מגיד נאָר ביי אַלע רביים, און ניט נאָר אין יענעם זמן – נאָר אין אַלע זמנים. נאָר מען דאַרף האָבן כלים פּנימיים."]]],[300010940,"תיב\n\n<b>ספר שבחי הבעל שם טוב</b>\n<b>רובו</b> מיוסד<sup data-n=\"1\">265</sup> על דברי וסיפורי רבינו הזקן<sup data-n=\"2\">266</sup>.",[["1","265","ראה ספר שבחי הבעש\"ט כת\"י (ירושלים, תשמ\"ב) ע' 19."],["2","266","אגרות-קודש כ\"ק אדמו\"ר זי\"ע חט\"ו ע' תלא [ושם לפנ\"ז: ולהעיר מענין דששים המה מלכות, וממאמר רז\"ל (ב\"ב קנז, ב) דמהדורות תושבע\"פ ארכו ששים שנה, וכן אף שאינו ברור בעיני נכונות כל הפרטים שבשבחי הבעש\"ט, אף שכפי כתבו [ההמשך בפנים. וממשיך שם:] אבל בטח יסוד ישנו לזה, ובפרט להענינים שהם יסוד לכמה סיפורים נוסף על עצם הענין. וכוונתי להמובא שם, שאמר הבעש\"ט שאם לא יבוא הגואל צדק במשך ששים שנה, מוכרח אז הוא לבוא בזה העולם, ובהמשך שם, שנשמע מאחרים שאמר בפירוש, שכעבור ששים שנה יבוא עוה\"פ בזה העולם, וחסידים מספרים אודות פתגם אדמו\"ר האמצעי בזה וכו', וכיון שלא שמעתיו מכ\"ק מו\"ח אדמו\"ר, ועכ\"פ מבר סמכא מוחלטי, אינני מעתיקו, ואפשר נודע לו ע\"ד זה יותר בפרטיות]. וראה גם אגרות-קודש כ\"ק אדמו\"ר זי\"ע חי\"ב ע' רל. התוועדויות תשמ\"ב חלק ב ע' 1114. חלק ד ע' 2200. תשד\"מ חלק א ע' 150. וראה לעיל סימן שכה: \"מספרים בשבחי הבעש\"ט ז\"ל כו'\"."]]],[300010941,"תיג\n\n<b>עבודה זרה</b>\n<b>ציוה</b> הבעש\"ט לעשות שלשול למהרהר בע\"ז כו'<sup data-n=\"1\">267</sup> וכידוע<sup data-n=\"2\">268</sup>.",[["1","267","ראה ספר גנזי נסתרות ע' נח."],["2","268","מאמרי אדמו\"ר האמצעי דרושי חתונה ח\"א ע' קמג. ושם לפנ\"ז: מבואר במ\"א בשרש אלקים אחרים שנמשך מבחי' פסולת הנופל מלמעלה שנקרא צואה והוא מבחי' נקב אחוריים כו', וז\"ש צא תאמר לו וכן כל שולחנות מלאו כו' (וע\"כ [ההמשך בפנים. וממשיך שם:] וכמ\"ש במ\"א בענין ע\"ז דפעור."]]],[300010942,"תיד\n\n<b>פרנסה</b>\n<b>עס</b> איז געווען באַקאַנט דעם בעש\"ט'ס שיטה אין פּרנסה אַז אידן באַדאַרפן זיך בעזעצין אין דערפער אין קליינע ישובים און אין קרעטשמעס, פאַרנעמען זיך מיט עבודת אדמה, און די אַנדערע דאָרף זאַכן, זיין אַרענדאַטערס און קרעטשמעס, טייכער – וואָס שטייסן מיהלן – ווינט- מיהלן, און גערטנער, פילע הונדערטער אידישע משפּחות האָט דער בעל שם טוב באַזעצט אויף פריער-דערמאָנטע באַשעפטיקונגען, און פלעגט זיי – די דאָרפס לייט און בעלי ישוב – שיקן מלמדים און שוחטים פון זיינע תלמידים וואָס זאָלן לערנען מיט זייערע קינדער.\nבאַ דעם בעל שם טוב איז געווען אַ ספּעציעלע קופּה של צדקה, מיט דעם נאָמען פּדיון שבוים, העלפן די אַרענדאַטערס און די קרעטשמערס וואָס האָבן ניט געהאַט מיט וואָס צו באַצאָלן די אַרענדע געלטער<sup data-n=\"1\">269</sup>.",[["1","269","ממכתב כ\"ק אדמו\"ר מהוריי\"צ. וראה לקוטי דיבורים ח\"ב רו, א. ספר השיחות תרצ\"ו ע' 21."]]],[300010943,"תטו\n\n<b>רדפו השטן</b>\n<b>וכזה</b> הי' המעשה בימי הבעש\"ט ז\"ל שרדפו הב\"ד שלמעלה לשטן המקטרג לחוב ולא רצו לשמוע ממנו הקטרוגים<sup data-n=\"1\">270</sup>.",[["1","270","מאמרי אדמו\"ר האמצעי דברים ח\"ב ס\"ע תרמט ואילך. אוה\"ת תצא ע' תתקפה. נתבאר בשיחת ש\"פ נצו\"י תשכ\"ז. וראה שיחת ש\"פ תבוא, ח\"י אלול תשל\"ג (לקוטי שיחות חי\"ד ע' 263).\nוראה מאמרי אדמו\"ר האמצעי קונטרסים ע' שמז: וכמעשה שסיפר הבעש\"ט ז\"ל שפ\"א רבו הקטרוגי' רעי' מן השטן עד להשחית כו' ולא הי' מועיל לפוטרו בשום הטענה וזכו' לישראל וצוה ראש ב\"ד העליון לגעור בו ולדוחפו חוץ כו'."]]],[300010944,"תטז\n\n<b>ריקוד במחול</b>\n<b>דער</b> ריקוד במחול – אין אַ עיגול הנהוג אצל החסידים – איז דאָס נתחדש געוואָרן בימי הבעש\"ט<sup data-n=\"1\">271</sup>, מחול איז מקיף, דער ערשטער גילוי מוז זיין אַ מקיף ער איז זיך ניט מתיישב אין כלים בכלל און אין פּנימיות בפרט, דער זיידע רבינו הגדול מיט זיין מסירת נפש אויף חסידות און אויף חסידים האָט מיישב געווען דעם מקיף אין אַ פּנימיות און האָט געמאַכט כלים צו פּנימיות, איצטער אַז חסידים טאַנצן אַ מחול איז דאָס אורות בכלים און אור מקיף שורה עליהם, והמקיף פּועל בפּנימי<sup data-n=\"2\">272</sup>.",[["1","271","ראה גם ספר השיחות תרצ\"ט ע' 306. הועתק לעיל בהערה לסימן נד."],["2","272","לקוטי דיבורים ח\"א לד, א."]]],[300010945,"תיז\n\n<b>תהלים</b>\n<b>דער</b> בעש\"ט – האָט ווייטער געזאָגט הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש – האָט זיך ניט פאַרלייגט אויף משניות בע\"פּ און האָט זיך מסתפּק געווען, אַז מען זאָל זאָגן תהלים בע\"פּ<sup data-n=\"1\">273</sup>.\n**********",[["1","273","ספר השיחות תש\"ד ע' 149. ומוסיף שם: הרב המגיד ממעזריטש האָט אויך געהייסן אויסלערנען בע\"פּ די שירת האזינו און הוד כ\"ק רבינו הזקן האָט זיך פאַרלייגט אויף אויסלערנען משניות בע\"פּ ביי זיינע בני משפּחתו."]]],[300010946,"תיח\n\n<b>הוספה</b>\n<b>להבין</b><sup data-n=\"1\">1</sup> הקושיא הידוע אם תורת הבעש\"ט אמת ובלא זה אין יכולים לעמוד בקשרי המלחמה של הסט\"א, למה לא נתגלה בימים הקדמונים, כי אנו רואים שדוקא בשנת ת\"ק לאלף השישי<sup data-n=\"2\">2</sup> נתגלה בעולם ולא קודם לזה. הענין הוא כך, כי אלף שנים למעלה נחשב כיום א' כדכתי'<sup data-n=\"3\">3</sup> כי אלף שנים בעיניך כו', ויש בזה ערב ובוקר ולכן כל הזמן עד אחר אלף השישי ת\"ק הראשונים נק' לילה נמצא שמשנת ת\"ק לאלף השישי הזה מתחיל הבוקר של אלף הזה<sup data-n=\"4\">4</sup>. וע' באוה\"ח פ' צו<sup data-n=\"5\">5</sup> ע\"פ היא העולה, וכתי'<sup data-n=\"6\">6</sup> והי' ביום השישי והכינו כו' שצריך הכנה לשבת, ומצוה עפ\"י שו\"ע<sup data-n=\"7\">7</sup> לטעום מכל מאכל שנתבשל לשבת שנאמר<sup data-n=\"8\">8</sup> טועמי' חיים זכו<sup data-n=\"9\">9</sup>, וכן הוא בכלל אלף הז' נק' יום שכולו שבת<sup data-n=\"10\">10</sup>, ואז תהי' הסעודה מלויתן ושור הבר<sup data-n=\"11\">11</sup>, וידוע הפי' עפ\"י חסידות שיתגלה פנימי' התורה<sup data-n=\"12\">12</sup> ע\"י משיח שיבוא בב\"א<sup data-n=\"13\">13</sup>, וזה נק' סעודת הצדיקים מנשמות הנק' נוני ימא שהם נק' לויתן<sup data-n=\"14\">14</sup> מתומ\"צ שלהם, וכל נשמו' מעלמא דאתגליא מתומ\"צ שלהם נקראים שור הבר, וע\"כ כיון שהתחיל יום השישי שנת ת\"ק היתה הזכות והמצוה לטעום מהמאכלים של שבת, ולכן נשלח לעוה\"ז הבעש\"ט ז\"ל לגלות פנימי' התורה, וכל מה שיתגלה פנימי' התורה ע\"י הצדיקי' עד ביאת המשיח זה נק' טעימא בעלמא, ועיקר הסעודה תהי' לעתיד אבל קודם לזה לא הי' ביכולת לנשמות בגופים לטעום מאילנא דחיי הגם שנתגלה נשמת האריז\"ל בשנת של\"ג<sup data-n=\"15\">15</sup> וגילה חכמת הקבלה אך זה הי' מעט מזעיר רק לתלמידיו הקדושים ונק' בחי' יניקה. וע\"ז רומז בגמ'<sup data-n=\"16\">16</sup> הסוד משמרה שלישית תינוק יונק משדי אמו ואשה מספרת עם בעלה, כי בשנת של\"ג וד' חדשים כלו שני חלקי הלילה והתחיל חלק הג' מהלילה, עד שנת ת\"ק היא משמרה שלישית וע\"כ התחילה עליו' השכינה מעפר, כי מאז כלה גזירו' שמד<sup data-n=\"17\">17</sup>, והתחיל לירד בעולם נשמו' דתיקון, לכן מה שתלמידי האריז\"ל גילו חכמת הקבלה נק' רק בחי' יניקה, וזהו תינוק יונק משדי אמו, ואשה מספרת קאי על השכינה הקדושה שהתחילה לקום מעפר, אך בשנת ת\"ק התחיל להתנוצץ בעולם אור היום לכל באי עולם.\n<b>ובזה</b> יובן מאמר סתום מהה\"ג ר' פנחס מקאָרעץ ז\"ל מתלמידי הבעש\"ט ז\"ל, שאמר שנשמת הבעש\"ט ירדה לעוה\"ז להעיר את כלל ישראל משינתם שהם בבחי' התעלפות<sup data-n=\"18\">18</sup>, כידוע שיש ד' מדריגות בשינה, המדריגה הא' היא נים ולא נים, תיר ולא תיר, דקרו לי' ועני ולא ידע לאהדורי סברא<sup data-n=\"19\">19</sup>, המדריגה הב' שנשתקע בשינה וצריכים להקיצו, המדריגה הג' שמי שנתעלף אז צריכים להקיצו ברפואות וסמים, ונכתב בספרי הרפואות סגולה לזה שילחשו לו באזנו שמו ואז יקיץ מההתעלפות<sup data-n=\"20\">20</sup>, והמדריגה הד' למי שצריכים לעשות לו רפואה לחתוך לו אבר או בשר שנרקב ר\"ל אז נותנים לו בחוטמו סם להריח ונוטלים ממנו חוש ההרגש ואינו מרגיש כאב החיתוך. וכל הד' מדריגות הי' בכלל ישראל בזה\"ג שנמשל לשינה<sup data-n=\"21\">21</sup>, כי תיכף אחר החורבן בית שני הי' מדריגה הא' נים ולא נים, כי מי שהיה עם הארץ ולקח עצמו ללמוד תורה נעשה תנא או אמורא כמו ר\"ע וכדומה<sup data-n=\"22\">22</sup>, ואח\"כ נשתקע בשינה יותר שצריכים להקיצו היטב, ואח\"כ קודם התגלות הבעש\"ט נ\"ע הי' בכלל ישראל בחי' התעלפות וע\"כ ירד הבעש\"ט ז\"ל לעוה\"ז ליתן רפואות חזקות והם ד\"ח, וגם לחש באזניהם את שמם שנק' ישראל, כי יש לנו ב' מדריגות יעקב וישראל<sup data-n=\"23\">23</sup>, והבעש\"ט ז\"ל המשיך לתוך גופם את שרש נשמתם הנק' מזלא<sup data-n=\"24\">24</sup>, וגם שם ישראל, ולכן קראו לו בשמים להבעש\"ט דוקא בעל שם טוב<sup data-n=\"25\">25</sup>, שהוא המשיך למטה כתר ש\"ט, שהוא מדריג' משיח<sup data-n=\"26\">26</sup> שעולה על כל הג' כתרים<sup data-n=\"27\">27</sup>, ואח\"כ בזמן הזה ירדו כלל ישראל למדריגה הד' שירדו מלמעלה מקיפים דקליפה לעוה\"ז והם נוטלים חלק חוש ההרגש, הגם שרוא' בספרי קודש ושומע ד\"ח, מ\"מ אין להם חיות כלל מזה, והמכוון בזה למעלה שיפרד חלק הרע מן הטוב, הם הנשמות הנדחים ונאבדים בג' קה\"ט שלא יקלקלו לאחר, וטובה זו עשו לנו שהם נפרדים בכל הענינים, הן במלבושים והן בהתנהגות אפי' בדברים שבקדושה כמו בבהכנ\"ס ושארי דברים, ואפי' בבית הקברות פורשים א\"ע להיות להם מקום מיוחד ולא יקברו אצל האנשים הישרים והתמימים, והם שונאים בתכלית לאיש חסיד וישר וזאת לטובתינו וד\"ל<sup data-n=\"28\">28</sup>, וע\"כ זה דומה לחיתוך בשר החי שלא יקלקל בשר הבריא, ואם הי' בזה\"ז גילוי אלקות כמו בימי הבעש\"ט ז\"ל ואדמו\"ר הזקן נ\"ע לא הי' הפירוד והבירור חלק הרע מן הטוב, כי מי פתי יעבור עבירה ח\"ו בפרהסיא כמו חלול שבת וכדומה, וממילא הי' הרע נשאר צפון בלבם והי' ביכולתם לקלקל לאחרים, כמו מ\"ד<sup data-n=\"29\">29</sup> ותלמידיו<sup data-n=\"30\">30</sup> ימ\"ש, שכמה נפשות החטיאו עבור שהחזיקו אותם לישרים, אך עתה שיצאו לתרבות רעה בפרהסיא אין מי שילמוד מהם וד\"ל. והטעם הב' שצריך להיות החשך וההסתר ממקיפים דקליפה כעת, כדי שלא ירגיש הכאב כ\"כ האדם הבריא בעבודת ה' כמו אב שיש לו בנים בזה\"ז שיצאו ופרשו א\"ע מן הכלל, עכ\"ז אינו מתפעל האב כ\"כ כי הרוח שטות שיש לאבות שנצרך לעסק הפרנסה ללמוד כתב ולשונות העמים, וחכמת חיצוני' המכסה על כל פשעים של הבן ומלמד זכות עליו ועל כל מעשיו, וע\"כ איננו מרגיש הכאב מהחיתוך וגיזור משורש נשמת הבן, ואם הי' מרגיש האב היסורי' לא הי' יכול לסבול מגודל עג\"נ שהי' לאב עבור פירוד הבן משרשו, וזה הי' הכרחיות מלמעלה שיפרדו הנשמות האלו מהכלל מחלק הטוב, וע\"כ ההסתר והחשך עושה פעולה טובה להאבות הישרים והתמימים שלא ירגישו כ\"כ, ובטעם הב' הוא דומה למשל ממש וד\"ל. אך עכ\"ז לבנ\"י הי' אור במושבותם<sup data-n=\"31\">31</sup> בחושך של מצרים, וכן עתה ג\"כ למי שיש לו אור החסידות אין החשך הזה מסתיר כלל. כל אלו הדברים שמענו מאדמו\"ר נ\"ע.\n<b>אך</b> עתה יש להבין דבר מתוך דבר להתיישב תוך לבנו מה שהתחילו דוקא החבלי משיח בתוקף גדול משנת תרנ\"א כידוע ולא קודם לכן, ולפי הענין הנ\"ל שיש ד' מדריגות בשינה, כך נוכל להבין שיש ד' מדריגות בקימה מן השינה, כידוע הדין בשו\"ע או\"ח<sup data-n=\"32\">32</sup> שבזמן קימה יש ד' זמנים, הזמן הא' הוא תיכף מעלות השחר אם יוצא לדרך וכדומה ומצוה מן המובחר לקרות ק\"ש בהנץ החמה, וזהו זמן הב', והזמן הג' עד ג' שעות היום שהוא חלק רביעי מהיום, והזמן הד' הוא כדעת הפוסקים שחושבים רביע היום מהנץ החמה עד שקיעתה ונמשך עוד ל\"ו מינוטין אחר ג' שעות, וכן פסק אדמו\"ר בסידור<sup data-n=\"33\">33</sup> כידוע, וכל הזמנים האלו מיוסדים על פסוק<sup data-n=\"34\">34</sup> ובקומך, בזמן שבנ\"א קמים משינתם<sup data-n=\"35\">35</sup>, ונמצא שיש ד' זמנים בענין הקימה של בנ\"א א' מעמוד השחר, ב' מהנץ החמה, ג' בני מלכים שדרכם לשכב עד ג' שעות ביום<sup data-n=\"36\">36</sup>, ועוד יש בנ\"א שהם קמים משינתם בזמן מאוחר יותר לפי דעת הפוסקים שנמשך מהנץ החמה ג' שעות, וזהו זמן הד'. וכך הי' לכלל ישראל שהם נצרכים לקום משינת הגלות הי' ג\"כ ד' זמנים, הזמן הא' מעלות השחר שהוא שנת ת\"ק לאלף השישי, שאז התחיל הבוקר כו' והזמן הב' מהנה\"ח שהוא שנת תק\"נ כידוע שמעלות השחר עד נץ החמה יש שעה וחומש שהם ד' מילין<sup data-n=\"37\">37</sup> והם חלק עשירי מן היום, ועל חשבון השנים חמשים שנה הם חלק עשירי מת\"ק שנה, ואז התחיל לזרוח שמש של אדמו\"ר הזקן ז\"ל נ\"ע ביותר תוקף ועוז, וע\"כ הי' קמים משינתם שינת הגלות כמה אלפים נשמות יותר מזמן הבעש\"ט ז\"ל שהיתה עלות השחר, כי אז קמו רק יחידי סגולה הגדולים, אבל בימי אדמו\"ר הזקן נ\"ע נתעוררו משינתם אפילו נשמות נמוכות כידוע<sup data-n=\"38\">38</sup>, כיון שנתגלה אור החסידות שהו\"ע יחו\"ע ויחו\"ת<sup data-n=\"39\">39</sup> שזה ענין ק\"ש בפרט כידוע<sup data-n=\"40\">40</sup>, והיתה נמשכת בתוקף גילוי מוחין עד ג' שעות היום שנת תרכ\"ה חלק רביעי מחמש מאות, ואח\"כ משנת תרכ\"ו שנסתלק אדמו\"ר בעל צ\"צ נ\"ע<sup data-n=\"41\">41</sup> ונסתלק גילוי המוחין שהוא בזמן ק\"ש והתחיל השעה הד' שהוא זמן תפלה, ותמשוך זמנה עד תרס\"ו<sup data-n=\"42\">42</sup> ושמונה חדשים שהוא שעה ד' שהוא זמן תפלה, וזהו קירוב יסוד עם מל' עפ\"י קבלה<sup data-n=\"43\">43</sup>, וע\"כ תהי' הגאולה שיהי' עליית המל' בשעה זו דוקא שהוא זמן תפלה, כידוע שבכל יום יש כמה עליות להשכינה הקדושה, ומתחיל מחצות לילה וגמר העלי' המובחרת הוא בעת התפלה<sup data-n=\"44\">44</sup>, וזה ידוע שעבודת התפלה היא דוקא בביטול חיצוני' בכריעת הגוף הגשמי<sup data-n=\"45\">45</sup> והוא העיקר דוקא בהודאה כי מאן דלא כרע במודים כו'<sup data-n=\"46\">46</sup> וע\"כ בשעה זו התחילו חבלי משיח ויסורי' גדולים כידוע, כי לנטוע בלב האדם בחי' ההודאה, הגם שמוחין והמדות אהוי\"ר נסתלקו עכ\"ז נשאר בחי' ההסכם וההודאה, וע\"ז יש כמה מס\"נ לנשמות נמוכות מאד רק על ההודאה לבד שאמונתם אמת היא ואינם רוצים לבטלה, ואינם רוצים להחליף את שמם כידוע, וזהו קעומ\"ש דוקא בביטול חיצוני' תהי' הכוונה להתגלות מל' דקדושה ועצמו' אוא\"ס ולא ע\"י מוחין ומדות, ע' בשערי אורה שער חנוכה<sup data-n=\"47\">47</sup>, וע\"כ עבודה זו של תפלה מתחלת בשעה ד', אך עכ\"ז צריך להבין למה לא התחילה תיכף עבודה זו של תפלה מתחילת השעה הד' שהוא שנת תרכ\"ו ולמה נמשכת עד שנת תר\"נ שלא הי' החבלי משיח בתוקף כ\"כ, ע\"ז יש טעם אחר שזה עשה ד' בגודל רחמיו להתמשך עוד הזמן ק\"ש כדעת הפוסקים שחושבי' מהנץ החמה, ונמצא שנמשך עוד ל\"ו מינוטין ועל חשבון השנים הוא כ\"ה שנים, וע\"כ היא נמשכת עוד כ\"ה שנים עד שנת תר\"נ שהוא סוף זמן ק\"ש מהנץ החמה, ואחר זמן זה התחילה הגירוש מערי רוסיא, ונתגלגל דחקות הפרנסה ועול הגלות בכל עיר ועיר במדינה זו, ועבור זה הקיצו משינתם שינת הגלות אפילו נשמו' של המדריגו' הד' שנשתקעו בשינה הרבה ונפלו ר\"ל בגקה\"ט לגמרי, עכ\"ז נתעוררו משינתם ומסרו נפשם לסבול גירוש וטלטול ממקום למקום ולא החליפו והמירו דתם ח\"ו וזהו הקימה בשלימות לכל ישראל לכל העשר מדריגו' שיש בישראל, ראשיכם שבטיכם וגו' עד שואב מימיך<sup data-n=\"48\">48</sup>, ובזכות זה יקוים הפסוק<sup data-n=\"49\">49</sup> לעברך בברית שהוא יסוד, ויהי' התחברות יסוד עם מל', ותהי' סמיכת גאולה לתפלה, ותהי' אי\"ה הגאולה בשלימות אמן סלה.\n**********",[["1","1","המאמר נדפס בספר מגדל עז (כפ\"ח, תש\"מ) ע' שנז ואילך. ועם שינויים – בהוספות לספר המאמרים תרס\"ג ח\"א ע' קמב ואילך. המאמר נדפס כאן מספר המאמרים שם, וניתוספו הערות וציונים (כמה מהם נעתקו ממגדל עז שם).\nבשיחת ח\"י אלול ה'שי\"ת – שספק אם המאמר הוא מרבי או מחסיד. בלקו\"ש ח\"ב ע' 516 כותב ע\"ד מאמר זה: \"נמצא בכת\"י דא\"ח ישן (אינו ברור למי הוא)\". בלקו\"ש חי\"ב ע' 165: \"דא\"ח שבכתובים\". ובלקו\"ש חט\"ו ע' 282: \"כת\"י דא\"ח ישן (לא נודע למי)\". וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע חי\"ט ע' סו. מגדל עז ריש ע' שנז. שם ע' תרמא."],["2","2","התגלותו של הבעש\"ט הי' בשנת תצ\"ד (שיחת כ' כסלו תרצ\"ג – לקוטי דיבורים ח\"א לא, א ואילך. וראה לעיל סימן ערב. וש\"נ). וראה לקו\"ש חלק טו ע' 42: התגלות [הבעש\"ט] איז געווען ארום שנת ת\"ק."],["3","3","תהלים צ, ד. ב\"ר פ\"ח, ב. פרש\"י סנהדרין צז, א – ד\"ה תרי. ועוד."],["4","4","ראה מאמרי אדמו\"ר הזקן פרשיות ח\"א ע' תכ ואילך. ספר השיחות תש\"נ ח\"א ע' 254 ובהערות שם."],["5","5","ו, ב."],["6","6","בשלח טז, ה."],["7","7","מגן אברהם או\"ח סר\"נ סוסק\"א. שו\"ע אדה\"ז שם סעיף ח."],["8","8","שער הכוונות ענין טבילת ערב שבת. פרי עץ חיים שער השבת רפ\"ג. ירושלמי – הובא במטה משה סימן תח; של\"ה מסכת שבת קלב, סע\"ב."],["9","9","ראה לקו\"ש חלק טו ע' 282. חלק כ ע' 173. ועוד."],["10","10","ראה מסכת תמיד בסופה."],["11","11","ראה בבא בתרא עה, א. ויק\"ר פי\"ג, ג. ועוד."],["12","12","ראה זח\"א קלה, סע\"א ואילך (במהנ\"ע). שערי זוהר ברכות יז, א. לקו\"ת שמיני יח, א ואילך."],["13","13","ראה לקו\"ת צו יז, א. שער האמונה לאדמו\"ר האמצעי פנ\"ו. ובכ\"מ."],["14","14","ראה לקו\"ת שמיני שם. וראה לעיל סימן שמו-שמז."],["15","15","ראה שערי תשובה לאדמו\"ר האמצעי ח\"א ה, א."],["16","16","ברכות ג, א."],["17","17","ראה שערי תשובה שם ובהערות המו\"ל שם. וש\"נ. מאמרי אדמו\"ר האמצעי במדבר ח\"ב ע' תשעו ואילך. וראה גם פלח הרמון שמות ע' עג: בזה\"ג יש ירידות ועליות רבות כמו בדורות הראשונים שהי' שמדות וגזירות רח\"ל ואח\"כ בזמן האריז\"ל הי' עלי' ובטל הגזירות ואח\"כ כשנסתלק האריז\"ל ותלמידיו נחשך קצת ואח\"כ נתהווה עלי' גדולה ע\"י הבעש\"ט ותלמידיו נ\"ע כו'."],["18","18","ראה לקו\"ש שבהערה 1. ועוד."],["19","19","פסחים קכ, ב."],["20","20","ראה גם ספר המאמרים תרצ\"ט ע' 163. תש\"א ע' 82. תש\"ב ע' 73."],["21","21","זח\"ג צה, א. לקו\"ת שה\"ש לג, ג. ובכ\"מ."],["22","22","ראה נדרים נ, א. אדר\"נ פ\"ו."],["23","23","ראה זח\"ג רי, ב. תו\"א מקץ לו, ג. לקו\"ת בלק ע, ג."],["24","24","ראה שערי הקדושה להרח\"ו ח\"ג שער ה. לקו\"ת במדבר טז, א. ובכ\"מ."],["25","25","עוד ביאורים לשם \"בעל שם טוב\" – ראה לעיל סימן שיח. וש\"נ."],["26","26","ראה אמרי בינה שער הק\"ש פמ\"ז-מח. שערי אורה שער החנוכה ד\"ה כתיב כי אתה נרי פי\"ט (נא, ב). תו\"ח שמות ריח, ב. תרא, א ואילך."],["27","27","אבות פ\"ד מי\"ג."],["28","28","ראה מאמרי אדמו\"ר האמצעי קונטרסים ע' רעג."],["29","29","= משה דעסווער. – המשכיל משה מענדלסאָן מדעסוי."],["30","30","ראה גם קונטרס \"אדמו\"ר הצמח צדק ותנועת ההשכלה\" ע' 56 הערה 94."],["31","31","בא י, כג."],["32","32","ראה שו\"ע או\"ח סנ\"ח ס\"א-ד."],["33","33","הל' ק\"ש. וראה שו\"ע אדה\"ז או\"ח סתמ\"ג ס\"ד."],["34","34","ואתחנן ו, ז."],["35","35","ראה ברכות י, ב."],["36","36","ראה שם ט, ב."],["37","37","ראה פסחים צד, א."],["38","38","ראה ספר השיחות תורת שלום ע' 86. שיחת יט כסלו תרצ\"ב (לקו\"ד ח\"ד תשנה, ב ואילך). ועוד."],["39","39","ראה הקדמה לאמרי בינה."],["40","40","זח\"א יח, ב. תניא שער היחוד והאמונה בתחילתו. שם פ\"ז."],["41","41","י\"ג ניסן תרכ\"ו."],["42","42","על הקץ דשנת תרס\"ו – ראה לקו\"ש ח\"ז ס\"ע 209. מגדל עז ע' תצא."],["43","43","ראה אוה\"ת תשא ע' א'תתעז. שבת שובה ע' א'תעח."],["44","44","ראה לקו\"ת שה\"ש לא, ד. לב, ג. אוה\"ת מסעי ע' א'תד. נצבים ע' א'רלז."],["45","45","ראה אוה\"ת נח ח\"ג תרג, א."],["46","46","בבא קמא טז, א. זח\"ב ק, א. לקו\"ת בלק עא, א. מאמרי אדמו\"ר הזקן הקצרים ע' שנג. אוה\"ת בראשית ח\"ה תתקלז, א."],["47","47","ד\"ה בכ\"ה בכסלו פמ\"ט ואילך (כ, ב ואילך)."],["48","48","נצבים כט, ט-י. לקו\"ת ר\"פ נצבים."],["49","49","נצבים שם, יא."]]],[300010947,"תיט\n\n<b>ליקוט ביאורים מכ\"ק אדמו\"ר זי\"ע</b><sup data-n=\"1\">*</sup>\n<b>לשבעת התורות שאמר מורנו הבעש\"ט</b>\n<b>בש\"פ תבוא, ח\"י אלול, תרנ\"ב, בגן עדן</b>\n<b>פתיחה</b>\n<b>משיחת כ\"ק אדמו\"ר מהוריי\"צ ליל שמיני עצרת תרצ\"ז</b><sup data-n=\"2\">1</sup>\nביום ו' עש\"ק יו\"ד אלול תרנ\"ב הי' חתונת דודתי מוסיא<sup data-n=\"3\">2</sup>, השבע ברכות האחרונות היו ביום ה', ביום הזה נסע אאמו\"ר על האוהל\n– בכלל הי' אצלו מסודר בדבר הביקור על האוהל, לבד הזמנים הקבועים הי' בזה גדרים<sup data-n=\"4\">3</sup>: א' – הי' אצלו ענינים שאינם ידועים. גדר הב' – עבור הידידים, כמו הרי\"מ מפּאָלטאַווא ז\"ל<sup data-n=\"5\">4</sup> (ישנם המכתבים שהשיב אאמו\"ר: קבלתי מכתבו והייתי באהלי קודש וספרתי דבריו, ופעם כותב: וספרתי עניניו). גדר הג' – שהי' נוסע לבקש על עניני חסידות שיונחו<sup data-n=\"6\">5</sup>, וישנם נזכרים בהפ\"נ מאמרים להבינם –\nבבואו מהאוהל ביום ה' הנ\"ל הי' השבע ברכות ואמר מאמר שוש תשיש, ואמר כי הוא מאמר הל\"ב שאמר אביו (אאזמו\"ר) אחר חתונתו<sup data-n=\"7\">6</sup>.\nביום ו' עש\"ק נסע עוד הפעם על האוהל, והי' שם עד זמן מאוחר<sup data-n=\"8\">7</sup>, ובבואו הי' ניכר בעיניו (עס זיינען געווען געשוואָלן די אויגן<sup data-n=\"9\">8</sup>), אצל המקורבים הי' כל הענין לפלא בעיניהם נסיעתו ביום השבע ברכות על האוהל וגם למחרתו<sup data-n=\"10\">9</sup>.\nבש\"ק<sup data-n=\"11\">10</sup> תבוא הי' מאמר והי' כי תבוא. התפלה בש\"ק ההוא הי' עד שעה מאוחרת ביותר (כי בשנים ההם בכלל הי' הסדר אצלו כי הי' מתפלל עד שעה 2 או חצי שלישית, והי' מתחיל בבוקר השכם, והי' בביהכ\"נ רק לומר ברכו, לפעמים הי' בא באמירת הללוי', בעת אמירת ברכו הי' בביהכ\"נ והיו מחכים עליו בדרך הכבוד אבל לא בדרך נשיאות, כי על אחרים היו ג\"כ ממתינים, (על דודי הרז\"א לא היו צריכים להמתין)).\nאופן התפלה בש\"ק תבוא (הנ\"ל) הי' שלא כדרך הרגיל (עס האָט געשאָסן פייער), דרכו הי' בש\"ק ללמוד שיעורים לפני הקידוש, וישנם שיעורים שהי' לומד לאחר הקידוש, ובעת הקידוש הי' מברך על פירות העץ והאדמה להרבות בברכות, בש\"ק ההוא מחמת גמרו התפלה בשעה מאוחרת הספיק רק לקדש ולהתפלל מנחה וליטול הידים לסעודת ש\"ק.\nבשמע\"צ תרנ\"ג בעת הפאַרברענגען סיפר אאמו\"ר אודות היותו על האוהל ביום ה' (הנ\"ל), ואמר<sup data-n=\"12\">11</sup> כי דרכו אשר כל מאמר שרוצה לומר ברבים הנה אחרי היגיעה בו אינו אומרו עד שיש לו הוראה על זה, און די הוראה איז אז דער ענין ווערט בַא עם נתעצם<sup data-n=\"13\">12</sup>.\nהמאמר והי' כי תבוא הנה אחרי היגיעה בו לא נתעצם עמו, ואמר: אלך לבעל השמועה (המאמר הוא מאמר אאזמו\"ר מהר\"ש), הגם איך האָב עס געקענט מאַכן אין שטוב, איך האָב אָפט אַזוינע געסט, אך אמרתי אלך לבעל השמועה ונסעתי להאוהל, ולא פעלתי, שהענין עדיין לא נתעצם, ונסעתי למחר עוד הפעם על האוהל, ות\"ל פעלתי שהענין נתעצם.\nדער אויבערשטער בלייבט דאָך קיין בעל-חוב ניט<sup data-n=\"14\">13</sup>, איז פאַר דעם הנחת עצמותו ומסירה ונתינה, האָט מיר דער טאַטע (אדמו\"ר מהר\"ש) אָפּגעצאָלט: השבת ההוא הי' ח\"י אלול יום הולדת הבעש\"ט, ואמר לי אאמו\"ר (אדמו\"ר מהר\"ש) קום לאָמיר גיין הערן תורה פון דעם בעש\"ט<sup data-n=\"15\">14</sup>, ולקחני עמו. ואאמו\"ר<sup data-n=\"16\">15</sup> צייר המקום שהי' שם<sup data-n=\"17\">16</sup>, ואמר<sup data-n=\"18\">17</sup> כי זהו ההפלאה בהרוחני שהוא שטחי, ואמר בג\"ע יש סדר, כי אין חשבון בשאול כתיב<sup data-n=\"19\">18</sup>, אבל בג\"ע יש סדר.\nואמר אאמו\"ר{15} כי שמע באותו הש\"ק מהבעש\"ט שבעה תורות בזמנים מיוחדים<sup data-n=\"20\">19</sup> (כדלקמן).\n**********",[["1","*","בא' השיחות ע\"ד שבעת התורות שאמר מורנו הבעש\"ט בגן עדן בח\"י אלול, כותב כ\"ק אדמו\"ר (לקוטי שיחות חכ\"ד ע' 177) תוכן הדברים דלקמן בתור הקדמה:\nהשקו\"ט בתורת הבעש\"ט שנאמרה בח\"י אלול בא' השנים (שנת תרנ\"ב), היא, לאחרי שישים לנגד עיניו ויתבונן בהנקודה הפנימית שמתבטאת ב\"שמו אשר יקראו לו בלשון הקודש\" – ח\"י אלול – כלשון הרב, כ\"ק מו\"ח אדמו\"ר נשיא דורנו: \"א) ח\"י אלול הוא היום שהביא ומביא חיות באלול, ב) ח\"י אלול נותן חיות בעבודה דאני לדודי ודודי לי\".\nויש להוסיף בדרך אפשר, שהעבודה כללית דאני לדודי (שמביאה כללות הענין דדודי לי) נחלקת לפרטים, כמרומז גם בהר\"ת דאלול: \"<i>א</i>נה <i>ל</i>ידו <i>ו</i>שמתי <i>ל</i>ך\" – ענין ערי מקלט, וענינו בעבודת האדם התורה (דברי תורה קולטין), \"<i>א</i>ני <i>ל</i>דודי <i>ו</i>דודי <i>ל</i>י\" – קו העבודה היא התפלה, \"<i>א</i>יש <i>ל</i>רעהו <i>ו</i>מתנות <i>ל</i>אביונים\" – קו דגמילות חסדים, \"(ומל ה' אלקיך) <i>א</i>ת <i>ל</i>בבך <i>ו</i>את <i>ל</i>בב (זרעך)\" – ענין התשובה, הקדמה ויסוד לג' קוין הנ\"ל, \"<i>א</i>שירה <i>ל</i>ה' <i>ו</i>יאמרו <i>ל</i>אמר\" – ענין הגאולה, גמר ושלימות העבודה. ע\"כ."],["2","1","ספר השיחות תרצ\"ז ע' 189 ואילך*."],["3","2","הרבנית חי' מושקא, עם הרה\"ח וכו' מו\"ה משה האָרענשטיין. – ראה אודותם ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז. תשנ\"ז) ע' 22."],["4","3","ברשימה אחרת: לפעמים הי' הולך עבור טובה פרטית, ולפעמים עבור ענין כללי."],["5","4","ראה אודותו בהנסמן בספר השיחות תש\"ו ע' 11 הערה 17. וש\"נ."],["6","5","ברשימה אחרת מוסיף בענין זה: הי' הולך באופן שלא ידעו מזה – כמדומה שאמר שהי' הולך בשעה 4 ושב בשעה 6 – ולפעמים גם בחורף הי' הולך בהשכמה כ\"כ."],["7","6","ראה ספר התולדות הנ\"ל הערה 2 ע' 72, שמיום האופרופענעס [של אדמו\"ר מהורש\"ב] עד אחר שבעת ימי המשתה אמר אדמו\"ר מהר\"ש ל\"ב מאמרים."],["8","7","ברשימה אחרת: ובכה שם הרבה."],["9","8","ברשימה אחרת: די אויגן זיינען געווען רויט פון בכיות."],["10","9","ברשימה אחרת מוסיף: אָבער פרעגן איז ניט געווען שייך."],["11","10","ברשימה אחרת מקדים: תפלת המנחה (בערב ש\"ק) הי' אז בסדר של ערב ר\"ה."],["12","11","ברשימה אחרת: באַ אַייך איז דאָך געווען אַ פלא מיין גיין אויפן אוהל."],["13","12","ברשימה אחרת: איך זאָג ניט קיין חסידות ביז דאָס ווערט מיט מיר נתעצם, און אַז עס ווערט נתעצם – נאָכדעם דאַרף איך האָבן אַ הוראה אַז איך זאָל דאָס זאָגן."],["14","13","ברשימה אחרת: אין הקב\"ה מקפח שכר כל ברי'."],["15","14","ברשימה אחרת: אין ג\"ע."],["16","15","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["17","16","להעיר משיחת ליל שמח\"ת קודם הקפות ה'שי\"ת (ספר השיחות ה'שי\"ת ע' 373), וז\"ל:\nהוד כ\"ק אאמו\"ר הרה\"ק האָט יענעם שמח\"ת** געזאָגט בעת'ן פאַרבּריינגען:\nהערט רייד, וואס איך האָב געהערט אין גן עדן.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן אַרומגערעדט דעם סדר פון גן עדן התחתון און גן עדן העליון.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט געהאַט אַ זעלטענעם חוש הציור, אין יעדע זאַך האָט ער מבאר ומסביר געווען אַז מען האָט דעם ענין געזעהען במוחש. ווען הוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן גערעדט דעם הבדל פון געה\"ת און געה\"ע, און דעם סדר העליות, האָט מען דאָס געזעהען (כ\"ק אדמו\"ר שליט\"א*** הראה באצבעותיו) במוחש ממש. און הוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן געזאָגט:\nאיך זעה דאָס. און איר הערט לכל הפחות און דערהערט.\nמיר האָט מען געגעבן אַ כח צו הערן דברי הרב. אַז איך האָב געהערט אַ מאמר פון טאַטן, האָב איך געהערט די רייד פון טאַטן, פון זיידן, פון עלטער זיידן, פון רבי'ן, פון מעזריטשער מגיד און פון בעש\"ט, וואָס ער האָט מקבל געווען מאחי' השילוני."],["18","17","ברשימה אחרת: וואָס פאַר אַ השערה קענט איר האָבן אין דעם מקום פון ג\"ע!"],["19","18","ע\"פ לשון הכתוב – קהלת ט, יו\"ד."],["20","19","כ\"ק אדמו\"ר מהוריי\"צ חזר על שבעת התורות בזמנים מיוחדים: תורה הא' והב' – בהמשך שיחה זו (דליל שמע\"צ), תורה הג' הד' והה' – בשיחת שמח\"ת לפני הקפות, תורה הו' – בשיחת ש\"פ בראשית בעת הקידוש, ותורה הז' – בשיחת ש\"פ בראשית בסעודה.\n-----שולי הגליון-----\n*) <i>ראה גם מכתב אדמו\"ר מהוריי\"צ מכ\"ט מנ\"א תרצ\"ז (אגרות-קודש ח\"ד ע' קיז): \"גמירא מילתא – ע\"פ ספור מקובל מהוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע – אשר בו ביום – ח\"י אלול – אומר כ\"ק רבנו הבעש\"ט נ\"ע דברי תורה ברבים לפני תלמידיו ותלמידי תלמידיו וכל המקושרים אליהם, כפי אשר ספרתי בארוכה בחג הסוכות העבר\".</i>\n**) <i>בהתחלת הפיסקא שם: \"</i>תרנ\"ד <i>איז געווען אַ יאָהר פון גרויסע גילויים\". אבל, מתוכן הדברים אודות הדיבורים ששמע בגן עדן, אואפ\"ל שהכוונה היא לשמיעת שבעת התורות שאמר מורנו הבעש\"ט בגן עדן (בח\"י אלול תרנ\"ב), כפי שסיפר בשמח\"ת הסמוך בשנת </i>תרנ\"ג<i> (כמסופר </i>בארוכה ובפרטיות<i> בשיחת ליל שמע\"צ תרצ\"ז (כנ\"ל))</i>.<i> ולהעיר</i>,<i> שבא' ההעתקות מהשיחה שתח\"י נרשם</i>: תרנ\"ג<i> (</i>המו\"ל<i>)</i>.\n***) <i>כ\"ק אדמו\"ר מהוריי\"צ נ\"ע</i>."]]],[300010948,"תכ\n\n<b>התגלות שבעת התורות שאמר מורנו הבעש\"ט</b>\n<b>ע\"י נשיאי חב\"ד</b>\nא. יש להקדים תחילה הלימוד וההוראה (תורה) מאופן התגלות תורות אלו – שז' התורות שאמר מורנו <i>הבעש\"ט</i> נתגלו ע\"י <i>נשיאי חב\"ד</i> דוקא:\nאע\"פ שחלק מז' התורות (ב' תורות הראשונות) נאמרו בהקהל, במעמד <i>כל תלמידי הבעש\"ט</i> ותלמידי תלמידיהם והחסידים שלהם, מ\"מ, התגלותם למטה לא היתה ע\"י שאר תלמידי הבעש\"ט, אלא ע\"י <i>נשיאי חב\"ד</i> – כ\"ק אדמו\"ר מהורש\"ב נ\"ע (ששמע בעצמו ז' התורות שאמר מורנו הבעש\"ט בגן עדן), וכ\"ק מו\"ח אדמו\"ר (שגילה ופירסם תורות אלו ברבים), ממלאי מקום של (רבותינו נשיאינו שלפניהם עד ל)אדמו\"ר הזקן מייסד חסידות חב\"ד.\n– ישנם הטוענים על חסידי חב\"ד: היתכן ש\"לוקחים לעצמם\" (\"זיי נעמען אַריין צו זיך\") גם את הבעש\"ט (וכן את תלמידו ממלא מקומו המגיד), בה בשעה שישנם עוד כמה וכמה תלמידי הבעש\"ט?! – הנה טענה זו יש לה מקום רק בנוגע להתורות שאמר הבעש\"ט בחיים חיותו <i>בעלמא דין</i>, שנמסרו גם לשאר תלמידי הבעש\"ט, \"נהרא נהרא ופשטי'\"<sup data-n=\"1\">1</sup>, אבל בנוגע להתורות שאמר הבעש\"ט (לאחרי הסתלקותו) <i>בגן עדן</i>, הרי לא נמסרו למטה ע\"י שאר תלמידי הבעש\"ט אלא ע\"י נשיאי חב\"ד דוקא<sup data-n=\"2\">2</sup>.\nונקודת הענין – שבמשך הזמן הולך ומתגלה יותר הקשר והשייכות שבין תורת החסידות הכללית לתורת חסידות חב\"ד, שאינם ב' ענינים בפ\"ע, אלא ענין אחד, שתורת חסידות חב\"ד \"היא היא תורת הבעש\"ט\"<sup data-n=\"3\">3</sup>, ועל ידה נעשה עיקר הענין ד\"יפוצו מעינותיך (דהבעש\"ט) חוצה\".\nב. ויובן בהקדם הביאור בענינו של <i>ח\"י אלול</i> – היום שבו שמע כ\"ק אדנ\"ע שבעת התורות שאמר מורנו הבעש\"ט, וקרוב לומר שמאורע זה שייך לתוכנו של היום – שנוסף על היותו יום הולדתו של הבעש\"ט (מייסד תורת החסידות הכללית), ה\"ה גם יום הולדתו של אדמו\"ר הזקן (מייסד תורת חסידות חב\"ד), ובלשון הידוע<sup data-n=\"4\">4</sup> \"יום הולדת (שמזלו גובר<sup data-n=\"5\">5</sup>) את <i>שני</i> המאורות הגדולים\":\nבהשוואת הבעש\"ט ואדמו\"ר הזקן ל\"שני המאורות הגדולים\" מודגש שענינם של הבעש\"ט ואדמו\"ר הזקן אחד הוא – בדוגמת \"שני המאורות הגדולים\" שהם (שני חלקים של) ענין אחד, שנבראו ביום אחד, ברגע אחד, בדיבור אחד, באותם אותיות (\"מאורות\"<sup data-n=\"6\">6</sup>), ולשם אותה תכלית (\"להאיר על הארץ\") – <i>גילוי החסידות</i>, שעל ידה מתגלה הנשמה והחיות דתומ\"צ<sup data-n=\"7\">7</sup>.\nאלא שכללות הענין דגילוי החסידות מתחלק בפרטיות לב' אופני עבודה (<i>שני</i> המאורות)<sup data-n=\"8\">8</sup>: גילוי החסידות ע\"י הבעש\"ט – שעיקרו<sup data-n=\"9\">9</sup> באופן של המשכה <i>מלמעלה למטה</i>, התגלות פנימיות התורה \"שלא בבחי' התלבשות\", וגילוי החסידות ע\"י אדמו\"ר הזקן – שעיקרו{9} באופן של העלאה <i>מלמטה למעלה</i><sup data-n=\"10\">10</sup>, התגלות פנימיות התורה \"בהתלבשות בהשגה\", לעשות את התחתון כלי מוכשר לגילוי החסידות<sup data-n=\"11\">11</sup>.\nוכמודגש גם בהחילוק שאצל הבעש\"ט הי' סדר עבודה של עשיית מופתים, הנהגה נסית, ועד שכללות הנהגה דעשיית מופתים נקראת \"אַ בעל-שם'סקע הנהגה\", שזהו סדר עבודה באופן של גילוי מלמעלה למטה; ואילו אצל אדמו\"ר הזקן, אף שהיו ריבוי מופתים, מ\"מ, לא היתה הדגשה (כ\"כ) על ענין המופתים<sup data-n=\"12\">12</sup>, כי אם, על לימוד תורת החסידות באופן של הבנה והשגה בשכל האדם (חכמה בינה ודעת), מלמטה למעלה.\nוזהו גם כללות החילוק שבין שיטת פולין (שאר תלמידי הבעש\"ט) לשיטת חב\"ד<sup data-n=\"13\">13</sup> – ששיטת פולין היא ש\"צדיק <i>באמונתו</i> יחי'\"<sup data-n=\"14\">14</sup>, א\"ת יִחְי' אלא יְחַי', מלמעלה למטה, ואילו שיטת חב\"ד היא שכל אחד ואחד צריך להתייגע <i>בידיעת</i> אלקות (\"<i>דע</i> את אלקי אביך\"<sup data-n=\"15\">15</sup>) באופן של <i>הבנה והשגה</i>, מלמטה למעלה.\nוהשלימות דגילוי החסידות היא בחיבור ב' האופנים דהמשכה מלמעלה למטה והעלאה מלמטה למעלה (שני המאורות הגדולים) גם יחד.\nג. ובפרטיות יותר:\nהסדר הוא שתחילה באה ההמשכה מלמעלה למטה, ולאח\"ז באה ההעלאה מלמטה למעלה, היינו, שהעבודה בכח עצמו (מלמטה למעלה) באה לאחרי הקדמת הנתינת-כח ע\"י ההמשכה מלמעלה למטה<sup data-n=\"16\">16</sup>.\nוע\"ד הסדר בכללות הענין דמתן תורה – \"ואני המתחיל שנאמר<sup data-n=\"17\">17</sup> וירד ה' על הר סיני\"<sup data-n=\"18\">18</sup>, המשכה ונתינת-כח מלמעלה למטה, כדי שלאח\"ז תהי' העבודה בכח עצמו מלמטה למעלה (ובכללות יותר – כ\"ו דורות שלפני מ\"ת שהיו ניזונין בחסדו של הקב\"ה<sup data-n=\"19\">19</sup>, המשכה מלמעלה למטה, ולאח\"ז העבודה מלמטה למעלה במ\"ת).\nוי\"ל שעד\"ז הוא הסדר בהתגלות החסידות – שתחילה הי' הגילוי דתורת החסידות הכללית ע\"י הבעש\"ט מלמעלה למטה, ולאח\"ז גילוי תורת חסידות חב\"ד ע\"י אדמו\"ר הזקן מלמטה למעלה.\nולאחרי שנעשית ההמשכה מלמעלה למטה (ע\"י הבעש\"ט) וההעלאה מלמטה למעלה (ע\"י אדמו\"ר הזקן), נעשה גם החיבור והיחוד ד\"שני המאורות הגדולים\" – שהגילוי מלמעלה למטה שבתורת החסידות הכללית נמשך ובא בעבודה בכח עצמו מלמטה למעלה בתורת חסידות חב\"ד, ובעבודה מלמטה למעלה בתורת חסידות חב\"ד ניכר ונרגש הגילוי מלמעלה למטה שבתורת החסידות הכללית שמתבארת בתורת חסידות חב\"ד.\nוענין זה מודגש ביותר בח\"י אלול תרנ\"ב – ששבעת התורות שאמר מורנו הבעש\"ט ביום זה, יום הולדת שני המאורות הגדולים, נמשכו ונתגלו למטה ע\"י נשיאי חב\"ד (כ\"ק אדנ\"ע וכ\"ק מו\"ח אדמו\"ר), ממלאי מקומו של אדמו\"ר הזקן, מייסד תורת חסידות חב\"ד.\nד. ויש לומר, שנוסף על החיבור דתורת חסידות הכללית (מלמעלה למטה) עם תורת חסידות חב\"ד (מלמטה למעלה) שבהתגלות ז' תורות הבעש\"ט ע\"י נשיאי חב\"ד, מודגש יותר החיבור דמלמעלה למטה ומלמטה למעלה באופן ההתגלות דתורות הבעש\"ט ע\"י נשיאי חב\"ד גופא – שבח\"י אלול תרנ\"ב שמע כ\"ק אדנ\"ע שבעת התורות שאמר מורנו הבעש\"ט <i>בגן עדן</i>:\nמאורע זה – שבח\"י אלול תרנ\"ב עלה כ\"ק אדנ\"ע לגן עדן, בחיים חיותו בעלמא דין, ושמע שבעה תורות שאמר מורנו הבעש\"ט – הוא <i>מופת נפלא</i>.\nוע\"פ הידוע{12} סדר ההנהגה בחב\"ד בנוגע לעניני \"מופתים\", שאף שאצל רבותינו נשיאינו ראו ריבוי מופתים, ובפרט לאחרונה, מ\"מ, לא עשו מזה ה\"שטורעם\" המתאים – צריך להבין: למה עשו \"שטורעם\" וגילו ופירסמו ברבים שכ\"ק אדנ\"ע עלה לגן עדן ושמע תורות מהבעש\"ט?! ע\"פ סדר ההנהגה בחב\"ד היו צריכים לגלות ולפרסם את <i>התוכן</i> דשבעת התורות, ללא הקדמת <i>המופת</i> שבפרטי הדברים, שתורות אלו שמע כ\"ק אדנ\"ע ממורנו הבעש\"ט בגן עדן בח\"י אלול תרנ\"ב?!\nומלבד התמיהה הכללית על עשיית \"שטורעם\" ע\"ד נס ומופת – יש להקשות יותר בנדו\"ד שמדובר אודות נס ומופת <i>בתורה</i>:\nתורה – \"לא בשמים היא\"<sup data-n=\"20\">20</sup>, אלא ניתנה למטה לנשמות בגופים ובטבע העולם<sup data-n=\"21\">21</sup>, ורק נשמות בגופים למטה יכולים לפסוק פס\"ד בתורה<sup data-n=\"22\">22</sup>. ומובן, שכלל זה הוא לא רק בנוגע לפסקי הלכות בנגלה דתורה, אלא גם בנוגע להוראות שבתורות הנ\"ל שבהם מדובר אודות ענינים הנוגעים <i>לעבודה בפועל</i> דנשמה בגוף<sup data-n=\"23\">23</sup> – מסירת נפש על פירסום אלקות בעולם (\"לשכן שמו שם\") ע\"י \"ברכה ופסוק תהלים\", וכיו\"ב.\nוא\"כ, נוסף על התמיהה שבפירסום <i>נס ומופת</i> שבהתגלות התורות, הרי, התגלות התורות שאמר מורנו הבעש\"ט בגן עדן כשלעצמה היא היפך הכלל ש\"לא בשמים היא\"?!\nה. ויש לומר הביאור בזה – ע\"פ האמור לעיל בנוגע לגילוי תורת החסידות באופן של חיבור תורת חסידות הכללית עם תורת חסידות חב\"ד:\nהתגלות שבעת התורות של הבעש\"ט (לכ\"ק אדנ\"ע, ועל ידו לכל בנ\"י בעלמא דין) באופן <i>נסי</i> דוקא (עי\"ז שכ\"ק אדנ\"ע שמע תורות אלו בגן עדן) – הו\"ע של המשכה <i>מלמעלה למטה</i> בתכלית (לא כלימוד התורה ע\"ד הרגיל ע\"י יגיעה בכח עצמו, מלמטה למעלה).\nוביחד עם זה, ההמשכה מלמעלה למטה שבהתגלות שבעת התורות באופן <i>נסי</i>, נתגלתה ונמסרה ע\"י כ\"ק אדנ\"ע (ובנו ממלא מקומו כ\"ק מו\"ח אדמו\"ר), נשיא <i>חב\"ד</i>, ממלא מקומם של רבותינו נשיאינו עד לאדמו\"ר הזקן מייסד תורת חסידות חב\"ד – שעי\"ז נתלבשה באותיות השכל דחב\"ד, כדי שתהי' בזה העבודה בכח עצמו <i>מלמטה למעלה</i><sup data-n=\"24\">24</sup>.\nובפרטיות יותר – שלאחרי שכ\"ק אדנ\"ע שמע שבעת התורות בג\"ע, התבונן והתעמק בהם עד שנקלטו ונתעצמו בשכל (חב\"ד) שלו, ועי\"ז נעשו תורות אלו פס\"ד והוראה לכל בנ\"י (בבוא הזמן שנתגלו ע\"י כ\"ק מו\"ח אדמו\"ר) – תורה והוראה שנמסרה ע\"י <i>נשמה בגוף</i>, כפי שמצינו דוגמתו גם בפסקי הלכות בנגלה דתורה, ש\"תנאים<sup data-n=\"25\">25</sup> ואמוראים הגדולים היו מביטין אורחין ושבילין דאא\"ס באותן ההלכות . . ולפי השגתם בארחות אא\"ס כך יפסוק הדין וההלכה\"<sup data-n=\"26\">26</sup> (ועד\"ז מצינו בכ\"מ שגדולי ישראל פסקו הלכות על יסוד מה שקיבלו בשמים, מאליהו הנביא, וכיו\"ב<sup data-n=\"27\">27</sup>), כי, לאחרי השגתם בארחות דאא\"ס התייגעו גם בהבנה והשגה ע\"פ <i>השכל</i> שלהם, עד שהפס\"ד בפועל הי' מצד ההבנה וההשגה <i>דנשמה בגוף</i><sup data-n=\"28\">28</sup>, ועד\"ז בנדו\"ד.\nו. ומזה מובן גם בנוגע להפירסום ברבים שתורות אלו שמע כ\"ק אדנ\"ע ממורנו הבעש\"ט בעלותו לגן עדן בחיים חיותו בעלמא דין:\nבשביל העבודה בכח עצמו <i>מלמטה למעלה</i> – מספיק לגלות רק את התוכן דשבעת התורות בנוגע לעבודה בפועל; אבל כדי שיהי' ניכר בעבודה <i>מלמטה למעלה</i> הנתינת-כח <i>מלמעלה למטה</i>, שעי\"ז תהי' העבודה מלמטה למעלה באופן נעלה יותר – צריך לגלות גם שתורות אלו נתגלו ונמסרו באופן <i>נסי</i>, ע\"י פירסום המאורע שכ\"ק אדנ\"ע עלה לגן עדן ושמע תורות אלו<sup data-n=\"29\">29</sup>.\nוכמובן בפשטות שכאשר יהודי שומע שנעשה <i>שינוי במעשה בראשית</i> (שכ\"ק אדנ\"ע עלה לגן עדן ושמע תורות שאמר הבעש\"ט) בכדי למסור לו הוראות בעבודת ה'<sup data-n=\"30\">30</sup> – ה\"ז מוסיף <i>התפעלות וחיות ותוקף</i> בקיום ההוראות בעבודה בפועל.\n[ולהעיר: ישנם \"שפּיץ-חב\"ד\" הטוענים שאין להתפעל מעניני מופתים, וראי' לדבר – טוענים הם – מתורת הבעש\"ט<sup data-n=\"31\">31</sup> ש\"ענין הנס הוא שנתחדש הדבר בפעם הראשון על הטבע . . ואח\"כ נעשה זה טבע ג\"כ\", היינו, שלאמיתתו של דבר אין הפרש וחילוק בין טבע לנס, ובמילא, כשם שלא מתפעלים מטבע כך לא צריכים להתפעל מנס.\nאבל, נוסף לכך שבדברים הנוגעים להם באמת, בני חיי ומזוני, יודעים ומרגישים היטב החילוק שבין טבע לנס [שכאשר המצב אינו כרצונם אזי מרעישים עולמות ומבקשים שיעשו להם נס], הרי, ע\"פ תורת-אמת יש חילוק בין הנהגה טבעית להנהגה נסית, ולדוגמא: צמיחת התבואה ע\"י הזריעה – גם כאשר פעולת הזריעה היא לא מפני שסומך על הנהגת הטבע, אלא מפני ש\"מאמין<sup data-n=\"32\">32</sup> בחי העולמים וזורע\"<sup data-n=\"33\">33</sup>, ה\"ז סו\"ס \"לחם מן הארץ\" (כנוסח הברכה) שצמיחתו ע\"י הנהגה טבעית, משא\"כ מאורע בלתי רגיל היפך הנהגת הטבע (הנהגה נסית), שחייבים לברך עליו \"ברכת הנסים\", ובודאי שהנהגה זו צריכה לעורר ומעוררת התפעלות גדולה.\nומזה מובן גם (ובמכ\"ש וק\"ו) בנוגע לנס ומופת שכ\"ק אדנ\"ע שמע ז' התורות שאמר מורנו הבעש\"ט בגן עדן – שסיפור זה צריך לעורר ומעורר התפעלות והתרגשות מיוחדת, ועי\"ז ניתוסף חיות ותוקף בקיום ההוראות דתורות אלו בעבודה בפועל].\nוכפי שרואים במוחש שאף שמקיימים הוראה <i>שמתבקשים</i> לקיימה, ועאכו\"כ <i>כשנדרשים</i> לקיימה שאז בודאי ובודאי מקיימים אותה – אין זה מגיע להחיות והתוקף בקיום הוראה מיוחדת שבאה ע\"י <i>שינוי מעשה בראשית</i>!\nז. ויש להוסיף, שכללות החיבור דתורת חסידות הכללית עם תורת חסידות חב\"ד – שתורת חסידות חב\"ד \"היא היא תורת הבעש\"ט\", ועל ידה נעשה עיקר הענין ד\"יפוצו מעינותיך (דהבעש\"ט) חוצה\" (כנ\"ל ס\"א) – הולך וניתוסף ככל שמתקרבים יותר לימות המשיח:\nמהטעמים<sup data-n=\"34\">34</sup> שדוקא בדורות האחרונים<sup data-n=\"35\">35</sup> נעשה הגילוי דפנימיות התורה בכלל, ובפרט הגילוי דתורת החסידות, תורת החסידות הכללית, ולאח\"ז תורת חסידות חב\"ד, ומוסיף והולך בהפצת המעיינות חוצה מדור לדור, אע\"פ ש\"אכשור דרי\" (בתמי')<sup data-n=\"36\">36</sup> – מפני שגילוי פנימיות התורה ותורת החסידות הוא הכנה מעין ודוגמא לעיקר ושלימות גילוי פנימיות התורה בביאת המשיח<sup data-n=\"37\">37</sup>, כמו הטעימה בערב שבת לאחרי חצות ממאכלי השבת, כמ\"ש \"טועמי' חיים זכו\"<sup data-n=\"38\">38</sup>.\nוכיון שבימות המשיח תהי' אצל כאו\"א מישראל ידיעת אלקות באופן של הבנה והשגה, כמ\"ש \"כי <i>כולם ידעו</i> אותי\"<sup data-n=\"39\">39</sup>, ועד ש\"מלאה <i>הארץ דעה</i> את ה' כמים לים מכסים\"<sup data-n=\"40\">40</sup>, מובן, שעיקר ושלימות ההכנה מעין ודוגמא לביאת המשיח היא ע\"י היגיעה <i>בידיעת</i> אלקות באופן של <i>הבנה והשגה</i> דוקא, שזהו\"ע דתורת חסידות חב\"ד.\nולכן, כללות החילוק בין שיטת תורת החסידות הכללית לשיטת תורת חסידות חב\"ד שייך רק בהתחלת הגילוי דתורת החסידות, אבל ככל שהולכים ומתקרבים לימות המשיח, הולך וניתוסף בשלימות ההכנה ע\"י ההבנה והשגה באלקות שבתורת חסידות חב\"ד, שעל ידה דוקא נעשה \"יפוצו מעינותיך (דהבעש\"ט) חוצה\".\nח. ויש להביא משל לזה מהתפשטות והפצת המעיינות בגשמיות:\nמעיינות – התחלתם טיפין טיפין, ואח\"כ מתרבים מימיהם עד שנעשים לנהרות, נהרות קטנים ונהרות גדולים, שהולכים כולם אל הים הגדול. והסדר בזה – שככל שהולכים ומתקרבים אל הים הגדול, נשפכים הנהרות הקטנים לתוך נהרות גדולים, והנהרות הגדולים נשפכים לתוך הנהר הכי גדול, ועד שנשפכים כולם יחד לתוך הים הגדול.\nודוגמתו ברוחניות – שככל שהולכים ומתקרבים לזמן ש\"כולם ידעו אותי\" \"כי מלאה הארץ דעה את ה' כמים <i>לים</i> מכסים\" (ים הגדול), נעשית התפשטות והתרחבות גילוי תורת החסידות באופן שכל הנהרות, גם דתורת החסידות הכללית (\"נהרא נהרא ופשטי'\"{1}), נמשכים ומתגלים בתורת חסידות חב\"ד (מעין ודוגמת הים הגדול, \"דעה את ה' כמים לים מכסים\").\nט. עפ\"ז יש לבאר הטעם דהתגלות ופירסום ז' התורות שאמר מורנו הבעש\"ט ע\"י כ\"ק מו\"ח אדמו\"ר דוקא<sup data-n=\"41\">41</sup>:\nאע\"פ שהמאורע דשמיעת ז' התורות שאמר מורנו הבעש\"ט בגן עדן הי' בשנת <i>תרנ\"ב</i>, ובשמע\"צ <i>תרנ\"ג</i> סיפר כ\"ק אדנ\"ע פרטי המאורע (ברבים או בסעודתו בלבד), מ\"מ, כלל לא נזכר כ\"ז במשך <i>יותר מארבעים שנה</i>, ורק לאח\"ז (בשנת תרצ\"ז) נתגלה ונתפרסם לרבים<sup data-n=\"42\">42</sup> ע\"י כ\"ק מו\"ח אדמו\"ר נשיא דורנו.\nובטעם הדבר יש לומר – ע\"פ האמור לעיל שככל שהולך וניתוסף בהפצת המעיינות חוצה הולך וניתוסף בהמשכת וגילוי תורת החסידות הכללית בתורת חסידות חב\"ד כהכנה להשלימות ד\"כולם ידעו אותי\", וכיון ששלימות העבודה דיפוצו מעינותיך חוצה נעשית ע\"י כ\"ק מו\"ח אדמו\"ר נשיא דורנו, לכן נתגלו <i>על ידו</i> דוקא ז' התורות שאמר מורנו הבעש\"ט, שבזה מודגש המשכת וגילוי תורת החסידות הכללית בתורת חסידות חב\"ד.\n[וכל זה – בהוספה על המבואר במק\"א<sup data-n=\"43\">43</sup> בכללות הטעם דהתגלות תורת החסידות בדורות האחרונים בגלל הצורך בגילוי אור גדול יותר מצד התגברות החושך כפול ומכופל דזמן הגלות, וכהמשל דשחיקת האבן טובה שבכתר המלך כדי להציל את חיי בן המלך<sup data-n=\"44\">44</sup>, ועד\"ז בנוגע לדורנו זה, שמצד התגברות חשכת הגלות יש צורך והכרח בגילוי חדש דשבעת התורות שאמר הבעש\"ט בגן עדן כפי שבאים בתורת חסידות חב\"ד (לא רק בשביל <i>שלימות</i> העבודה, \"דע את אלקי אביך ועבדהו בלב שלם\"{15}, אלא גם) בשביל כללות העבודה דקיום התומ\"צ כפשוטו, כפי שרואים במוחש בהמדינות שבהם היו נסיונות גדולים על העבודה דקיום התומ\"צ, שאלה שלמדו תורת חסידות חב\"ד ונהגו בדרכי' ואורחותי', הצליחו לעמוד בכל הנסיונות ונשארו שלימים בקיום התומ\"צ].\nי. וההוראה והלימוד מזה בנוגע לפועל:\nכיון שעומדים בסמיכות להזמן ד\"כולם ידעו אותי\", יש להוסיף ולהרבות (ועד להוספה שמרובה על העיקר) בלימוד תורת חסידות חב\"ד, ולהשתדל ביותר בהפצת המעיינות חוצה באופן שגם אלה שעד עתה היו שייכים רק לתורת החסידות הכללית יתחילו לעסוק גם בלימוד תורת חסידות חב\"ד.\nואין לחשוש מפני הקושי שבידיעת אלקות באופן של הבנה והשגה, כי, נוסף על הכלל שאין לך דבר העומד בפני הרצון<sup data-n=\"45\">45</sup> [כפי שראו במוחש בין החסידים שגם בעלי כשרונות פשוטים הצליחו – ע\"י יגיעה כדבעי – להיות חסידים בעלי מעלה כו'], ישנה תוספת נתינת-כח חיזוק ועידוד מצד הידיעה שזוהי ההכנה וה\"כלי\" למהר ולזרז ולפעול קיום היעוד ד\"כולם ידעו אותי\", בגאולה האמיתית והשלימה ע\"י משיח צדקנו<sup data-n=\"46\">46</sup>.",[["1","1","חולין יח, ב. וש\"נ."],["2","2","מובן ופשוט שאין כוונת הדברים למעט מאומה ח\"ו מגדלות שאר תלמידי הבעש\"ט (ותורת החסידות הכללית), כי אם, להדגיש המעלה המיוחדת דנשיאי חב\"ד (ותורת חסידות חב\"ד)."],["3","3","אגרות-קודש אדמו\"ר מהורש\"ב ח\"א ע' רנט. וש\"נ."],["4","4","שיחת ח\"י אלול תש\"ג (ספר השיחות ע' 141 ואילך)."],["5","5","ראה ירושלמי ר\"ה פ\"ג ה\"ח ובקה\"ע שם."],["6","6","ורק אח\"כ (לאחרי \"<i>ויהי כן</i>\") נאמר \"את המאור הגדול גו' ואת המאור הקטן\"."],["7","7","ראה שיחת ח\"י אלול ה'ש\"ת (ספר השיחות ע' 170)."],["8","8","בהבא לקמן – ראה שיחת כ\"ק מו\"ח אדמו\"ר ליל ש\"ק פ' תשא שנת תפר\"ח (ספר השיחות תרפ\"ח-תרצ\"א ע' 19 ואילך). מכתב י\"ג אלול תש\"ט*. לקו\"ש חי\"ט ע' 255 ואילך."],["9","9","בעיקר ובגלוי, אבל, בודאי היתה אצל שניהם שלימות העבודה בשני הקוין דהעלאה והמשכה."],["10","10","ולהעיר שעבודתו של אדמו\"ר הזקן היתה בעשיית <i>בעלי תשובה</i> (ספר השיחות תורת שלום ע' 86) – העלאה מלמטה למעלה (משא\"כ עבודת הצדיקים שהיא המשכה מלמעלה למטה)."],["11","11","ראה ד\"ה פדה תרפ\"ה (סה\"מ תרפ\"ה ע' עט) בשם אביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע י\"ט כסלו עטר\"ת (נדפס בספר השיחות תורת שלום ע' 260)."],["12","12","ראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' שסב ואילך. וש\"נ."],["13","13","ראה לקו\"ד ח\"א קמא, ב. ועוד."],["14","14","חבקוק ב, ד. וראה מכות בסופה. תניא פל\"ג."],["15","15","דברי הימים-א כח, ט. וראה תניא (קו\"א) קנו, ב. ועוד."],["16","16","בלשון החסידות: אתערותא דלעילא, אתערותא דלתתא (לקו\"ת ויקרא ד\"ה אדם כי יקריב. <i>ובכ\"מ</i>)."],["17","17","יתרו יט, כ."],["18","18","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["19","19","פסחים קיח, א. וראה תו\"א ר\"פ בשלח. אוה\"ת בראשית רפח, א. קונטרס ומעין מאמר ח ואילך."],["20","20","לשון הכתוב – נצבים ל, יב. וראה ב\"מ נט, ב. תמורה טז, א. רמב\"ם הל' יסוה\"ת רפ\"ט."],["21","21","ראה גם לקו\"ד ח\"ד תשנב, ב ואילך."],["22","22","וכמחז\"ל (ב\"מ פו, א) \"קא מפלגי במתיבתא דרקיעא כו' הקב\"ה אומר כו' וכולהו מתיבתא דרקיעא אמרי כו', מאן נוכח, נוכח רבה בר נחמני\" – נשמה בגוף דוקא. ולדעת הרמב\"ם (הל' טומאת צרעת ספ\"ב) שפוסק דלא כרבה בר נחמני – פי' הכסף משנה \"דכיון דבשעת יציאת נשמה הוא דאמר הכי הוי בכלל לא בשמים היא\" (וראה לקו\"ת ס\"פ תזריע. לקו\"ש חי\"ב ע' 68 ובהערה 34)."],["23","23","ואולי י\"ל שזוהי עיקר הכוונה של כ\"ק אדנ\"ע וכ\"ק מו\"ח אדמו\"ר בגילוי ז' התורות."],["24","24","וראה סד\"ה פדה בשלום תרפ\"ה (ע' פח): המופתים הם שינוי הטבע, וכוונת העצמות שהטבע ממש יהי' אלקות, והענינים שלמטה יהיו כלים לאלקות, וזה בא ע\"י רבינו בהתלבשות בהשגה דוקא. וראה לקו\"ש ח\"ד ע' 1137 ואילך."],["25","25","ביאורי הזוהר לאדמו\"ר האמצעי וישלח כ, ב."],["26","26","<i>ועד\"ז</i> מצינו פסקי דינים התלויים <i>בשרש הנשמה למעלה</i> – שנשמות ששרשן ממדת חסד הנהגתן גם כן להטות כלפי חסד להקל כו' (הקדמת התניא. אגה\"ק סי\"ג. ובכ\"מ)."],["27","27","ראה התוועדויות תשמ\"ז ח\"ד ע' 204 הערה 85 ובשוה\"ג."],["28","28","ראה לקוטי לוי\"צ אגרות-קודש ע' רסג ואילך. לקו\"ש ח\"ד ע' 1178. ח\"ז ע' 170 ובהערה 13. ועוד."],["29","29","ראה גם לקמן סימן תכה סוס\"ד."],["30","30","וטעם הדבר – כיון שהכוונה דמעשה בראשית, כל סדר ההשתלשלות, כולל גן עדן וכו', היא, בשביל עבודתם של ישראל לעשות לו ית' דירה בתחתונים."],["31","31","כתר שם טוב סימן קיט. רנו."],["32","32","ירושלמי הובא בתוד\"ה אמונת – שבת לא, א. וראה לקו\"ש חט\"ו ע' 370. וש\"נ."],["33","33","ועד כדי כך, שפעולת הזריעה כשלעצמה (לולי האמונה בחי העולמים) נחשבת אצלו לאיבוד הזרעים, בל תשחית."],["34","34","ראה לקו\"ש ח\"ל ע' 170 ואילך. וש\"נ."],["35","35","שבדורות הראשונים \"כל חכמת הקבלה היתה נסתרה . . ונעלמה מכל תלמידי חכמים כ\"א ליחידי סגולה . . (ו)דוקא בדורות אלו האחרונים מותר ומצוה לגלות זאת החכמה\" (תניא אגה\"ק סכ\"ו)."],["36","36","יבמות לט, ב ובפרש\"י. וש\"נ."],["37","37","כדברי מלך המשיח להבעש\"ט שביאתו תהי' כשיפוצו מעינותיך (דהבעש\"ט) חוצה (אגה\"ק דהבעש\"ט – לעיל בריש הספר. ובכ\"מ)."],["38","38","פרי עץ חיים שער השבת רפ\"ג. שו\"ע אדה\"ז או\"ח סר\"נ ס\"ח**. – ולהעיר, שאצל כ\"ק מו\"ח אדמו\"ר לא ראיתי קיום מנהג זה בגשמיות כפשוטו, אבל ברוחניות בודאי צ\"ל כן (ולא רק ביום ששי, אלא בכל ימי השבוע)."],["39","39","ירמי' לא, לג."],["40","40","ישעי' יא, ט."],["41","41","ועד\"ז בנוגע לכללות היו\"ט דח\"י אלול – שהי' מהחגים הנסתרים, עד שהגיע הזמן שנתפרסם לחג ומועד גלוי ע\"י כ\"ק מו\"ח אדמו\"ר (ראה שיחת ח\"י אלול תש\"ג (ספר השיחות ע' 140 ואילך))."],["42","42","ועד לפירסום באופן של דפוס – <i>לדורות</i> (אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' שפב)."],["43","43","לקו\"ש שבהערה 34 – עיי\"ש בארוכה ביאור תיווך ב' הטעמים."],["44","44","אגרות-קודש הנ\"ל ח\"ג ע' שכו ואילך. ועוד."],["45","45","ע\"פ זח\"ב קסב, רע\"ב."],["46","46","משיחות ש\"פ בראשית תשי\"ז***. ש\"פ תבוא ח\"י אלול תשמ\"ז****.\n-----שולי הגליון-----\n*) <i>נדפס באגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ג ע' קעז</i>. המו\"ל.\n**) <i>ראה גם לעיל סימן תיח</i>.\n***) <i>עשרים שנה להתגלות תורות אלו ע\"י אדמו\"ר מהוריי\"צ (תרצ\"ז – תשי\"ז)</i>.\n****) <i>חמישים שנה להתגלות תורות אלו ע\"י אדמו\"ר מהוריי\"צ (תרצ\"ז – תשמ\"ז)</i>."]]],[300010949,"תכא\n\n<b>התלבשות אורות בכלים</b>\n<b>חיבור חסידות הכללית עם חסידות חב\"ד</b>\nא. נוסף על הדגשת החיבור דתורת החסידות הכללית עם תורת חסידות חב\"ד שבכללות המאורע דהתגלות שבעת התורות שאמר מורנו הבעש\"ט ע\"י נשיאי חב\"ד (כנ\"ל בארוכה) – ה\"ז בהדגשה ובגלוי גם בתוכן התורות עצמן, ובפרט בשתי תורות הראשונות שנאמרו בהקהל:\nהחילוק שבין תורה הראשונה לתורה השני' – ש\"אמר עוד הפעם התורה הקודמת והוסיף כו'\" – שבתורה הראשונה נאמר שהרצון והמרוצה הוא \"<i>מתנה מלמעלה בירושה</i> בכל אחד מישראל\",\n[וב' פרטים בזה: (א) \"מתנה\" – שצ\"ל בזה איזה ענין של עבודה, כמארז\"ל<sup data-n=\"1\">47</sup> \"אי לאו דעביד נייחא לנפשא לא הוה יהיב לי' מתנתא\", (ב) \"ירושה\" – שבזה אין צורך בענין של עבודה כלל, שהרי אפילו תינוק בן יומו יורש הכל<sup data-n=\"2\">48</sup>],\nובתורה השני' מוסיף שבכדי <i>להגיע</i> אל הרצון שישנו במתנה בכל אחד הוא ע\"י \"לשכן שמו שם\", למסור נפשו לפרסם אלקותו בעולם.\nכלומר: ההוספה דתורה השני' על התורה הראשונה, היא, שגם בנוגע לענינים שבאים מלמעלה באופן של מתנה וירושה, צ\"ל עבודה בכח עצמו כדי להגיע אליהם, כי, הענינים שבאים מלמעלה באופן של מתנה וירושה הם בבחינת <i>מקיף</i>, וכדי להגיע אליהם שיהיו באופן <i>פנימי</i> צ\"ל עבודה בכח עצמו.\nוזהו גם תוכן ההוספה דתורת חסידות חב\"ד על תורת החסידות הכללית – שנוסף על האמונה (באופן מקיף) שבאה מלמעלה צ\"ל גם הבנה והשגה (באופן פנימי) ע\"י העבודה בכח עצמו<sup data-n=\"3\">49</sup>.\nב. ויש להוסיף, שענין זה מרומז גם בתורה <i>הראשונה</i>:\n\"והי' כי תבוא אל הארץ אשר ה' אלקיך נותן לך נחלה וירשתה\", שקאי על הרצון והמרוצה שהוא מתנה מלמעלה בירושה בכל אחד מישראל – הו\"ע תורת החסידות הכללית, גילוי רצון העצמי שבנשמה שישנו בכאו\"א מישראל.\nוהעבודה שצריכה להיות בהרצון והמרוצה, \"וישבת בה\", שיהי' בהתיישבות, \"ולקחת גו' ושמת בטנא\", להלביש האורות בכלים – הו\"ע תורת חסידות חב\"ד, שהרצון והמרוצה שבנשמה יורד ונמשך באופן של אורות בכלים, שמתגלה ופועל בכל הכחות הפרטיים שבאדם.\nומדגיש בתורת הבעש\"ט שכל זה הוא ענין אחד, ולא ב' ענינים ועבודות – שהרי לא נאמר שצריך להגיע (\"דו <i>זאָלסט</i> צוקומען\") להרצון והמרוצה כו', וגם (ענין שני) שצ\"ל העבודה להמשיך בהתיישבות באופן דאורות בכלים, אלא כל זה נאמר בתור ענין אחד – שכשתגיע (\"אַז דו <i>וועסט</i> צוקומען\") להרצון והמרוצה אזי צ\"ל בהתיישבות כו'.\nוטעם הדבר – כיון שהפעולה דתורת החסידות הכללית ותורת חסידות חב\"ד היא בדוגמת החיות הכללי (אמונה) והחיות הפרטי (שהאמונה חודרת בשכל האדם, ומהשכל נמשך וחודר במדות כו', בכל כח לפי ענינו), אשר, ע\"י שניהם יחד נעשה אמיתת ושלימות החיות דהאדם באלקות<sup data-n=\"4\">50</sup>.\nג. עפ\"ז יש לבאר המשך התורה, \"והלכת אל המקום גו'\" הוא ענין השגחה פרטית, שההשגחה העליונה מביאה אותו למקום זה, והכוונה היא לשכן שמו שם, לפרסם אלקות בעולם – דלכאורה צריך להבין:\nהענין דהשגחה פרטית ופירסום אלקות בכל מקום שיהודי בא הוא אמנם גם מיסודות שיטת הבעש\"ט<sup data-n=\"5\">51</sup>, אבל, מהו הקשר עם התחלת התורה, \"והי' כי תבוא אל הארץ . . ולקחת . . ושמת בטנא\", להלביש האורות בכלים?\nלכאורה אפשר לבאר המשך הענין ע\"פ התורה השני', שבה מוסיף שבכדי להגיע להרצון (\"תבוא אל הארץ\") הוא ע\"י \"והלכת גו' לשכן שמו שם\", מס\"נ לפרסם אלקות בעולם.\nאבל, ביאור זה אינו מספיק, כי: (א) כיון שההוספה בתורה השני' (\"אמר עוד הפעם התורה הקודמת והוסיף\") היא ענין ותורה בפ\"ע, ולא (רק) ביאור על התורה הראשונה, אין זה מספיק לבאר קשר הענינים בתורה הראשונה, (ב) ועיקר: ביאור זה מבאר רק השייכות ד\"והלכת גו' לשכן שמו שם\" עם \"והי' כי תבוא אל הארץ\", הרצון העצמי שבנשמה, ועדיין צריך להבין השייכות להפרט העיקרי שבהתחלת התורה שצ\"ל \"וישבת בה גו' ושמת בטנא\", בהתיישבות, והתלבשות האורות בכלים, שהרצון העצמי צריך להיות נמשך בכל פרטי כחות האדם.\nויש לומר, שעיקר ושלימות הענין דפירסום אלקות בעולם (\"לשכן שמו שם\") נעשה ע\"י התלבשות האורות בכלים (\"ושמת בטנא\") שע\"י גילוי תורת חסידות חב\"ד, כדלקמן.\nד. וההסברה בזה:\nהחידוש של רבינו הזקן בתורת חסידות חב\"ד הוא לא רק מצד מעלת והבדלת שכל (חב\"ד) האדם משאר כחות הנפש (שלכן נוגע שתורת החסידות, אלקות, תחדור גם בשכלו של האדם), אלא, מצד כללות כוונת הבריאה לעשות לו ית' דירה בתחתונים:\nכוונת הבריאה היא שגם <i>ב</i>מציאות העולם <i>ומצד</i> העולם תהי' ההכרה ש\"אין עוד מלבדו\"<sup data-n=\"6\">52</sup>. וכיון שהתחלת המציאות שנבדלת כביכול מאלקות היא מציאות <i>השכל</i><sup data-n=\"7\">53</sup>, לכן, לכל לראש צריכים להסביר הענין דאחדות ה' בשכל, בשכל אנושי, ועד שנעשית כל מציאותו של השכל להבין אלקות (\"וידעת\"<sup data-n=\"8\">54</sup>). וע\"י השכל נמשך גם במדות שבלב (\"והשבות אל לבבך\"{54}), ועי\"ז גם בכחות התחתונים, ועד שאחדות ה' מתגלה וחודרת בכל העולם ובכל עניני העולם<sup data-n=\"9\">55</sup>.\nולכן, בהמשך להחידוש דתורת חסידות חב\"ד שהרצון העצמי דהנשמה (\"תבוא אל הארץ\") צריך לחדור ע\"י השכל בכל פרטי כחות האדם (\"ושמת בטנא\", התלבשות האורות בכלים), בא גם הענין ד\"והלכת גו' לשכן שמו שם\", לפרסם אלקות בעולם – שכל ענין ופרט שבעולם נעשה חדור באלקות עי\"ז שמנוצל לעבודתו ית', בהתאם לתכלית בריאתו ש\"לא בראו אלא לכבודו\"<sup data-n=\"10\">56</sup>.\nה. ויש להוסיף, שהענין דפירסום אלקות בעולם (\"והלכת גו' לשכן שמו שם\") נוגע (לא רק להתלבשות האורות <i>בכלים</i>, \"ושמת בטנא\", אלא) גם להתגלות הרצון העצמי שבנשמה (\"תבוא אל הארץ\"):\nכאשר עבודת האדם היא שהשכל שלו ושאר כחות נפשו יהיו חדורים באלקות – יתכן שעבודה זו קשורה עם המציאות (והתענוג) שלו (השכלתו באלקות, ההרגש שלו באהבה ויראה לאלקות), ולא מצד הרצון העצמי דהנשמה; ועי\"ז שיוצא ממציאותו (\"ער פאַרבויגט אויף זיך\") לעסוק (לא רק עם עצמו, אלא) גם בפירסום אלקות בעולם שמחוץ הימנו<sup data-n=\"11\">57</sup>, ה\"ז הוכחה שעבודתו היא מצד הרצון והמרוצה <i>דעצם הנפש</i> כפי שנמשך ומתלבש בחב\"ד.\nועוד ועיקר – שע\"י העבודה בהחדרת אלקות בכל פרטי הכחות שבנפש האדם ובכל פרטי הענינים שבעולם (לעשות לו ית' דירה בתחתונים), ניתוסף יותר בגילוי העצמות ובגילוי הרצון העצמי שבנשמה.\nו. עפ\"ז מובן גם הטעם שתורת הבעש\"ט הנ\"ל נתגלה ע\"י כ\"ק מו\"ח אדמו\"ר:\nאצל כ\"ק מו\"ח אדמו\"ר ראו בפועל שההשגחה העליונה הוליכה אותו בכל מקום \"לשכן שמו שם, לפרסם אלקות בעולם\" – בכל העולם כפשוטו, ובפרט ע\"י שלוחיו כו' בכל קצוי תבל.\nוגם הפירסום הי' בכל האופנים – הן ע\"י גילוי ענינים הכי עמוקים בתורת חסידות חב\"ד, והן ע\"י פירסום עניני תורה, נגלה וחסידות, בשפות שונות, ועד למטה ביותר, באופן המובן גם לתינוקות שנשבו כו', לפעול עליהם בעניני שמירת שבת, טהרת המשפחה, הנחת תפילין, וכיו\"ב.\nולכן, על ידו דוקא נתגלתה תורת הבעש\"ט ע\"ד הרצון העצמי שבנשמה שצריך לחדור בכל פרטי כחות האדם ובכל העולם כולו<sup data-n=\"12\">58</sup>.",[["1","47","ראה גיטין נ, ב. ב\"מ טז, א (וראה הנסמן בלקו\"ש חי\"ג ע' 117 הערה 41)."],["2","48","ראה נדה מד, רע\"א (במשנה). רמב\"ם הל' נחלות ספ\"א. טושו\"ע חו\"מ סרע\"ו ס\"ה."],["3","49","ועפ\"ז תומתק ההקדמה של כ\"ק מו\"ח אדמו\"ר לתורות הנ\"ל – שאינו מספיק הענין דאמונה בה', אלא צריך להתייגע שאלקות יבא גם בהשגה, וע\"י ההשגה באלקות נעשה אמונה טהורה כו', עיי\"ש."],["4","50","בפרטיות יותר – ראה לקו\"ש חכ\"ד ע' 178 ואילך (בביאור החידוש <i>דיום הולדת</i> (הבעש\"ט ואדה\"ז בח\"י אלול) בענין החיות)."],["5","51","ראה לעיל סימן קפד ואילך."],["6","52","ואתחנן ד, לה."],["7","53","כי הרצון – הוא תנועה בנפש ו(גילוי)מציאותו הוא בשכל ומדות ומחדו\"מ."],["8","54","שם, לט."],["9","55","ראה ד\"ה פדה בשלום תרפ\"ה בסופו (נעתק לעיל סימן תכ הערה 24)."],["10","56","אבות ספ\"ו."],["11","57","להעיר ממכתב כ\"ק מו\"ח אדמו\"ר שנדפס באגרות-קודש שלו ח\"ח ס\"ע תצז ואילך. וש\"נ."],["12","58","משיחת ח\"י אלול תשמ\"א – לקו\"ש חכ\"ד ע' 183 ואילך."]]],[300010950,"תכב\n\n<b>ושמת בטנא – התלבשות אורות בכלים</b>\nא. פירוש הבעש\"ט ש\"ושמת בטנא\" הו\"ע התלבשות האורות <i>בכלים</i>, מודגש ביותר ע\"פ דרשת חז\"ל<sup data-n=\"1\">59</sup> שמהפסוק \"ושמת בטנא\" למדים ש\"הביכורים טעונין <i>כלי</i>\", ו\"מצוה מן המובחר להביא כל מין ומין <i>בכלי בפני עצמו</i>\"<sup data-n=\"2\">60</sup>.\nויש לומר, שהחידוש ש\"הביכורים טעונין כלי\" הוא מצד מעלת האורות שמודגשת בענין הביכורים:\nביכורים הם \"מראשית כל פרי האדמה\", \"מראשית ולא כל ראשית, שאין כל הפירות חייבין בביכורים אלא שבעת המינין בלבד, נאמר כאן ארץ ונאמר להלן ארץ חטה ושעורה וגו', מה להלן משבעת המינים שנשתבחה בהם ארץ ישראל אף כאן <i>שבח</i> ארץ ישראל שהן שבעה מינין\"<sup data-n=\"3\">61</sup>, \"<i>המשובחים</i> שבכל פירותי' . . <i>מבחר</i> פירות אדמתך והם ז' המינים שנשתבחה בהם\"<sup data-n=\"4\">62</sup>, ובשבעת המינים עצמם \"אין מביאין כו' אלא מתמרים שבעמקים ומפירות שבהרים לפי שהן <i>מן המובחר</i>\"<sup data-n=\"5\">63</sup>.\nוכיון שביכורים הם מהשבח והמובחר שבארץ ישראל, וכללות השבח דארץ ישראל, ובפרט המובחר שבארץ ישראל עצמה, אינו מצד טבע העולם, כי אם, מפני היותה \"ארץ אשר גו' תמיד <i>עיני ה' אלקיך בה</i> מרשית השנה ועד אחרית שנה\"<sup data-n=\"6\">64</sup> – מודגש בזה גודל מעלת האורות (הרצון והמרוצה, ארץ), שהם אורות <i>בלתי מוגבלים</i>.\nועפ\"ז מודגש יותר החידוש ב\"ושמת בטנא\" ש\"הביכורים טעונין כלי\" – שגם האורות הבלתי מוגבלים יכולים וצריכים להמשיך בכלים.\nוהכח לזה מרומז בהמשך הכתוב \"אשר <i>יבחר</i> ה' אלקיך\" – בחירה דייקא, שבחירה אמיתית היא מצד העצמות שאינו מוגדר בשום גדר (גם לא בגדר האור), ובכח העצמות שהוא נמנע הנמנעות נעשית התלבשות האורות הבלתי מוגבלים בכלים.\nב. ויש להוסיף, שבענין התלבשות האורות בכלים יש (בכללות) שני אופנים:\nא) כלים של <i>דיבור</i>, כמ\"ש בדגל מחנה אפרים<sup data-n=\"7\">65</sup> בשם זקנו הבעש\"ט בפירוש \"ושמת בטנא\" ש\"טנא ר\"ת <i>ט</i>עמים <i>נ</i>קודין <i>א</i>תוון<sup data-n=\"8\">66</sup>, והוא ע\"ד אם<sup data-n=\"9\">67</sup> שגורה תפלתי בפי\"<sup data-n=\"10\">68</sup> – שהרצון והמרוצה שבעבודת התפלה צריך לבוא בכלי הדיבור.\nב) כלים של <i>מעשה</i> (לא רק מעשה זוטא דעקימת שפתיו הוי מעשה<sup data-n=\"11\">69</sup>, אלא גם מעשה כפשוטו, מעשה רבה), כפשטות הפירוש \"ושמת בטנא\" שהו\"ע של מעשה – שהרצון והמרוצה צריך לבוא גם ובעיקר במעשה בפועל.\nוע\"פ המבואר בהמשך התורה \"והלכת אל המקום גו' לשכן שמו שם\", שהכוונה היא לפרסם אלקות בעולם – מובן, שלא מספיקה ההתלבשות בכלים של דיבור, תפלה ותורה, אלא צ\"ל גם ההתלבשות בכלים של <i>מעשה</i>, מעשה המצוות שנתלבשו בעניני העולם, ועד לההתעסקות בעניני הרשות באופן ש\"כל מעשיך יהיו לשם שמים\"<sup data-n=\"12\">70</sup> ו\"בכל דרכיך דעהו\"<sup data-n=\"13\">71</sup>, כיון שעי\"ז דוקא נשלמת הכוונה דבירור העולם, \"לשכן שמו שם\".\nג. ובפרטיות יותר:\nההתלבשות בכלים של מעשה היא ירידה גדולה יותר מאשר ההתלבשות בכלים של דיבור, כפשוט.\nוכמודגש גם בהחילוק שבין פרשה ראשונה דק\"ש לפרשה שני' – שההתעסקות בעניני העולם, \"ואספת דגנך גו'\"<sup data-n=\"14\">72</sup>, היא בפרשה שני' שלא נאמר בה \"בכל מאדך\"<sup data-n=\"15\">73</sup>, \"אין עושין רצונו של מקום\", משא\"כ בפרשה ראשונה דק\"ש שנאמר בה \"בכל מאדך\", \"עושין רצונו של מקום\", אזי כללות העבודה היא בהאהבה ד\"בכל לבבך ובכל נפשך ובכל מאדך\", עבודה שבלב זו תפלה<sup data-n=\"16\">74</sup>, כפי שבאה גם בדיבור (תפלתי שגורה בפי), ואילו עניני העולם הם באופן ש\"מלאכתן נעשית ע\"י אחרים, שנאמר<sup data-n=\"17\">75</sup> ועמדו זרים ורעו צאנכם\"<sup data-n=\"18\">76</sup>.\nועאכו\"כ הענין ד\"והלכת אל המקום גו'\", שההשגחה העליונה מביאה אותו למקום מסויים כדי \"לשכן שמו שם\" – שענין זה מודגש בעיקר בזמן הגלות, שהסדר דעבודת הבירורים אינו כמו בזמן שלמה, שישראל ישבו על אדמתן, איש תחת גפנו ותחת תאנתו, ובדרך ממילא נתבררו ניצוצות הקדושה שבעולם כנר בפני האבוקה<sup data-n=\"19\">77</sup>, אלא באופן ש\"אחד מכם גולה לברברי' ואחד מכם גולה לסמטרי'\"<sup data-n=\"20\">78</sup>, שצריכים לילך ולבוא אל המקום שבו נמצאים ניצוצות הקדושה כדי לבררם ולהעלותם לקדושה – היפך לגמרי מהמעמד ומצב ד\"ועמדו זרים ורעו צאנכם\", מן הקצה אל הקצה.\nואף שההתלבשות בכלים של מעשה היא ירידה גדולה יותר מאשר ההתלבשות בכלים של דיבור, מ\"מ, ע\"י הירידה במעשה דוקא מגיעים לעילוי גדול יותר – ע\"ד המבואר בהמשך תרס\"ו<sup data-n=\"21\">79</sup> שדוקא ע\"י מעשה המצוות מגיעים לעילוי גדול יותר מאשר ע\"י לימוד התורה, כולל גם היגיעה בתורה, \"דדחקין<sup data-n=\"22\">80</sup> למלה דחכמתא\"<sup data-n=\"23\">81</sup>.",[["1","59","ספרי עה\"פ (תבוא כו, ב). רמב\"ם הל' ביכורים פ\"ג ה\"ז."],["2","60","רמב\"ם שם."],["3","61","תבוא שם ובספרי ובפרש\"י."],["4","62","ספורנו שם."],["5","63","רמב\"ם שם פ\"ב ה\"ג."],["6","64","עקב יא, יב."],["7","65","עה\"פ ברוך טנאך (תבוא כח, ה)."],["8","66","מגלה עמוקות אופן נג."],["9","67","ברכות לד, ב."],["10","68","ועד\"ז מבואר באו\"ת להמגיד (ר\"פ תבוא) שהו\"ע \"כי חיים הם למוצאיהם, שיהי' ניכר בכל דיבור ודיבור היוצא מפיך כל אות ואות ונקודיו וטעמיו שבו, וז\"ש ושמת בטנא, כי טנ\"א ר\"ת טעמים נקודות אותיות\" (ומוסיף ש\"לא הזכיר כאן תגין מפני שאינם במבטא כו'\")."],["11","69","סנהדרין סה, א."],["12","70","אבות פ\"ב מי\"ב. וראה רמב\"ם הל' דעות ספ\"ג."],["13","71","משלי ג, ו. וראה רמב\"ם שם. שו\"ע אדה\"ז או\"ח סקנ\"ו ס\"ב."],["14","72","עקב יא, יד."],["15","73","ואתחנן ו, ה."],["16","74","ריש מס' תענית. רמב\"ם ריש הל' תפלה."],["17","75","ישעי' סא, ה."],["18","76","ברכות לה, ב."],["19","77","ראה תו\"א בראשית ה, סע\"ד ואילך. ובכ\"מ."],["20","78","שהש\"ר פ\"ב, ח (ב)."],["21","79","ע' נו ואילך."],["22","80","זח\"א קל, ב."],["23","81","משיחת ש\"פ תבוא ח\"י אלול תש\"כ."]]],[300010951,"תכג\n\n<b>לשכן שמו שם – לפרסם אלקות בעולם</b>\nא. בשתי התורות הראשונות מדובר אודות פירסום אלקות בעולם, אבל, בתורה הראשונה ה\"ז באופן שההליכה אל המקום היא בהשגחה פרטית, שהקב\"ה מסבב הסיבות בדרך הטבע שילך למקום מסויים בשביל עניניו הגשמיים, לרגל עסקיו וכיו\"ב, ואז אומרים לו שהאמת היא שההשגחה העליונה הוליכה אותו למקום זה כדי לפרסם אלקות (ועי\"ז שימלא את שליחותו בפירסום אלקות יצליח גם בעניניו הגשמיים); ומוסיף על זה בתורה השני' שצריך <i>למסור נפשו</i> לפרסם אלקות בעולם.\nוהענין בזה:\nכשם שבנוגע לכללות הענין דירידת הנשמה בגוף נאמר \"על כרחך אתה חי\"<sup data-n=\"1\">82</sup>, כיון שהנשמה אינה רוצה לירד למטה להתלבש בגוף [ובפרט ע\"פ הידוע<sup data-n=\"2\">83</sup> שקודם הירידה למטה מוליכים את הנשמה דרך פתחי גן עדן וגיהנם כו'], וירידתה למטה להתלבש בגוף אינה אלא מצד גזירתו ית', כך גם לאחרי ירידתה בגוף בחיים חיותה בעלמא דין אין הנשמה רוצה לילך למקום ירוד יותר, ויש צורך <i>במסירת נפש</i> \"לשכן שמו שם\", לפרסם אלקות בעולם, בכל מקום בעולם, גם במקום ירוד כו'.\nויומתק יותר ע\"פ דיוק הלשון \"לשכן שמו <i>שם</i>\", \"שם\" דייקא – כידוע<sup data-n=\"3\">84</sup> ש\"מקום ומשכן הקליפות נק' שם, כלומר עמוק מאד למטה\", כמ\"ש<sup data-n=\"4\">85</sup> \"קראו שם פרעה גו'\", ולכן אין הנשמה חפצה לילך שם, ויש צורך <i>במסירת נפש</i> \"לשכן שמו <i>שם</i>\", לפרסם אלקות במקום הכי ירוד, ועד שמהפכים ה\"שם פרעה\" דלעו\"ז לפרעה דקדושה, \"דאתפריעו ואתגליין מיני' כל נהורין\"<sup data-n=\"5\">86</sup>.\nב. ובפרטיות יותר – בעבודה בפועל:\nכשדורשים מיהודי לילך למקום מסויים כדי לפרסם אלקות – יכול לטעון טענה שכלית שלא כדאי לו לעזוב את מקומו ולילך לבדו למקום נדח כו', הן מצד חשבונות גשמיים, והן ובעיקר (כיון שבנוגע לענינים הגשמיים מוכן הוא לוותר) מצד חשבונות רוחניים, כדברי ר' יוסי בן קיסמא: \"אם אתה נותן לי כל כסף וזהב ואבנים טובות ומרגליות שבעולם איני דר אלא במקום תורה\"<sup data-n=\"6\">87</sup>.\nועל זה באה ההוראה בתורת הבעש\"ט שצריך <i>למסור נפשו</i> לפרסם אלקות בעולם, כלומר, גם כאשר אין הדבר מובן ע\"פ שכל [בלשון החסידים: עבודה ע\"פ טו\"ד (כהלשון בתורה הג')], צריך להניח את השכל על הצד, ולילך מתוך <i>מסירת נפש</i>.\nובמכל-שכן וקל-וחומר: אפילו נשמות בלא גופים שנמצאים בגן עדן, ושומעים מהבעש\"ט עצמו [ולאחרי שהגיע להשלימות ד\"אל עפר תשוב\"<sup data-n=\"7\">88</sup> (לאחרי הסתלקותו) שזהו\"ע נעלה יותר מאשר העלי' בסערה השמימה<sup data-n=\"8\">89</sup>] ע\"ד הענין ד\"לשכן שמו שם\", אעפ\"כ אין זה מעורר אצלם הרצון והתשוקה, ויש צורך <i>במסירת נפש</i> (כיון שזהו\"ע של ירידה) – נשמות בגופים בעוה\"ז הגשמי, על אחת כמה וכמה שאין זה נעשה הרצון והתשוקה שלהם, אלא יש צורך <i>במסירת נפש</i>.\nוכיון שכח המסירת נפש ישנו אצל כאו\"א מישראל בכל הדורות, ובפרט בזמן הגלות ובעקבתא דמשיחא, שאז מתגלה יותר כח המסירת נפש, וכמשל הידוע שנקל להכניס את הרגל למים חמים יותר מאשר את הראש<sup data-n=\"9\">90</sup> – בכחו וביכלתו של כאו\"א לנצל את כח המסירת נפש כדי לקיים את ההוראה \"והלכת (הליכה ברגל) אל המקום אשר יבחר ה' אלקיך לשכן שמו שם\", לפרסם אלקות בעולם.\nוכשהולכים מתוך מסירת נפש, עוזר הקב\"ה ומסייע בכל המצטרך, ורואים בעיני בשר את כל הטוב אשר נותן ה' אלקיך, הן בענינים הגשמיים, כמודגש בביכורים שהפירות הם מן המובחר, והן ובעיקר בענינים הרוחניים, ולכל לראש במילוי הכוונה העליונה לפרסם אלקות בעולם.\n*\nג. ויש להוסיף בביאור לימוד ההוראה לפרסם אלקות בעולם מהפסוק \"והלכת אל המקום אשר יבחר ה' אלקיך לשכן שמו שם\" – דלכאורה אינו מובן:\nכיון שהפירוש הפשוט בפסוק \"והלכת אל המקום אשר יבחר ה' אלקיך לשכן שמו שם\", הוא, ההליכה אל <i>בית המקדש</i>, המקום המקודש ביותר מכל ארץ ישראל שהיא המקודשת מכל הארצות<sup data-n=\"10\">91</sup> – איך למדים מזה ההוראה ע\"ד ההליכה <i>לכל מקום שבעולם</i>, גם בחוץ לארץ, ועד לפנה נדחת, כדי לפרסם אלקות בעולם?\nוהביאור בזה – שהיא הנותנת – שהכוונה העליונה היא שהעולם כולו יהי' בדוגמת בית המקדש:\n\"יבחר ה' אלקיך\", \"בחירת השם יתברך ונחת רוח ועשיית רצונו\"<sup data-n=\"11\">92</sup> – קאי על כללות העולם, כדרשת חז\"ל<sup data-n=\"12\">93</sup> על הפסוק<sup data-n=\"13\">94</sup> \"שוקיו עמודי שש\", \"זה העולם <i>שנשתוקק</i> הקב\"ה לבראותו\", וכמארז\"ל<sup data-n=\"14\">95</sup> \"<i>נתאווה</i> הקב\"ה להיות לו ית' דירה בתחתונים\", שעוה\"ז התחתון שאין תחתון למטה ממנו יהי' דירה, משכן ומכון לשבתו ית', בדוגמת השראת השכינה בבית המקדש.\nוענין זה נעשה ע\"י כללות מעשינו ועבודתינו כל זמן משך הגלות, שעיקר העבודה בזמן הגלות היא <i>בחוץ לארץ</i>,\n– ששם נמצאים רוב מנין ורוב בנין של בנ\"י, ושם הוא עיקר גילוי התורה ע\"י גדולי ישראל, ולדוגמא: הבית-יוסף, שחיבר השולחן-ערוך שלאורו הולכים כל בית ישראל, חי רוב שנותיו בחוץ לארץ, וכן הרי\"ף הרמב\"ם והרא\"ש, ג' עמודי ההוראה שעליהם יסד הבית יוסף את פסקי השו\"ע, חיו בחוץ לארץ, וכן האריז\"ל שעל ידו התחיל גילוי פנימיות התורה חי רוב שנותיו בחוץ לארץ, וכן הבעש\"ט ואדמו\"ר הזקן, שני המאורות הגדולים, חיו וגילו תורת החסידות בחוץ לארץ דוקא<sup data-n=\"15\">96</sup> –\nלעשות מחוץ לארץ ארץ ישראל<sup data-n=\"16\">97</sup>, ועד להקדושה הכי נעלית שבארץ ישראל עצמה – <i>בית המקדש</i>.\nוזהו גם הדיוק \"לשכן <i>שמו</i> שם\" – \"כמה שכתוב<sup data-n=\"17\">98</sup> בכל המקום אשר אזכיר את שמי\"{92} – שבכל מקום שמגיע יהודי, אפילו יהודי אחד בלבד (כמארז\"ל<sup data-n=\"18\">99</sup> \"ומניין אפילו אחד, שנאמר בכל המקום אשר אזכיר את שמי\"), ה\"ה פועל \"לשכן שמו שם\", \"אזכיר את שמי\", שם המפורש שניתן רשות להזכירו בבית המקדש, שמתגלה בכל העולם כולו, כמ\"ש<sup data-n=\"19\">100</sup> \"ביום ההוא יהי' ה' אחד ושמו אחד\", \"כשם<sup data-n=\"20\">101</sup> שאני נכתב כך אני נקרא\"<sup data-n=\"21\">102</sup>.",[["1","82","אבות ספ\"ד."],["2","83","לקו\"ד ח\"א קעג, סע\"א ואילך."],["3","84","לקו\"ת ראה לב, רע\"ג."],["4","85","ירמי' מו, יז."],["5","86","זח\"א רי, א."],["6","87","אבות פ\"ו מ\"ט."],["7","88","בראשית ג, יט."],["8","89","כידוע מאמר הבעש\"ט שהי' יכול לעלות בסערה השמימה כאליהו הנביא, אלא שרצה להגיע לעילוי יותר גדול שנעשה ע\"י \"אל עפר תשוב\" (ראה לעיל סימן שא-שב)."],["9","90","ראה סה\"מ תרמ\"ח ע' קפז ואילך. הנסמן בסה\"מ מלוקט ח\"ד ע' קפח. בהוצאה החדשה – ח\"ג ע' עז."],["10","91","כלים פ\"א מ\"ו ואילך. רמב\"ם הל' ביהב\"ח פ\"ז הי\"ב ואילך."],["11","92","או\"ת להה\"מ עה\"פ (נו, רע\"ג)."],["12","93","במדב\"ר רפ\"י. וש\"נ."],["13","94","שה\"ש ה, טו."],["14","95","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["15","96","ולהעיר, ששניהם רצו ליסע לארץ ישראל, ובסופו של דבר נשארו בחוץ לארץ (ראה שד\"ח שיורי הפאה מערכת ג' כלל ז' בסופו (כרך ח א'תשיט, ד). – בנוגע לבעש\"ט. \"התמים\" ח\"ב ע' נב ואילך – בנוגע לאדה\"ז). וראה לעיל סימן ש."],["16","97","כפתגם הצ\"צ: עשה כאן – בחו\"ל – ארץ ישראל (אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' תפה)."],["17","98","יתרו כ, כא."],["18","99","אבות פ\"ג מ\"ו."],["19","100","זכרי' יד, ט."],["20","101","ראה פסחים נ, א. וש\"נ."],["21","102","משיחות ש\"פ תבוא ח\"י אלול תשי\"ג. ש\"פ תבוא ח\"י אלול תשט\"ז (הוספות ללקו\"ש ח\"ט ע' 338 ואילך)."]]],[300010952,"תכד\n\n<b>ג' פירושים בכניסה לארץ ושייכותם למצות ביכורים</b>\nא. נוסף על פירוש הבעש\"ט על הפסוק \"והי' כי תבוא על הארץ\" ש\"ארץ\" קאי על הרצון והמרוצה שבכאו\"א מישראל, ישנם גם הפירושים של המגיד ואדמו\"ר הזקן:\nפירוש המגיד<sup data-n=\"1\">103</sup> – ש\"עולם הבא נקרא ארץ . . כמ\"ש<sup data-n=\"2\">104</sup> צדיקים לעולם ירשו ארץ . . וזהו אומרו והי' כי תבוא אל הארץ . . כאשר תרצו לבוא אל הארץ העליונה אשר ה' אלקיך נותן לך, כי כל ישראל יש להם חלק לעולם הבא<sup data-n=\"3\">105</sup>, וירשתה . . שלא יצטרך להתגלגל רק וישבת בה ישיבה עולמית ונצחית, ככה תתנהג ותזכה: ולקחת מראשית וגו'\" – שהו\"ע בירור הניצוצים שבדברים הגשמיים (כמבואר שם בפרטיות), ש\"זהו עיקר עבודת האדם בעולם הזה . . וזהו אשר יבחר ה' אלקיך . . בחירת השם יתברך ונחת רוח ועשיית רצונו כו'\".\nופירוש אדמו\"ר הזקן<sup data-n=\"4\">106</sup> – ש\"ארץ ישראל הוא בחי' תורה שבעל פה<sup data-n=\"5\">107</sup> . . אשר בה גילוי רצונו ית', כי ע\"פ תורה שבכתב אי אפשר לידע שום דין על בוריו בלתי פירוש הגמרא, כמו דרשת טטפת שבתפילין כו' וכיוצא בהן ואיך הם נכתבין וכל פרטי דקדוקיהם\"<sup data-n=\"6\">108</sup>. ומוסיף לבאר{108} ש\"כמו שיש בחי' זו (ארץ ישראל) בעולם כך יש בשנה<sup data-n=\"7\">109</sup>, והוא בראש השנה . . שבר\"ה הוא בחי' מצוך לעשות את החוקים וגו'\"<sup data-n=\"8\">110</sup>.\nב. ג' הפירושים ב\"ארץ\" – הרצון והמרוצה שבכאו\"א מישראל, ירושת עולם הבא, וקיום רצונו ית' שבתושבע\"פ – הם ענינים כלליים בעבודת האדם.\nויתירה מזה, שבהצירוף דג' הפירושים נכלל כללות ענין העבודה: הרצון והמרוצה שבנפש האדם (פירוש הבעש\"ט) – התחלת ויסוד העבודה; עולם הבא (פירוש המגיד) – שכר (גמר ותכלית) העבודה; ותורה שבע\"פ שבה מתגלה רצון העליון (פירוש אדמו\"ר הזקן) – העבודה עצמה.\nוכיון שפירושים אלו הם בשייכות להכניסה לארץ שנאמרה בפרשת <i>ביכורים</i> (\"והי' כי תבוא אל הארץ וגו' ולקחת מראשית כל פרי האדמה וגו'\"), מסתבר לומר, שיש להם קשר ושייכות לתוכנה של מצות ביכורים, שעם היותה מצוה פרטית (ולא עוד אלא שאינה נוהגת אלא בפני הבית ובארץ ישראל בלבד<sup data-n=\"9\">111</sup>), נרמז בה כללות ענין העבודה, כדלקמן.\nג. וביאור הענין:\nביכורים<sup data-n=\"10\">112</sup> – קאי על האבות, כמארז\"ל<sup data-n=\"11\">113</sup> \"האבות . . עלו במחשבה להבראות . . שנאמר<sup data-n=\"12\">114</sup> כענבים במדבר גו' כבכורה בתאנה בראשיתה ראיתי אבותיכם\", וקאי גם על כללות ישראל, כדאיתא בזהר<sup data-n=\"13\">115</sup> \"ראשית ביכורי . . אינון ישראל . . קדש<sup data-n=\"14\">116</sup> ישראל לה' ראשית תבואתה\", \"כבכורה בתאנה הכי ישראל קדמונים וביכורים . . קדש ישראל לה' ראשית תבואתה\"<sup data-n=\"15\">117</sup>, כיון שגם \"ישראל . . עלו במחשבה להבראות\"{113}, היינו, שהאבות וישראל קדמו לעולם, ולכן נקראים ביכורים, לפי שביכורים קודמים לכל<sup data-n=\"16\">118</sup>.\nויתירה מזה – שהאבות וישראל קדמו (לא רק לעולם, אלא) אפילו לתורה, כדאיתא בתדבא\"ר<sup data-n=\"17\">119</sup> \"שני דברים קדמו לעולם תורה וישראל . . (וביניהם גופא) ישראל קדמו\", וראי' לדבר<sup data-n=\"18\">120</sup>, שהתורה עצמה אומרת \"צו את בני ישראל\", \"דבר אל בני ישראל\"<sup data-n=\"19\">121</sup>, ולכן נקראים ביכורים שקודמים אפילו לתרומה, תורה מ' (שניתנה למ' יום)<sup data-n=\"20\">122</sup>.\nובסגנון דתורת החסידות – שהתורה היא בחי' חכמה דאצילות, ראשית ההשתלשלות, וישראל עלו במחשבה הקדומה דא\"ק שלמעלה מחכמה דאצילות.\nאמנם, כל זה הוא מצד שרש הנשמה כפי שכלולה במאצילה ית', שעז\"נ \"נשמה שנתת בי טהורה היא\", שקאי על שרש הנשמה כפי שהיא בבחי' טהירו עילאה; אבל לאח\"ז ירדה הנשמה בסדר השתלשלות העולמות, \"אתה בראתה אתה יצרתה אתה נפחתה בי\", עד שירדה למטה ונתלבשה בגוף בעוה\"ז הגשמי, שאז צריך לקשר ולחבר את דרגת הנשמה המלובשת בגוף עם שרש הנשמה למעלה. והכוונה בזה – כדי שהנשמה תמלא שליחותה בבירור הגוף ונה\"ב וחלקו בעולם לעשות לו ית' דירה בתחתונים.\nוענין זה מרומז במצות ביכורים:\nבמצות ביכורים יש בה ב' ענינים: (א) הבאת ביכורים, \"ולקחת מראשית כל פרי האדמה וגו' ולקח הכהן הטנא מידך והניחו לפני מזבח ה' אלקיך\"<sup data-n=\"21\">123</sup>, (ב) קריאת פרשת ביכורים, \"וענית ואמרת וגו'\"<sup data-n=\"22\">124</sup>.\nוענינם בעבודת האדם: הבאת הביכורים הו\"ע העלאה מלמטה למעלה (העלאת הפירות והנחתם לפני המזבח) – העלאת הנשמה (שנקראת פרי האילן, אילנא דחיי) המלובשת בגוף לקשרה ולחברה עם שרשה ומקורה למעלה<sup data-n=\"23\">125</sup>, וקריאת פרשת ביכורים הו\"ע המשכה מלמעלה למטה (ע\"י הקריאה, \"כאדם הקורא לחבירו שיבוא אליו\"<sup data-n=\"24\">126</sup>) – שיומשך משרש הנשמה למעלה בדרגת הנשמה המלובשת בגוף.\nועד\"ז בעבודה בעניני העולם (שבשביל זה ירדה הנשמה למטה) – שהבאת ביכורים, נתינת הפירות לכהן, מורה על העלאת עניני העולם לקדושה, וקריאת פרשת ביכורים, שבח והודאה להקב\"ה על חלקו הטוב בארץ זבת חלב ודבש, מורה על המשכת אלקות בעניני העולם.\nד. עפ\"ז יש לומר שהשייכות למצות ביכורים היא (לא רק בהפירושים דתיבת \"ארץ\", אלא) גם בתוכן תורת הבעש\"ט, וההמשך וההוספה בתורת המגיד ואדמו\"ר הזקן:\nנתבאר לעיל שבמצות ביכורים נרמזת כללות העבודה בשתי הקוין דהעלאה מלמטה למעלה והמשכה מלמעלה למטה, היינו, שאין להסתפק בענין ההעלאה מלמטה למעלה, אלא צ\"ל גם ההמשכה מלמעלה למטה, כיון שעי\"ז נשלמת הכוונה דירידת הנשמה למטה.\nוענין זה מודגש גם בתורת הבעש\"ט שהרצון והמרוצה צ\"ל באופן של התיישבות והתלבשות אורות בכלים – שתנועת הרצון והמרוצה הו\"ע העלאה מלמטה למעלה, ותנועת ההתיישבות והתלבשות אורות בכלים הו\"ע המשכה מלמעלה למטה, שעי\"ז נשלמת הכוונה ד\"לשכן שמו שם\".\nועד\"ז בתורת המגיד שכדי לזכות לבוא אל הארץ העליונה, עולם הבא, לרשתה ולישב בה ישיבה עולמית ונצחית, צ\"ל העבודה דבירור הניצוצות שבעניני העולם – שכללות העלי' דהנשמה לעולם הבא היא ע\"י העבודה דהמשכת אלקות בעניני העולם.\nועד\"ז בתורת אדמו\"ר הזקן בענין התגלות רצונו ית' בתורה שבע\"פ – כפי שמבאר{108} ש\"אע\"פ שעיקר דיני התורה שבע\"פ הוא בבחי' עשי' גשמית, מ\"מ, הרי היא כמו בחי' רגל וסוף מעשה . . שירדה ונתלבשה ממקום גבוה למקום נמוך . . כי סוף מעשה במחשבה תחלה, ואי אפשר להשיג טעמי תורה וסודותי' אם לא על ידי ידיעת התורה שבע\"פ, כמו למשל מלך שבונה בנין מפואר ואי אפשר להשיג חכמתו ורצונו שבבנין בלי שיוגמר בנין הנ\"ל בשלימותו . . שלימות וגמר הזה הוא בסוף מעשה שהוא ע\"פ תורה שבעל פה\", שבזה מודגש גם שעיקר הענין דתושבע\"פ הוא (לא רק השגת הרצון העליון כשלעצמה<sup data-n=\"25\">127</sup>, אלא) קיום הרצון העליון במעשה בפועל (בעשי' גשמית), \"גדול תלמוד שמביא לידי מעשה\"<sup data-n=\"26\">128</sup>, כיון שהרצון העליון הוא להיות לו ית' דירה בתחתונים (\"לשכן שמו שם\"<sup data-n=\"27\">129</sup>)<sup data-n=\"28\">130</sup>.",[["1","103","או\"ת ר\"פ תבוא."],["2","104","ישעי' ס, כא."],["3","105","סנהדרין ר\"פ חלק."],["4","106","לקו\"ת ר\"פ תבוא – על הפסוק (כו, טז) \"היום הזה ה' אלקיך מצוך לעשות את החוקים האלה וגו'\", ש\"לא כתיב איזה יום משום דהמקרא מחובר לפרשה שלמעלה הימנה שמסיימת ארץ זבת חלב ודבש . . דהיינו בשעת כניסתן לארץ\" (שזהו התוכן ד\"והי' כי תבוא אל הארץ\")."],["5","107","\"כי ארץ מלשון רצון, כמאמר רז\"ל (ב\"ר פ\"ה, ח) למה נקרא שמה ארץ שרצתה כו' . . כי תורה שבע\"פ היא השגת תכלית הרצון לידע איך ומה כגון סוכה שהיא גבוה כו' שאין זה מבואר בתורה שבכתב\" (תו\"א בראשית א, ג)."],["6","108","לקו\"ת שם."],["7","109","ומקדים לזה ש\"יש בחי' עולם שנה נפש\", ועפ\"ז י\"ל, שפירוש הבעש\"ט הוא <i>בנפש</i> (הרצון והמרוצה), פירוש המגיד הוא <i>בעולם</i> (ארץ העליונה), ופירוש אדמו\"ר הזקן הוא <i>בשנה</i> (ראש השנה).\nוראה ד\"ה אתם נצבים דח\"י אלול תשל\"ט (סה\"מ מלוקט ח\"א ע' שכט ואילך. בהוצאה החדשה – ח\"ד ע' ערב ואילך) – ביאור הענין דכריתת ברית לפני הכניסה לארץ בעולם בשנה ובנפש."],["8","110","ושם: \"לפי שר\"ה הוא ענין אחד עם תושבע\"פ, כי ר\"ה הוא בחי' שתמליכוני עליכם, ומלכות פה תורה שבעל פה קרינן לה, לכך כמו שבתורה שבעל פה הוא גילוי הרצון עליון איך יעשו התפילין והסוכה כו', כך בראש השנה הוא גילוי רצון עליון, ולכן בר\"ה הוא בחי' מצוך לעשות כו'\"."],["9","111","רמב\"ם הל' ביכורים רפ\"ב."],["10","112","בהבא לקמן – ראה אוה\"ת תבוא ע' תתרלג ואילך. תתרלט ואילך."],["11","113","ב\"ר פ\"א, ד."],["12","114","הושע ט, יו\"ד."],["13","115","ח\"ב קכא, רע\"א."],["14","116","ירמי' ב, ג."],["15","117","ח\"ג רנג, א."],["16","118","תרומות פ\"ג מ\"ז. רמב\"ם הל' תרומות פ\"ג הכ\"ג."],["17","119","פרק יד."],["18","120","ראה ספר המאמרים תרצ\"ב ע' רה ובהערה 43."],["19","121","ראה ב\"ר שם."],["20","122","זח\"ג קעט, א."],["21","123","תבוא כו, ב-ד."],["22","124","שם, ה."],["23","125","ע\"ד ש\"מיכאל כהנא רבא מקריב נשמות ע\"ג המזבח . . ליכלל ולאשתאבא בגופא דמלכא. (אוה\"ת שם ס\"ע תתרלד ואילך. תתרמ)."],["24","126","תניא ספל\"ז."],["25","127","ש\"ע\"י השגת הרצון בנפש תכלל הנפש במקורה למעלה\" (תו\"א שם)."],["26","128","קידושין מ, ב. וש\"נ."],["27","129","ועד\"ז בנוגע להכניסה לארץ בשנה שהוא בראש השנה – שהענין ד\"תמליכוני עליכם\" (קבלת עול מלכותו ית') מתבטא בקיום רצונו ית' (\"מצוך לעשות את החוקים האלה גו'\") במעשה בפועל (קבלת עול מצוות), שעי\"ז פועלים ומגלים מלכותו ית' בכל העולם כולו, לא רק \"תמליכוני <i>עליכם</i>\", \"מלך <i>ישראל</i> וגואלו\", אלא גם \"מלך על כל הארץ\", שזהו תוכן הענין ד\"לשכן שמו שם, לפרסם אלקות <i>בעולם</i>\"."],["28","130","ממאמר ד\"ה והי' כי תבוא ח\"י אלול תשל\"ז. שיחת ח\"י אלול תשמ\"א."]]],[300010953,"תכה\n\n<b>אמירת התורות בהקהל,</b>\n<b>במעמד תלמידי הבעש\"ט ותלמידי תלמידיהם</b>\nא. בביאור דיוק הלשון שאמירת התורות היתה במעמד \"תלמידי הבעש\"ט ותלמידי תלמידיהם\" – יש לומר:\nאמרו חז\"ל<sup data-n=\"1\">131</sup> \"כל שהוא תלמיד חכם ובנו תלמיד חכם ובן בנו תלמיד חכם שוב אין תורה פוסקת מזרעו לעולם, שנאמר<sup data-n=\"2\">132</sup> ואני זאת בריתי וגו' לא ימושו מפיך ומפי זרעך ומפי זרע זרעך אמר ה' מעתה ועד עולם . . אמר הקב\"ה אני ערב לך בדבר זה . . מכאן ואילך תורה מחזרת על אכסניא שלה\", כיון שישנו התוקף דשלש דורות, \"החוט המשולש לא במהרה ינתק\"<sup data-n=\"3\">133</sup>.\nועד\"ז י\"ל בנדו\"ד, שאמירת התורות במעמד התלמידים ותלמידי תלמידיהם<sup data-n=\"4\">134</sup> (כמו בנו ובן בנו, כי התלמידים קרויין בנים<sup data-n=\"5\">135</sup>), היא, כדי להדגיש ולפעול בתורות אלו <i>תוקף נצחי</i> באופן ד\"לא ימושו גו' מעתה ועד עולם\".\nב. ובעומק יותר – שבאמירת התורות במעמד \"תלמידי הבעש\"ט ותלמידי תלמידיהם און זייערע חסידים\" נכללים כל תלמידי הבעש\"ט ותלמידי תלמידיהם <i>עד סוף כל הדורות</i>:\nכשם שבמתן-תורה במעמד הר סיני היו נוכחים כל בנ\"י, \"את אשר ישנו פה גו' ואת אשר איננו פה\"<sup data-n=\"6\">136</sup>, כל נשמות בנ\"י עד סוף כל הדורות (כדאיתא בפרדר\"א<sup data-n=\"7\">137</sup>), כך גם במעמד אמירת התורות ע\"י הבעש\"ט בח\"י אלול היו נוכחים הנשמות של כל תלמידי הבעש\"ט ותלמידי תלמידיהם, כל הלומדים תורת החסידות, וכל אלה שילמדו תורת החסידות עד סוף כל הדורות, \"את אשר ישנו פה ואת אשר איננו פה\", שכולם היו נוכחים במעמד אמירת שתי תורות הנ\"ל.\nויש לומר, שענין זה מרומז גם בתוכן שתי התורות בענין \"כי תבוא אל הארץ\" – כי, שלימות הכניסה לארץ היא באופן ד\"כל יושבי' עלי'\" (שאז היובל נוהג)<sup data-n=\"8\">138</sup>, שרומז על השלימות דכללות בנ\"י שבכל הדורות.\nג. ויש להוסיף בביאור השייכות דאמירת התורות בהקהל במעמד התלמידים ותלמידי תלמידיהם (עד סוף כל הדורות) לחודש אלול:\nידוע ביאור רבינו הזקן<sup data-n=\"9\">139</sup> בענינו של חודש אלול \"ע\"פ משל למלך שקודם בואו לעיר יוצאין אנשי העיר לקראתו ומקבלין פניו <i>בשדה</i>, והוא מקבל את כולם בסבר פנים יפות ומראה פנים שוחקות לכולם כו'\".\nועפ\"ז י\"ל שגם אמירת התורות ע\"י הבעש\"ט היא באופן דמלך <i>בשדה</i>:\nהלימוד <i>בבית-המדרש</i> הוא באופן שניכר החילוק בין התלמידים ע\"פ סדר ישיבתם בשורה ראשונה, שורה שני' וכו', לפי ערך מעלתם בלימוד התורה<sup data-n=\"10\">140</sup>, ולא עוד אלא שישנו סוג תלמידים שלא מכניסים אותם לבית-המדרש<sup data-n=\"11\">141</sup>, משא\"כ הלימוד <i>בשדה</i> הוא באופן שלא ניכר החילוק בין התלמידים, כיון שאין יושבים שורות שורות אלא כולם יחדיו.\nועד\"ז בנדו\"ד, שכל תלמידי הבעש\"ט ותלמידי תלמידיהם עד סוף כל הדורות – שבודאי יש ביניהם חילוקי דרגות מן הקצה אל הקצה – שומעים <i>יחדיו</i> (בהקהל) התורות שאומר מורנו הבעש\"ט, כיון שאמירת התורות בחודש אלול היא באופן דמלך <i>בשדה</i>.\nד. אמנם, אף שכל החסידים עד סוף כל הדורות שמעו תורות אלו, מ\"מ, כיון שישנם ענינים המעלימים ומסתירים כו', לכן <i>לא זוכרים</i> המעמד דשמיעת התורות מהבעש\"ט<sup data-n=\"12\">142</sup>.\nוהעצה לזה – לימוד התורות ע\"י החסידים בכל דור ודור:\nאמרו חז\"ל \"כל האומר שמועה מפי אומרה יהא רואה בעל השמועה כאילו <i>הוא עומד כנגדו</i>\"<sup data-n=\"13\">143</sup>, ולא עוד אלא שכן הוא גם בנוגע לבעל השמועה עצמו, \"כל ת\"ח שאומרים דבר שמועה מפיו בעולם הזה <i>שפתותיו דובבות</i> כו'\"<sup data-n=\"14\">144</sup>.\nומזה מובן שכאשר לומדים התורות שאמר מורנו הבעל שם טוב בגן עדן, חוזר ונשנה עוד הפעם אמירת התורות ע\"י הבעש\"ט בגן עדן, אבל, כפי שגן עדן נמשך ומתגלה בעוה\"ז, בבחינת \"עולמך תראה בחייך\"<sup data-n=\"15\">145</sup>.\nומעלה יתירה בלימוד התורות בזמן אמירתן – ח\"י אלול – מצד עבודת התשובה שבחודש אלול, חודש החשבון והתשובה<sup data-n=\"16\">146</sup>, ובפרט מח\"י אלול שבו מתחילים י\"ב ימים האחרונים שהם כנגד י\"ב חדשי השנה, יום לחודש יום לחודש<sup data-n=\"17\">147</sup> – כי, ע\"י עבודת התשובה מתבטלים הענינים המעלימים ומסתירים על האמת<sup data-n=\"18\">148</sup>, ונעשית השבת הנפש לשרשה ומקורה<sup data-n=\"19\">149</sup>, ואז יכולים \"לשמוע\" מחדש התורות שאמר (ואומר) מורנו הבעש\"ט<sup data-n=\"20\">150</sup>.\n[ויש לומר, שא' הטעמים שסיפרו לנו המאורע דשמיעת התורות שאמר מורנו הבעש\"ט בגן עדן (ולא רק תוכן התורות מבלי להוסיף שנאמרו בגן עדן<sup data-n=\"21\">151</sup>), הוא, כדי ללמד ולהורות לנו שע\"י עבודה המתאימה יכולים לבוא לדרגא נעלית של שמיעת תורה בגן עדן, בחזיון לילה, וכיו\"ב<sup data-n=\"22\">152</sup>].\n*\nה. ויש להוסיף ולבאר הלימוד וההוראה (מאמירת התורות בהקהל במעמד התלמידים ותלמידי התלמידים) בעבודת כאו\"א מישראל בהפצת המעיינות דתורת הבעש\"ט כפי שנתבארה בתורת חסידות חב\"ד:\nנוסף על לימוד תורת החסידות בעצמו, צריך כאו\"א להשתדל לעסוק בהפצת המעיינות ע\"י הלימוד עם הזולת, ולא להסתפק בלימוד עם אחד מישראל, אלא לומד עם כו\"כ מישראל, ועד לרבים מישראל<sup data-n=\"23\">153</sup> – <i>בהקהל</i><sup data-n=\"24\">154</sup>.\nויתירה מזה, שלימודו עם הרבים צ\"ל באופן שכאו\"א מהם נעשה \"טופח על מנת להטפיח\"<sup data-n=\"25\">155</sup>, היינו, שכאו\"א מהתלמידים עוסק בהפצת המעיינות ע\"י הלימוד לאחרים – <i>תלמידי הבעש\"ט ותלמידי תלמידיהם</i>.\nזאת ועוד:\nגם כשעסק בהפצת המעיינות והעמיד תלמידים ותלמידי תלמידים, אין לו להסתפק בהלימוד לתלמידיו בלבד, והם כבר ילמדו לתלמידיהם, אלא צריך להשתדל ללמד בעצמו גם את תלמידי תלמידיו (לא רק מסקנת הענין, אלא גם) כל פרטי הענינים – כהנהגת הבעש\"ט שאמר התורות במעמד תלמידיו ותלמידי תלמידיהם.\n[וכן הוא ב\"סדר המשנה\" דמשה רבינו – שלאחרי שלמד עם אהרן, בני אהרן והזקנים, \"נכנסו כל העם ושנה להם משה פרקן\"<sup data-n=\"26\">156</sup>, היינו, שלא הסתמך על כך שאהרן ובניו והזקנים (תלמידיו) ילמדו עם כל העם, אלא גם הוא בעצמו למד עם כל העם (תלמידי תלמידיו)].\nואין לתמוה על כך שתובעים <i>מכאו\"א</i> לעסוק בהפצת המעיינות בהקהל ולהעמיד תלמידים ותלמידי תלמידים – שהרי אמרו חז\"ל<sup data-n=\"27\">157</sup> \"כל אחד ואחד חייב לומר בשבילי נברא העולם\", ולא עוד אלא ש\"לפיכך נברא אדם יחידי . . עולם מלא\" (\"להראותך שמאדם א' נברא מילואו של עולם\"<sup data-n=\"28\">158</sup>), היינו, שבריאת אדה\"ר (יציר כפיו של הקב\"ה<sup data-n=\"29\">159</sup>) בג\"ע מקדם (קודם החטא) היתה באופן שמזה ילמד כל אחד מישראל עד סוף כל הדורות שבשבילו נברא העולם!\nומזה מובן גם שההשתדלות בהפצת המעיינות צריכה להיות בנוגע לכל יחיד מישראל, מבלי הבט על מעמדו ומצבו – כיון שגם הוא \"עולם מלא\", ולא עוד אלא שבו תלוי' השלימות דכלל ישראל<sup data-n=\"30\">160</sup>.",[["1","131","ב\"מ פה, א."],["2","132","ישעי' נט, כא."],["3","133","קהלת ד, יב."],["4","134","ומוסיף שהיו נוכחים גם <i>החסידים של תלמידי תלמידיהם</i> (\"תלמידי הבעש\"ט ותלמידי תלמידיהם און זייערע חסידים\"), היינו, שגם תלמידי תלמידיהם נסמכו להורות לתלמידים, שבזה מודגשת יותר גודל מעלת הבעש\"ט במעמד אמירת התורות (שעי\"ז ניתוסף יותר בגודל מעלת התורות) – כי, \"כשנסמכו גם תלמידי תלמידיו אז השלישים קרואין רבי והשנים נקראים רבן והוא נקרא בשמו\", \"גדול מרבן שמו\" (פי' חסדי דוד לתוספתא סוף עדיות)."],["5","135","ספרי ופרש\"י ואתחנן ו, ז."],["6","136","נצבים כט, יד."],["7","137","פרק מא."],["8","138","ערכין לב, סע\"ב. רמב\"ם הל' שמיטה ויובל פ\"י ה\"ח. – ולהעיר מהשקו\"ט בפוסקים גם בנוגע לחיוב תרומות ומעשרות אם תלוי ב\"כל יושבי' עלי'\" (ראה רמב\"ם הל' תרומות ספ\"א ובהשגת הראב\"ד שם. חינוך מצוה תקז. טושו\"ע יו\"ד סשל\"א ס\"ב. וראה שד\"ח מע' התי\"ו כלל כג)."],["9","139","לקו\"ת ראה לב, ב."],["10","140","ראה ב\"ק קיז, סע\"א."],["11","141","ראה ברכות כח, א."],["12","142","וע\"ד מארז\"ל (נדה ל, ב) \"הולד כו' במעי אמו כו' מלמדין אותו כל התורה כולה כו' כיון שבא לאויר העולם בא מלאך וסטרו על פיו <i>ומשכחו</i> כו'\"."],["13","143","ירושלמי שבת פ\"א ה\"ב. ועוד."],["14","144","יבמות צז, רע\"א."],["15","145","ברכות יז, סע\"א."],["16","146","ראה טור או\"ח ר\"ס תקפא. סה\"מ תרצ\"ו ס\"ע 141 ואילך. סה\"מ אידיש ע' 75. 78. 129."],["17","147","שיחת ח\"י אלול תש\"ג (ספר השיחות ע' 177. 179)."],["18","148","וע\"ד פס\"ד הרמב\"ם (הל' גירושין ספ\"ב) בענין \"כופין אותו עד שיאמר רוצה אני\", שרצונו האמיתי של כאו\"א מישראל הוא \"להיות מישראל . . לעשות כל המצוות ולהתרחק מן העבירות ויצרו הוא שתקפו וכיון שהוכה עד שתש כחו ואמר רוצה אני . . (ה\"ז) לרצונו\", כיון שמתגלה רצונו האמיתי."],["19","149","ראה לקו\"ת ר\"פ האזינו. ובכ\"מ."],["20","150","כ\"ק אדמו\"ר זי\"ע צוה לנגן ניגון הבעש\"ט (ג' תנועות, דהבעש\"ט המגיד ואדה\"ז), ואח\"כ המשיך בביאור התורות (המו\"ל)."],["21","151","ראה גם לעיל סימן תכ ס\"ד."],["22","152","ראה לקו\"ש ח\"ד ע' 1026. וש\"נ."],["23","153","ולהעיר מהל' ת\"ת לאדה\"ז (פ\"א ה\"ח): \"על כל חכם וחכם ללמד את <i>כל התלמידים</i> כו'\"."],["24","154","ולהעיר, שענין זה הוא בהדגשה יתירה בשנת הקהל*, שבה מודגש הציווי \"הקהל את העם גו' למען ילמדו גו' את כל דברי התורה הזאת\" – לימוד התורה בהקהל."],["25","155","לשון חז\"ל – ברכות כה, ריש ע\"ב. ועוד."],["26","156","עירובין נד, ב. הובא בפרש\"י עה\"ת ס\"פ תשא (לד, לב)."],["27","157","סנהדרין לז, סע\"א (במשנה)."],["28","158","פרש\"י שם."],["29","159","ראה ב\"ר פכ\"ד, ה. וש\"נ."],["30","160","משיחות ש\"פ תבוא ח\"י אלול תשי\"ג. ש\"פ תבוא תשמ\"א. תשמ\"ח. ט\"ו אלול תנש\"א.\n-----שולי הגליון-----\n*) <i>השנה שבה נאמרה שיחה זו – שנת תשמ\"א</i> (המו\"ל)."]]],[300010954,"תכו\n\n<b>שייכותן גם לנשים</b>\nא. בביאור הטעם שמביא המבואר במאמר להבין ענין זיווג הנשמות בג\"ע שמניחים לנשמות מעלמא דנוקבא לשמוע תורה בג\"ע – יש לומר:\n\"אשה אינה במצות תלמוד תורה, שנאמר<sup data-n=\"1\">161</sup> ולמדתם אותם את בניכם ולא את בנותיכם\", אלא שאעפ\"כ \"גם הנשים חייבות ללמוד <i>הלכות הצריכות להן</i> לידע אותן כמו דיני נדה וטבילה ומליחה ואיסור יחוד וכיו\"ב וכל מ\"ע שאין הזמן גרמא וכל מל\"ת . . שהן מוזהרות בהן כאנשים\"<sup data-n=\"2\">162</sup>.\nוכיון שבג\"ע (מקום הנשמות לאחרי יציאתן מן הגוף) לא שייך החיוב דקיום המצוות (\"במתים חפשי<sup data-n=\"3\">163</sup>, כיון שמת אדם נעשה חפשי מן המצוות\"<sup data-n=\"4\">164</sup>), ובמילא, לא שייך גם החיוב דלימוד ההלכות הצריכות, כי אם, תלמוד תורה כשלעצמו<sup data-n=\"5\">165</sup> – אין זה שייך (לכאורה) לנשים שאינן במצות תלמוד תורה.\nולכן, כשמספר אודות אמירת תורות <i>בג\"ע</i> גם בפני <i>נשים</i>, מוכרח להבהיר השייכות דלימוד התורה בג\"ע גם לנשים – ע\"פ המבואר במאמר הנ\"ל בהגהה שגם נשמות דעלמא דנוקבא מניחים להם לשמוע תורה בג\"ע.\nוכל זה בנוגע להסיפור דשמיעת התורות <i>בג\"ע</i>, אבל בנוגע להלימוד וההוראה בעבודה בפועל <i>לנשמות בגופים</i> (שזוהי עיקר הכוונה בהסיפור ע\"ד שמיעת התורות בג\"ע), פשוט, שלימוד תורות אלו שייך גם לנשים, ככל עניני תורת החסידות שלימודם שייך גם לנשים, מפני שלימוד תורת החסידות מביא לאמונת ה' ויחודו אהבתו ויראתו כו' (כמ\"ש<sup data-n=\"6\">166</sup> \"דע את אלקי אביך ועבדהו בלב שלם\"), שש המצוות שחיובן תמידי בכל רגע<sup data-n=\"7\">167</sup>, גם בנשים<sup data-n=\"8\">168</sup>.\nב. אמנם, מזה שאומר ששתי התורות נאמרו בהקהל, גם בפני נשים, משמע, שחמש התורות שלאח\"ז לא נאמרו בפני נשים.\nוטעם הדבר – כמובן מהמאמר הנ\"ל ש\"מדבר בענין נשמות דעלמא דדכורא ודעלמא דנוקבא\" – שב' תורות הראשונות שייכות גם לנשמות דעלמא דנוקבא, משא\"כ ה' התורות שלאח\"ז שייכות רק לעלמא דדכורא.\nויש לומר, שחילוק זה מרומז גם <i>בזמן</i> אמירת התורות – שב' תורות הראשונות (ששייכות גם לנשמות דעלמא דנוקבא) נאמרו <i>בליל</i> שבת (מלכות, נוקבא), משא\"כ ה' התורות שלאח\"ז נאמרו <i>ביום</i> השבת (ז\"א, דכורא).\nג. ובביאור השייכות דב' תורות הראשונות גם לנשמות דעלמא דנוקבא – יש לומר:\nמהחילוקים שבין דכר לנוקבא (איש ואשה) – ש\"איש דרכו לכבוש ואין אשה דרכה לכבוש\"<sup data-n=\"9\">169</sup>. ודוגמתו בעבודת ה' – שהעבודה <i>דכיבוש</i> העולם ע\"י <i>מלחמה</i> שייכת לנשמות דעלמא דדכורא, \"<i>איש</i> דרכו לכבוש\", היינו, שהאדם העובד הוא במעמד ומצב של חוזק ותוקף בעבודת ה', משא\"כ כשהאדם העובד אינו במעמד ומצב של חוזק ותוקף בעבודת ה' (ועד שתשש כחו כנקבה<sup data-n=\"10\">170</sup>), אינו יכול לעסוק בכיבוש העולם ע\"י מלחמה, ע\"ד מארז\"ל \"סמוך לפלטרי' שלך לא הורשת כו'\"<sup data-n=\"11\">171</sup>, \"קשוט עצמך (תחילה) ואח\"כ קשוט אחרים\"<sup data-n=\"12\">172</sup>.\nאמנם, שיטתו של הבעש\"ט שאין צורך בכיבוש העולם בדרך של מלחמה (שבירת המנגד), אלא אדרבה, התכלית היא <i>לברר ולזכך</i> את העולם ולעשותו כלי לאלקות (לעשות לו ית' דירה בתחתונים<sup data-n=\"13\">173</sup>) – ע\"י <i>המשכת אור הקדושה</i>, שזהו\"ע ד\"לשכן שמו שם, לפרסם אלקות בעולם\" (תוכן ב' תורות הראשונות), ועבודה זו שייכת לכאו\"א מישראל, גם לנשמות דעלמא דנוקבא, שאין דרכן לכבוש<sup data-n=\"14\">174</sup>.\nוכמודגש גם בסיום התורה השני' שהענין ד\"לשכן שמו שם\" הוא ע\"י \"ברכה ופסוק תהלים\" – שענין זה שייך לכל אחד ואחת מישראל, אנשים ונשים.\nד. ויש להוסיף, שלאחרי שנתגלו ונתפרסמו בדפוס כל שבעת התורות, ניתנה האפשרות <i>לנשים</i> ללמוד גם את חמש התורות השייכות לנשמות דעלמא <i>דדכורא</i> שנאמרו רק בפני אנשים.\nוע\"ד שמצינו (באופן הפכי) בהסיפור<sup data-n=\"15\">175</sup> אודות אדמו\"ר האמצעי, שלפעמים הי' מבקש מאחותו מרת פריידא (שהיתה חביבה אצל רבינו הזקן והי' אומר דא\"ח בפני') שתשאל איזה ענין מרבינו והוא הי' מתחבא ושומע – שמסתבר לומר, שזמנים אלו היו מסוגלים לאמירת תורה חדשה ששייכת לנשמות דעלמא <i>דנוקבא</i>, ולכן שלח אדמו\"ר האמצעי את אחותו שתעורר את רבינו הזקן לאמירת תורה זו, ועי\"ז זכה <i>גם הוא</i> לשמוע התורה השייכת לנשמות דעלמא דנוקבא.\nולהעיר, שמצינו <i>מעין זה</i> בפשוטו של מקרא: (א) חידוש פרשה ע\"י <i>נוקבא</i> – פרשת נחלות שזכו <i>בנות צלפחד</i> ונכתבה על ידן<sup data-n=\"16\">176</sup>, (ב) חידוש פרשה ע\"י <i>דכורא</i> – פרשת פסח שני, \"ויהי <i>אנשים</i> אשר היו טמאים לנפש אדם\"<sup data-n=\"17\">177</sup>, \"<i>מישאל ואלצפן</i> . . שהיו עוסקין בנדב ואביהוא\"<sup data-n=\"18\">178</sup> (שהכניסה בפנים (להוציא את נדב ואביהוא) יכולה להיות ע\"י זכרים דוקא), שזכו שתאמר על ידם, ושתי הפרשיות (הן הפרשה שנתחדשה ע\"י נשים והן הפרשה שנתחדשה ע\"י אנשים) שייכות לאנשים ונשים.\nה. אמנם, עפ\"ז צריך להבין: כיון שלאחרי הגילוי והפירסום בדפוס יכולות (וצריכות) הנשים ללמוד גם ה' התורות שנאמרו בפני האנשים – מהי התועלת (הלימוד וההוראה) שבהדגשת החילוק שבין ב' התורות שנאמרו גם בפני הנשים לה' התורות שנאמרו רק בפני האנשים?\nויש לומר הביאור בזה:\nהחילוק שבין שמיעת התורות בשעתן (שב' תורות ראשונות נאמרו גם בפני נשים וה' תורות שלאח\"ז נאמרו בפני אנשים) ללימודן לאחרי ההתגלות והפירסום בדפוס (שכל שבעת התורות גלויות ומפורסמות גם לנשים) – ששמיעת התורות בשעתן היא ע\"י הגילוי <i>מלמעלה למטה</i>, ואילו לימודן לאח\"ז הוא ע\"י העבודה <i>מלמטה למעלה</i>, ולכן, גם כאשר מצד הגילוי מלמעלה למטה ה\"ז ענין השייך לנשמות דעלמא דדכורא, פועלת העבודה בכח עצמו את השייכות גם לנשמות דעלמא דנוקבא.\n[מעין דוגמא לדבר – שמצינו שע\"י פעולת העקידה ניתנה ביצחק (שנשמתו היתה מעלמא דנוקבא) נשמה חדשה שמעלמא דדכורא<sup data-n=\"19\">179</sup>].\nועפ\"ז יש לבאר הטעם שבפירסום התורות מדגישים שרק ב' תורות נאמרו גם בפני נשים – שהידיעה שרק ב' תורות הראשונות נאמרו גם בפני הנשים, ואילו ה' התורות שלאח\"ז נאמרו בפני האנשים בלבד, מעוררת את התשוקה של נשי ישראל לה' התורות שנאמרו בפני האנשים, ותשוקה זו כשלעצמה היא ה\"עבודה\" (בכח עצמן) שעל ידה ממשיכים עליהן השייכות גם לעניני התורה השייכים לנשמות מעלמא דדכורא.\nויש לומר שזהו גם הביאור בהסיפור הנ\"ל שאדמו\"ר האמצעי התחבא ושמע עניני התורה השייכים לעלמא דנוקבא שאמר רבינו הזקן בפני בתו – שאין זה ענין של הערמה באופן ד\"מים<sup data-n=\"20\">180</sup> גנובים<sup data-n=\"21\">181</sup> יומתקו\"<sup data-n=\"22\">182</sup>, כי אם, שההשתוקקות לשמיעת דברי תורה אלו (שהתבטאה גם בכך שהתחבא לשמעם) היא העבודה שעל ידה נעשית השייכות דתורה זו (מעלמא דנוקבא) גם אליו<sup data-n=\"23\">183</sup>.",[["1","161","עקב יא, יט."],["2","162","הל' ת\"ת לאדה\"ז ספ\"א. וש\"נ."],["3","163","תהלים פח, ו."],["4","164","שבת ל, א. וש\"נ."],["5","165","ראה לקו\"ש חי\"ז ע' 344. וש\"נ."],["6","166","דברי הימים-א כח, ט. וראה תניא (קו\"א) קנו, ב. ועוד."],["7","167","ראה אגרת המחבר שבריש ס' החינוך – בסופה."],["8","168","ולהעיר מפס\"ד הרמב\"ם (סוף הל' תשובה) \"מלמדין . . את הנשים . . לעבוד מיראה . . עד שתרבה דעתן ויתחכמו חכמה יתירה מגלים להם רז זה מעט מעט ומרגילין אותן לענין זה בנחת עד שישיגוהו וידעוהו ויעבדוהו מאהבה\" – \"מעלה גדולה מאד . . מעלת אברהם אבינו שקראו הקב\"ה אוהבו\"."],["9","169","יבמות סה, ב."],["10","170","ע\"ד ברכות לב, א. ועוד."],["11","171","ספרי עקב יא, כד."],["12","172","ב\"מ קז, סע\"ב. וש\"נ."],["13","173","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["14","174","והחידוש הוא שגם נשמות דעלמא דנוקבא, שאין דרכן לכבוש, יכולים \"לשכן שמו <i>שם</i>\" – \"שם\" דייקא, דקאי על מקום הקליפות כו' (ראה לעיל אות ד' סוס\"א)."],["15","175","בית רבי ח\"א פכ\"ד (נז, ב)."],["16","176","ב\"ב קיט, א. וש\"נ. ספרי ופרש\"י פינחס כז, ה."],["17","177","בהעלותך ט, ו."],["18","178","סוכה כה, סע\"א ואילך. ספרי עה\"פ."],["19","179","ראה אוה\"ת בראשית (כרך ב') תלב, סע\"א ואילך."],["20","180","משלי ט, יז."],["21","181","להעיר מזח\"ב צג, ב: \"אי לאו דפסקא טעמא הוה אסיר אפילו למגנב דעתא דרבי' באורייתא . . ובמה דפסיק טעמא, אסיר ושרי\"."],["22","182","ע\"ד הסיפור הידוע (אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ז ע' קעו ואילך. בית רבי ח\"א פ\"ב בהערה) אודות רבינו הזקן ור' אברהם המלאך, שהי' מדובר ביניהם שרבינו הזקן ילמוד עם הר\"א המלאך נגלה, והר\"א המלאך ילמוד עם רבינו הזקן חסידות, וסיפר רבינו הזקן שלפעמים הי' מחזיר את המורה שעות לאחוריו כדי ללמוד יותר, אשר, נוסף להרויח בזמן, הרי, בהלימוד שבזמן זה ניתוסף גם העילוי ד\"מים גנובים <i>יומתקו</i>\"."],["23","183","משיחות ש\"פ תבוא ח\"י אלול תשט\"ז (הוספות ללקו\"ש ח\"ט ע' 339). ח\"י אלול תשכ\"ג. ש\"פ תבוא תשמ\"א. ש\"פ תבוא ח\"י אלול תשמ\"ז."]]],[300010955,"תכז\n\n<b>שמחת עבדי השם</b>\nא. המוזכר בתורה הששית ע\"ד שמחת עבדי השם (\"זיי זיינען שמח וואָס זיי זיינען זוכה זיין עבדי השם\") – שייך למצות ביכורים שבהתחלת פרשת כי תבוא:\nבמצות ביכורים מודגש ביותר ענין השמחה (נוסף על השמחה שבכל המצוות, כמ\"ש בהמשך פרשת כי תבוא<sup data-n=\"1\">184</sup> \"עבדת את ה' אלקיך בשמחה ובטוב לבב\") – כמ\"ש<sup data-n=\"2\">185</sup> \"<i>ושמחת</i> בכל הטוב אשר נתן לך ה' אלקיך גו'\", \"מכאן<sup data-n=\"3\">186</sup> אמרו אין קורין מקרא ביכורים אלא <i>בזמן שמחה</i> מעצרת ועד החג\"<sup data-n=\"4\">187</sup>.\nומרומז גם בהתחלת הפרשה – \"והי' כי תבוא אל הארץ\", כדרשת חז\"ל<sup data-n=\"5\">188</sup> \"אין והי' אלא לשון <i>שמחה</i>\"<sup data-n=\"6\">189</sup>.\nוענינו בעבודת האדם בכל יום – שהתחלת וראשית היום (ע\"ד \"מראשית כל פרי האדמה\") היא בהכרת תודה ונתינת שבח והודאה לה', הן בנוגע לכללות מציאותו, כמודגש באמירת \"מודה אני לפניך כו' שהחזרת בי נשמתי\", שנעשה \"ברי' חדשה\"<sup data-n=\"7\">190</sup>, והן בנוגע לכל הצרכים הפרטיים, כמודגש בברכות השחר. ועי\"ז נעשה אצלו מעמד ומצב ד\"ושמחת בכל הטוב אשר נתן לך ה' אלקיך\" במשך כל היום כולו, החל מהשמחה על הזכות להיות עבד השם, דכיון שעבודת השם היא הנקודה העיקרית דכל פרטי עניניו (הן עניני תומ\"צ והן עניני הרשות שנעשים לשם שמים) וכל מציאותו (\"אני (לא) נבראתי (אלא) לשמש את קוני\"<sup data-n=\"8\">191</sup>), הרי, השמחה על שזוכה להיות עבד השם היא באופן <i>תמידי</i>.\nב. ויש להוסיף, שגם בהשמחה על שזוכים להיות עבדי השם ישנם ע\"ד ובדוגמת ב' הענינים דמתנה וירושה מלמעלה (\"תבוא אל הארץ אשר ה' אלקיך נותן לך\") ועבודה בכח עצמו (\"וירשתה וישבת בה\"):\nובהקדמה – שמעלת העבודה בכח עצמו (אתעדל\"ת) שמגעת בדרגא נעלית יותר מאשר ההמשכה שנמשכת מלמעלה (אתעדל\"ע), מודגשת במיוחד בנוגע לשמחה, דכיון ששמחה פורצת גדר<sup data-n=\"9\">192</sup>, גם הגדרים שלמעלה<sup data-n=\"10\">193</sup>, הרי בודאי שהשמחה שבכח עצמו היא נעלית יותר מהשמחה שנמשכת מלמעלה<sup data-n=\"11\">194</sup>.\nומזה מובן גם בנוגע להשמחה על שזוכים להיות עבדי השם – שאף ששמחה זו היא תמידית (כנ\"ל), מ\"מ, צריכה להיות באופן של הוספה ועילוי<sup data-n=\"12\">195</sup> מיום ליום (כשנעשה \"ברי' חדשה\"), כי, דרגת השמחה (על שזוכה להיות עבד ה') שהיתה אצלו אתמול נעשית כמו טבע (שני) המזומן לו, ע\"ד שמחה הבאה מלמעלה, ולכן צריך להוסיף מדילי', בכח עצמו, דרגא נעלית יותר בהשמחה<sup data-n=\"13\">196</sup>.\nבסגנון אחר: השמחה על שזוכים להיות עבדי השם היא לא רק ביחס ובהשוואה למצב הפכי (אלמלא זכו לכך), שזוהי דרגא חד-פעמית בהשמחה (וכבר היתה אתמול כו', ובהתחלת העבודה, ואח\"כ ה\"ז מזומן לו כמו דבר שניתן מלמעלה), אלא גם ובעיקר השמחה שמצד המעלה דעבדי השם כשלעצמה, שהיא נעלית יותר<sup data-n=\"14\">197</sup>, וניתוסף בה (ע\"י עבודת האדם בכח עצמו) בעילוי אחר עילוי, עד אין-סוף<sup data-n=\"15\">198</sup>.\nג. עפ\"ז יומתק שענין זה (השמחה על שזוכים להיות עבדי השם) נאמר ע\"י הבעש\"ט בגן עדן, לאחר גמר עבודתו בעוה\"ז הגשמי:\nהמעלה דגן עדן היא בנוגע להתגלות מלמעלה, ואילו המעלה דעוה\"ז הגשמי היא בנוגע לעבודה בכח עצמו.\nוכמודגש בהחילוק שבין הנשמות בגן עדן קודם ירידתן למטה, שעם היותן בדרגא נעלית ביותר, כמאמר<sup data-n=\"16\">199</sup> \"כל נשמתא ונשמתא הוה קיימא בדיוקנאה קמי' מלכא קדישא\", ה\"ז בעיקר מצד הגילוי מלמעלה, ואילו מצד עצמן ה\"ה בבחינת \"עומדים\"<sup data-n=\"17\">200</sup>, לגבי מעלת הנשמות לאחרי עבודתן בעוה\"ז, בכח עצמן, שעי\"ז נעשים בבחינת \"מהלכים\"<sup data-n=\"18\">201</sup>.\nובנוגע לנדו\"ד:\nבאמירת תורה זו (ע\"ד השמחה על שזוכים להיות עבדי השם) בגן עדן, שמעלתו בההתגלות מלמעלה, וללא נתינת מקום לענינים בלתי-רצויים – מודגש שהכוונה בהשמחה על שזוכים להיות עבדי השם, היא, לא ביחס ובהשוואה למצב הפכי (שאינו שייך בגן עדן<sup data-n=\"19\">202</sup>), אלא בנוגע לעצם המעלה דעבדי השם.\nובאמירתה ע\"י הבעש\"ט לאחר גמר עבודתו בעוה\"ז הגשמי, שמעלתו בעבודה בכח עצמו<sup data-n=\"20\">203</sup> – מודגש ששמחה זו צריכה להיות באופן של הוספה ועילוי ע\"י עבודתו בכח עצמו<sup data-n=\"21\">204</sup>.",[["1","184","כח, מז."],["2","185","שם כו, יא."],["3","186","פרש\"י עה\"פ."],["4","187","ולהעיר ממ\"ש בהשיעור דיום הרביעי – שבכמה שנים חל בו ח\"י אלול – \"ובנית שם מזבח גו' וזבחת גו' <i>ושמחת</i> לפני ה' אלקיך\" (כז, ה-ז)."],["5","188","ראה ב\"ר פמ\"ב, ג."],["6","189","ראה גם או\"ת להמגיד על הפסוק: \"פתח הכתוב בלשון והי\"ה שהוא לשון שמחה, כי עיקר העבודה שתהי' בשמחה ובטוב לב ובהתלהבות גדול וזאת נקרא שמחה של מצוה, כי העובד מאהבה שמח תמיד בעבודתו כו'\"."],["7","190","שו\"ע אדה\"ז או\"ח רס\"ו. וראה יל\"ש תהלים רמז תשב."],["8","191","משנה וברייתא סוף מס' קידושין."],["9","192","ראה סה\"מ תרנ\"ז ס\"ע רכג ואילך."],["10","193","ראה סה\"מ שם (ע' רנב ואילך) שהשמחה מגעת בעצמותו ית', למעלה יותר מהמצוה עצמה."],["11","194","ועפ\"ז מבואר שם (ע' רסה ואילך. ע' רפב ואילך) תוכן הבקשה \"שמח תשמח רעים האהובים\" – שאף שבבחינת \"רעים אהובים\" (חו\"ב) יש ענין השמחה, הרי שמחה זו היא בהגבלה, ע\"פ מה שנמשך מלמעלה בסדר השתלשלות, ולכן מבקשים \"שמח תשמח\", שתומשך ב\"רעים אהובים\" השמחה העצמי' דא\"ס שנמשכת ע\"י עבודת המטה*."],["12","195","כלומר: לא רק הוספה בהשמחה בגלל שהגיע לדרגא נעלית יותר בעבודת ה' (כיון שעבודתו היא באופן ד\"מעלין בקודש\"), אלא גם השמחה שבכללות הענין דעבודת ה' צריכה להיות באופן של הוספה (\"מעלין בקודש\" בהשמחה שבכללות עבודת ה' גופא)."],["13","196","ואף ששמחה שפורצת גדר היא בלי-גבול – הרי ידוע שבבל\"ג גופא ישנם דרגות (דוגמא לדבר: א\"ס נקודות בקו (כי נקודה אין לה מקום), וא\"ס קוים בשטח, וא\"ס שטחים במעוקב)."],["14","197","דאף שהיציאה ממצב בלתי-רצוי היא שמחה גדולה ביותר (ראה תניא פל\"א (מ, סע\"א)), מ\"מ, כיון שחושב ומתבונן בהמצב הבלתי-רצוי שהי' מקודם, הרי השמחה היא לפי ערך וביחס להמצב הקודם (וכמו ב\"אהבת עולם\", שבאה ע\"י ההתבוננות בעניני העולם, שהיא לפי ערך וביחס לעניני העולם), משא\"כ שמחה שאינה קשורה עם יציאה ממעמד ומצב בלתי-רצוי, היא למעלה ממדידה והגבלה."],["15","198","וע\"ד שלימות השמחה דלעתיד לבוא (לאחרי ש\"את רוח הטומאה אעביר מן הארץ\") – \"שמחת עולם על ראשם\", עולם במובן של נצחיות, עליות בשמחה עצמה עד א\"ס (ע\"ד המבואר בתניא אגה\"ק סו\"ס כו)."],["16","199","ראה זח\"ג קד, ב. זח\"א צ, סע\"ב. רכז, ב. רלג, ב. זח\"ב צו, ב. זח\"ג סא, ב."],["17","200","ומרומז גם בדיוק הלשון \"קיימא\", מלשון עמידה."],["18","201","ראה תו\"א ס\"פ וישב (ל, סע\"א ואילך). ובכ\"מ."],["19","202","ודוגמתו בעבודת האדם – שבעמדו \"לפניך\" (\"מודה אני לפניך\") באמיתיות, אינו שייך לענינים בלתי-רצויים ח\"ו."],["20","203","ולהעיר מהשייכות המיוחדת להבעש\"ט – \"בעל (בעה\"ב על הענין ד)שם טוב\" – כי, ב\"שם טוב\" (שלמטה מתורה כהונה ומלכות, ולכן אינו נחשב לכתר בפ\"ע), מודגשת ביותר מעלת העבודה <i>בכח עצמו</i> (משא\"כ בתורה כהונה ומלכות שעיקרם מצד הגילוי מלמעלה)."],["21","204","משיחת ש\"פ תבוא תשמ\"ח.\n-----שולי הגליון-----\n*) <i>ומ\"ש \"כשמחך יצירך בגן עדן מקדם\" – יש לפרש \"</i>כ<i>שמחך\" בכ\"ף הדמיון </i>למעליותא,<i> כיון שהשמחה שנמשכת ע\"י עבודת האדם היא באופן נעלה יותר מהשמחה שנמשכה מלמעלה בהתחלת הבריאה</i>."]]],[300010956,"תכח\n\n<b>קומי אורי</b>\nכללות הענין ד\"קומי <i>אורי</i>\" שייך במיוחד לח\"י אלול (שבו נאמרה תורה זו) – יום הולדת את שני <i>המאורות</i> הגדולים, אדמו\"ר הזקן (בשנת קה\"ת) והבעש\"ט (בשנת נח\"ת):\nבח\"י אלול שנת קה\"ת, שאז נולד אדמו\"ר הזקן, אמר הבעש\"ט לתלמידיו: \"ביום הרביעי (שבו חל ח\"י אלול בשנה ההיא) וואָס בו נתלו <i>המאורות</i>, איז אין דעם יום הרביעי פון <i>קומי אורי</i> אַראָפּגעקומען אַ נשמה חדשה וועלכע וועט <i>באַלייכטן</i> די וועלט אין תורה הנגלית והחסידות\" (ביום הרביעי נתלו <i>המאורות</i>, וביום הרביעי לסדר <i>קומי אורי</i> ירדה נשמה חדשה <i>שתאיר</i> את העולם בתורה הנגלית והחסידות)<sup data-n=\"1\">205</sup>.\nומזה מובן גם בנוגע לח\"י אלול שנת נח\"ת, שאז נולד הבעש\"ט<sup data-n=\"2\">206</sup> – שגילוי אור החסידות דהבעש\"ט שייך להענין ד\"קומי אורי\".\nויש להוסיף, שהענין ד\"קומי אורי\" הוא למעלה מהגילוי ד\"שני המאורות הגדולים\" גם לאחרי ש\"והי' אור הלבנה כאור החמה ואור החמה יהי' שבעתיים כאור שבעת הימים\"<sup data-n=\"3\">207</sup> – ע\"ד מ\"ש<sup data-n=\"4\">208</sup> \"לא יהי' לך עוד השמש לאור יומם גו' והי' לך <i>ה'</i> לאור עולם\", שזהו גם התוכן ד\"קומי אורי כי בא אורך <i>וכבוד ה'</i> עליך זרח\"<sup data-n=\"5\">209</sup>.",[["1","205","שיחת ח\"י אלול תש\"ה (ספר השיחות ע' 129)."],["2","206","אף שאז היתה הקביעות ביום השני (שיחת ח\"י אלול תש\"ג (ספר השיחות ע' 141))."],["3","207","ישעי' ל, כו."],["4","208","שם ס, יט, – המשך ההפטרה ד\"קומי אורי\"."],["5","209","משיחת ש\"פ תצא תשל\"א. מאמר ד\"ה קומי אורי דש\"פ תבוא ח\"י אלול תשל\"ג."]]],[300010957,"תכט\n\n<b>ההתעסקות בטובת הרבים</b>\nא. אע\"פ שהמאמר \"קומי אורי\" נאמר <i>לנשיאי ישראל</i> (\"אתם נשיאי ישראל כו'\"), מ\"מ, כיון שגם מאמר זה נתגלה ונתפרסם (ע\"י כ\"ק מו\"ח אדמו\"ר נשיא דורנו) לכל ישראל, בודאי יש בו לימוד והוראה <i>לכל ישראל</i>.\nוהענין בזה:\nאצל כאו\"א מישראל ישנו החיוב דהתעסקות בטובת הזולת ובטובת הרבים (הן מצד הציווי \"הוכח תוכיח את עמיתך\"<sup data-n=\"1\">210</sup>, והן מצד כללות הציווי ד\"ואהבת לרעך כמוך\"<sup data-n=\"2\">211</sup>), <i>מעין ודוגמת</i> הפעולה דנשיאי ישראל בשביל טובת הרבים.\nוהלימוד וההוראה מתוכן המאמר – שכאו\"א צריך להשתדל בהתעסקות בצרכי ציבור גם על חשבון תורתו ועבודתו, וישנה ברכה מיוחדת שלא יחסר בתורתו ועבודתו, ע\"ד מארז\"ל \"תורתם משתמרת\"<sup data-n=\"3\">212</sup>, ויתירה מזה, \"ברכה ניתנת בתורתן\"<sup data-n=\"4\">213</sup>, ולא עוד אלא שעי\"ז ניתוסף העילוי ד\"<i>קומי אורי</i>\", שזהו\"ע שלא בערך אפילו לגבי \"ברכה ניתנת בתורתן\".\nויש לומר, שהענין ד\"קומי אורי\" שנאמר בנוגע להתעסקות בטובת הרבים הוא ע\"ד דרשת חז\"ל<sup data-n=\"5\">214</sup> על הפסוק<sup data-n=\"6\">215</sup> \"והמשכילים יזהירו כזהר הרקיע ומצדיקי הרבים ככוכבים לעולם ועד\", שקאי על גבאי צדקה ומלמדי תינוקות<sup data-n=\"7\">216</sup>.\nב. ויש להוסיף בביאור תוכן המאמר – דלכאורה אינו מובן:\nכללות הפעולה בשביל טובת הרבים ע\"י כאו\"א מישראל, ועאכו\"כ ע\"י נשיאי ישראל שתפקידם ושליחותם להנהיג את ישראל, היא, חיוב ומצוה ע\"פ תורה, כאמור, \"הוכח תוכיח את עמיתך\", \"ואהבת לרעך כמוך\".\nוענין נוסף בנוגע לנשיאי ישראל – שהתעסקותם בשביל טובת הרבים קשורה עם כללות ענין הנשיאות והמלכות, \"שום תשים עליך מלך\"<sup data-n=\"8\">217</sup>, שקיומה תלוי (לא רק בהעם שמשימים עליהם מלך, אלא) גם <i>בהמלך</i> שמקבל על עצמו הנהגת המלכות להנהיג את העם<sup data-n=\"9\">218</sup> (\"אשר יוציאם ואשר יביאם\"<sup data-n=\"10\">219</sup>), ובמילא, פעולת המלך (נשיאי ישראל) בהנהגת העם (טובת הרבים) היא חלק מכללות הציווי ד\"שום תשים עליך מלך\".\nועפ\"ז צריך להבין תוכן השאלה \"אתם נשיאי ישראל כו' מה יהי' עמכם\" – הרי ההתעסקות בטובת הרבים (גם על חשבון תורתם ועבודתם) היא קיום <i>מצוה בתורה</i><sup data-n=\"11\">220</sup>, שזהו תכלית ועיקר תורתם ועבודתם לקיים רצון העצמות?!\nועד\"ז בנוגע להלימוד וההוראה לכאו\"א מישראל בנוגע להתעסקות בטובת הזולת והרבים (גם על חשבון תורתו ועבודתו) – מה מקום לשאלה בדבר (מה יהי' עמו) בה בשעה שעי\"ז מקיים ציווי התורה (\"הוכח תוכיח את עמיתך\", \"ואהבת לרעך כמוך\"), רצון העצמות?!\nג. ויש לומר הביאור בזה:\nבקיום המצוות ישנם (בכללות) ב' ענינים: (א) קיום רצון העצמות, (ב) פרטי ההמשכות וההשפעות שע\"י כל מצוה ומצוה. ואף שההמשכות וההשפעות הם רק אורות וגילויים שבאין-ערוך לגבי הענין העיקרי דקיום רצון העצמות, מ\"מ, כיון שרצון העצמות הוא שע\"י המצוות יומשכו האורות והגילויים, ה\"ז גם ענין עיקרי בקיום המצוות.\nובנוגע לעניננו:\nאע\"פ שההתעסקות בטובת הרבים גם על חשבון תורתו ועבודתו היא מצוה בתורה שעל ידה מקיימים רצון העצמות, מ\"מ, בנוגע למעלת האורות וגילויים (שגם זה ענין עיקרי בקיום המצוות כנ\"ל) ה\"ז ענין של <i>ירידה</i>, שצריך לירד ממדרגתו כדי לפעול על הזולת הענין ד\"הוכח תוכיח\" וכיו\"ב.\nועאכו\"כ בנוגע לנשיאי ישראל, שמצד גודל מעלתם באופן ש\"משכמו ומעלה גבוה מכל העם\"<sup data-n=\"12\">221</sup>, מובן, שהתעסקותם בטובת הרבים (תוך כדי הנחת תורתם ועבודתם) היא <i>ירידה גדולה</i> ביחס למעלת האורות והגילויים.\nועל זה נאמר \"קומי אורי\", באור הפרטי להכללי כו' – שגם בענין האורות והגילויים (\"אורי\", ובזה גופא הפרטי והכללי) לא יחסר, ואדרבה, ע\"י הירידה לעסוק בטובת הרבים יתוסף עוד יותר גם בענין האורות והגילויים.\nד. ויש לקשר זה עם המבואר בתו\"א<sup data-n=\"13\">222</sup> במעלת הצדקה – צדקה גשמית, ועד\"ז גם צדקה רוחנית – שעי\"ז נעשים מוחו ולבו זכים <i>אלף פעמים ככה</i>, שאין זה בדרך גוזמא בעלמא, אלא אלף פעמים ככה <i>כפשוטו</i>, כמובן מהמבואר בלקו\"ת לג\"פ<sup data-n=\"14\">223</sup> ע\"פ מארז\"ל<sup data-n=\"15\">224</sup> \"אלף בני אדם נכנסין למקרא יוצא מהן מאה למשנה, מאה למשנה יוצאין מהן עשרה לתלמוד, עשרה לתלמוד יוצא מהם אחד להוראה\".\nונקודת הביאור בזה – שע\"י הירידה למטה בעשי' גשמית<sup data-n=\"16\">225</sup> ניתוסף עילוי גדול יותר (כיון שכח העשי' הוא גבוה ביותר רק שנשפל למטה כו') עד לבחי' אלף, מלשון אאלפך חכמה, חכמה דאצילות, ועד לבחי' הכתר שלמעלה מהשתלשלות, ועד להתגלות העצמות, יש האמיתי שקשור עם יש הגשמי דוקא<sup data-n=\"17\">226</sup>.\nוכמודגש גם במעלת ההוראה (\"אחד להוראה\") – הלכה <i>למעשה</i>, שקשור עם גילוי שם הוי'<sup data-n=\"18\">227</sup> (\"והוי' עמו שהלכה כמותו\"<sup data-n=\"19\">228</sup>), שלמעלה מגילוי שם אלקים (\"אלו ואלו דברי אלקים חיים\"<sup data-n=\"20\">229</sup>), כמבואר בהמשך תרס\"ו<sup data-n=\"21\">230</sup>.\nומזה מובן גם בנוגע לעבודתם של נשיאי ישראל – שדוקא ע\"י הירידה שבהנחת תורתם ועבודתם (התנשאות עצמית) בשביל טובת הרבים (התנשאות על העם), ובמיוחד בנוגע לענינים של מעשה בפועל, ניתוסף אצלם עילוי גדול יותר גם בבחינת האורות והגילויים, בחי' החכמה והכתר (אלף).\nומעין זה גם בעבודת כאו\"א מישראל שמשתדל בטובת הרבים ע\"י העסק בצרכי ציבור, כאמור, שעי\"ז נעשים מוחו ולבו זכים אלף פעמים ככה, ובמילא, ניתוסף עוד יותר גם בתורתו ועבודתו.\nה. ויש להוסיף ולהעיר, שענין זה (שע\"י הירידה למטה דוקא באים לעילוי גדול יותר) מרומז בהשיעור תניא דח\"י אלול כפי שנקבע בדיוק ע\"י כ\"ק מו\"ח אדמו\"ר נשיא דורנו:\nהשיעור דח\"י אלול לשנה פשוטה<sup data-n=\"22\">231</sup> – \"שמעתי ממורי ע\"ה ע\"פ<sup data-n=\"23\">232</sup> ואנכי עפר ואפר שאמר אברהם אבינו ע\"ה על . . מדתו מדת אהבה רבה שהי' אוהב את הקב\"ה אהבה גדולה ועליונה . . (ש)אין דמיון וערך מהות אור האהבה המאיר בו אל מהות אור אהבה וחסד עליון שבאצילות אלא כערך ודמיון מהות העפר שנעשה אפר אל מהותו ואיכותו כשהי' עץ נחמד למראה וטוב למאכל עד\"מ ויותר מזה כו'\", שמזה מובן גודל הירידה דאברהם בהיותו למטה (וכמבואר בענין אברהם אברהם פסיק טעמא בגווייהו<sup data-n=\"24\">233</sup>, שבהיותו למטה אינו דומה לכמו שהוא למעלה<sup data-n=\"25\">234</sup>). ואעפ\"כ, איתא בספר הבהיר<sup data-n=\"26\">235</sup> \"אמרה מדת החסד לפני הקב\"ה רבש\"ע מימי היות אברהם בארץ לא הוצרכתי אני לעשות מלאכתי שהרי אברהם עומד ומשמש במקומי\", היינו, שבהיותו למטה החליף את מדת החסד דאצילות, ועד שמדת החסד דאצילות <i>מקנאת</i> בעבודתו של אברהם אבינו<sup data-n=\"27\">236</sup> – שמזה מובן שדוקא ע\"י הירידה למטה ניתוסף אצלו עילוי גדול יותר.\nוהשיעור דח\"י אלול לשנה מעוברת<sup data-n=\"28\">237</sup> – \"כ\"ז הוא בנפש השכלית התחתונה שבאדם הבאה מקליפת נוגה, אך באמת לאמיתו בנפש העליונה האלקית שהיא חלק אלקה ממעל כל המדות פנימיות וחיצוניות הן לה' לבדו כו'\", שמקדים תחילה המדות דנפש השכלית ואח\"כ מבאר המדות דנפש האלקית, כיון שדוקא ע\"י הירידה למטה (נפש השכלית שלמעלה מנפש האלקית) באים לעילוי גדול יותר<sup data-n=\"29\">238</sup>.",[["1","210","קדושים יט, יז."],["2","211","שם, יח."],["3","212","ברכות לב, ב."],["4","213","ירושלמי שם פ\"ה ה\"א. וראה לקו\"ש חט\"ז ע' 375 ואילך. וש\"נ."],["5","214","ב\"ב ח, ב."],["6","215","דניאל יב, ג."],["7","216","להעיר מהשייכות דמלמדי תינוקות להבעש\"ט ואדמו\"ר הזקן שיום הולדתם בח\"י אלול: הבעש\"ט – שקודם התגלותו הי' (עוזר ל)מלמד תינוקות ואומר עמהם איש\"ר כו' (ראה ספר השיחות תש\"א ע' 32. ועוד), ואדמו\"ר הזקן – שגם כשיסד ה\"חדרים\" עבור לומדים מופלגים בנגלה ובנסתר (לקו\"ד ח\"א יא, ב. כט, ב), לא נקראו בשם ישיבה וכיו\"ב, אלא בשם \"חדר\" דוקא, שבזה מרומז גם הלימוד עם תינוקות כפשוטם."],["8","217","שופטים יז, טו."],["9","218","ועד\"ז בהמצוות שמקיים המלך ומוציא י\"ח את כלל ישראל* – שקיומן תלוי (לא רק במלך עצמו, אלא) גם בהעם שמקבלים מלכותו, כיון שעי\"ז מאפשרים לו לקיים מצוות המלך**."],["10","219","פינחס כז, יז."],["11","220","ובודאי שמקבלים על זה שכר, ובפרט כשקיום מצוה זו היא מתוך מס\"נ שמניחים תורתם ועבודתם, שאז השכר הוא גדול ביותר."],["12","221","שמואל-א ט, ב."],["13","222","בראשית א, ב."],["14","223","נדפס לאח\"ז באוה\"ת בראשית ח\"ו תתרכו, ב ואילך."],["15","224","ויק\"ר רפ\"ב. קה\"ר פ\"ז, כח."],["16","225","כמרומז בתיבת <i>ככה</i> (אלף פעמים ככה) – שלמטה מבחי' כה, ועאכו\"כ למטה מבחי' זה (אוה\"ת שם)."],["17","226","ראה ביאוה\"ז לאדהאמ\"צ בשלח מג, ג. ובכ\"מ."],["18","227","ודוגמתו בענין קומי אורי – כהמשך הכתוב \"וכבוד <i>הוי'</i> עליך זרח\"."],["19","228","סנהדרין צג, ב."],["20","229","עירובין יג, ב. וש\"נ."],["21","230","ד\"ה כל השונה הלכות (ע' תכז ואילך)."],["22","231","אגה\"ק סט\"ו (קכא, סע\"א ואילך)."],["23","232","וירא כח, יז."],["24","233","זח\"ג קלח, רע\"א (אד\"ר)."],["25","234","ראה סה\"מ תש\"ט ע' 152 הערה 15. ועוד."],["26","235","סקצ\"א (זח\"א בהשמטות רסד, רע\"ב) – הובא ונת' בפרדס שער כב פ\"ד."],["27","236","ראה ספר השיחות תרח\"ץ ריש ע' 251. ע' 255. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' שכא."],["28","237","שם (קכג, סע\"א)."],["29","238","משיחות ש\"פ תבוא ח\"י אלול תש\"כ. תשל\"ג.\n-----שולי הגליון-----\n*) <i>נוסף לכך שכל מצוה של איש פרטי קשורה עם כלל ישראל מצד הערבות דכל ישראל זב\"ז (ראה סהמ\"צ להצ\"צ מצות אהבת ישראל)</i>.\n**) <i>ולהעיר, שיש דעה שמצות ברכת כהנים שייכת גם לכלל ישראל המתברכים</i>,<i> כי</i>,<i> לולי המתברכים לא שייכת הברכה</i>."]]],[300010958,"תל\n\n<b>נשיאי ישראל – התנשאות עצמית</b>\nא. תוכן המאמר לנשיאי ישראל – אתם נשיאי ישראל שמניחים התורה ועבודה שלכם בשביל טובת הרבים, מה יהי' עמכם, ועל זה נאמר קומי אורי כו' – מצינו דוגמתו במדרש על הפסוק \"למנצח לדוד להזכיר\"<sup data-n=\"1\">239</sup>.\nוז\"ל: \"משל . . למלך שהי' לו צאן וכעס עליהן, הסיר את הצאן והסיר את הדיר, והוציא את הרועה, אחר ימים חזר המלך לצאנו, התחיל מכנסה ובונה את הדיר ולרועה לא הזכיר, אמר הרועה הרי הצאן מתכנסת והדיר בנוי' ואני איני נזכר, כך אמר דוד, למעלה מהפרשה כי<sup data-n=\"2\">240</sup> אלקים יושיע ציון ויבנה ערי יהודה, הרי הדיר בנוי', וישבו שם וירשוה וזרע עבדיו ינחלוה ואוהבי שמו ישכנו בה, הרי הצאן, אמר הרועה ואני איני נזכר, למנצח לדוד להזכיר\".\nודוגמתו בנדו\"ד:\nנשיאי ישראל הם בדוגמת רועי צאן, רועי ישראל שנקראים בשם צאן, כמ\"ש<sup data-n=\"3\">241</sup> \"שה פזורה ישראל\", שנמצאים במעמד ומצב של פיזור מצד הירידה בעניני העולם וטרדות הפרנסה שבזמן הגלות, ותפקידם של הנשיאים-רועים לפעול <i>כינוס הצאן</i>, לאסוף את הכחות שנתפזרו בעניני העולם ולהעלותם לאלקות, <i>ולבנות הדיר</i>, ע\"ד \"תפארת אדם לשבת בית\"<sup data-n=\"4\">242</sup>, ודוגמתו בבחי' בהמה (צאן) שלמעלה מאדם<sup data-n=\"5\">243</sup>, עבודה שלמעלה מטו\"ד, הו\"ע הדיר, ועד לגמר ושלימות העבודה לעשות לו ית' <i>דירה</i> בתחתונים<sup data-n=\"6\">244</sup>.\nומצד גודל התמסרותם של נשיאי ורועי ישראל לכלל ישראל, שאינם דואגים לעצמם אלא לצאן מרעיתם [ע\"ד המסופר במדרש<sup data-n=\"7\">245</sup> אודות הנהגת משה ודוד במרעה הצאן שלכן נבחרו לרעות צאנו של הקב\"ה] – צ\"ל הזכרה מיוחדת (\"למנצח לדוד להזכיר\") בנוגע לנשיאי ורועי ישראל, שזהו תוכן המאמר ד\"קומי אורי\" לנשיאי ישראל שמניחים תורתם ועבודתם בשביל טובת הרבים.\nב. ויש לומר, שההזכרה דנשיאי ורועי ישראל (\"קומי אורי\") היא בשייכות לענינם המיוחד <i>מצד עצמם</i>, למעלה מצאן מרעיתם:\nנוסף על שייכותם של נשיאי ורועי ישראל לצאן מרעיתם, יש בהם מעלה מיוחדת כפי שהם באופן של הבדלה מצאן מרעיתם (ובגלל מעלה זו בכחם וביכלתם להיות רועי ישראל), כמ\"ש במלך (ועד\"ז נשיא) \"משכמו ומעלה גבוה מכל העם\"<sup data-n=\"8\">246</sup>, \"אין עליו אלא ה' אלקיו\"<sup data-n=\"9\">247</sup>, ועד להתנשאות עצמית, הקשורה עם ההתנשאות עצמית דלמעלה (בחי' המלך המרומם לבדו מאז), כידוע שהשרש דספירת המלכות הוא בבחי' התנשאות עצמית<sup data-n=\"10\">248</sup>.\nולאחרי שלימות עבודת נשיאי ורועי ישראל עם צאן מרעיתם (כינוס הצאן ובניית הדיר), מתעלים לדרגא נעלית יותר – שמתגלה אצלם שרשם בבחי' התנשאות עצמית.\nומצד גודל העילוי שבזה יש צורך בנתינת כח מיוחדת מלמעלה (גם לאחרי שלימות העבודה) – \"למנצח לדוד להזכיר\", \"קומי אורי\".\nג. ויש להוסיף, שגם מעלה זו (התנשאות עצמית) פועלים נשיאי ורועי ישראל אצל כל ישראל:\nגם לאחרי כינוס הצאן ובניית הדיר, שמורה על שלימות עבודתם של ישראל בעולם לעשות לו ית' דירה בתחתונים, ישנו ענין נעלה יותר מצד עצם מציאותם של ישראל (למעלה מעבודתם בעולם) – היחוד דישראל עם הקב\"ה באופן ש\"ישראל וקוב\"ה כולא חד\"<sup data-n=\"11\">249</sup>, כפי שיתגלה לעתיד לבוא, כמארז\"ל<sup data-n=\"12\">250</sup> \"עתידין צדיקים שנקראין על שמו של הקב\"ה\", היינו, שיתאחדו לאחדים ממש עד שיקראו בשמו של הקב\"ה.\nוזהו תוכן הענין ד\"למנצח לדוד להזכיר\" – כי, זכרון הוא מצד ביטול המציאות לגמרי, שאינו מציאות לעצמו כלל, כי אם \"ישראל וקוב\"ה כולא חד\", ולאחרי גמר העבודה באופן שנרגשת עדיין איזו מציאות, באים (ע\"י הפעולה דנשיאי ורועי ישראל) להשלימות האמיתית דביטול המציאות לגמרי, \"להזכיר\", מצד שרשם בעצמותו ית' (ע\"ד התנשאות עצמית) באופן ד\"ישראל וקוב\"ה כולא חד\".\nד. ויש לומר, שענין זה מרומז גם ב\"קומי אורי כי בא אורך\":\nעל הפסוק \"קומי אורי כי בא אורך\", איתא במדרש<sup data-n=\"13\">251</sup>: \"אמרו ישראל לפני הקב\"ה, עשינו לך מנורה בימי משה וכבתה, בימי שלמה וכבתה, מכאן ואילך אין אנו ממתינים אלא לאורך, שנאמר<sup data-n=\"14\">252</sup> כי עמך מקור חיים באורך נראה אור\", היינו, שהענין ד\"קומי אורי כי בא אורך\" הוא ע\"ד הענין ד\"באורך נראה אור\".\nונקודת הביאור בזה – ש\"אורך\" קאי על תורה, \"תורה אור\"<sup data-n=\"15\">253</sup>, והאור שנראה ע\"י אורך (\"באורך נראה אור\") קאי על השרש דישראל, שע\"י התורה מתגלה השרש דישראל שלמעלה מהתורה<sup data-n=\"16\">254</sup>, \"ישראל וקוב\"ה כולא חד\".\nועפ\"ז יומתק שהתורה לנשיאי ישראל על הפסוק \"קומי אורי\" נאמרה \"בסעודתא דזעיר אנפין\" (סעודה שלישית), זמן הכי נעלה ביום השבת – כי, התוכן דתורה זו קשור עם הדרגא הכי נעלית ד\"ישראל וקוב\"ה כולא חד\", ולכן ה\"ז שייך להזמן הכי נעלה ביום השבת, \"זמן התגלות בחי' רעוא דכל רעוין שזהו בחי' פנימיות הרצון ופנימיות התענוג שהוא בחי' התענוג העצמי והפשוט לגמרי\" (כמבואר בהמשך תרס\"ו<sup data-n=\"17\">255</sup>), מעין ודוגמת תכלית השלימות דלעתיד לבוא<sup data-n=\"18\">256</sup>.",[["1","239","תהלים ע, א וביל\"ש עה\"פ (רמז תתב בסופו)."],["2","240","סט, לו-לז."],["3","241","ירמי' נ, יז."],["4","242","ישעי' מד, יג."],["5","243","ועד לבחי' בהמה רבה שלפני האצילות (ראה תניא ספמ\"ו)."],["6","244","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["7","245","שמו\"ר פ\"ב, ב."],["8","246","שמואל-א ט, ב."],["9","247","הוריות יא, רע\"ב. רמב\"ם הל' שגגות פט\"ו ה\"ו."],["10","248","ראה תו\"א מג\"א ד, ג ואילך. סה\"מ תרצ\"ט ע' 20 ואילך. תש\"א ס\"ע 42 ואילך. ועוד."],["11","249","ראה זח\"ג עג, א."],["12","250","ב\"ב עה, רע\"ב."],["13","251","יל\"ש ישעי' עה\"פ (רמז תצט בתחלתו)."],["14","252","תהלים לו, יו\"ד."],["15","253","משלי ו, כג."],["16","254","ראה סה\"מ מלוקט ח\"ג ע' רעו. בהוצאה החדשה – ע' רסט וש\"נ."],["17","255","בסופו (ריש ע' תקמה)."],["18","256","ממאמר ד\"ה למנצח לדוד להזכיר דש\"פ צו יו\"ד ניסן תשל\"ב (סה\"מ תשל\"ב ע' 143 ואילך). שיחה ומאמר ד\"ה קומי אורי דש\"פ תבוא ח\"י אלול תשל\"ג (סה\"מ מלוקט ח\"ג ע' רעג ואילך. בהוצאה החדשה – ע' רסו ואילך)."]]],[300010959,"תלא\n\n<b>מעלת ההתעסקות בטובת הרבים</b>\n<b>שבשביל זה כדאי הירידה</b>\nא. אחת משבעת התורות שאמר מורנו הבעש\"ט בח\"י אלול תרנ\"ב היא:\n\"אתם נשיאי ישראל וואָס איר לייגט אַוועק אייער תורה ועבודה בשביל טובת הרבים, וואָס וועט זיין מיט אייך וכו'\" (אתם נשיאי ישראל שמניחים התורה ועבודה שלכם בשביל טובת הרבים, מה יהי' עמכם וכו').\nומזה מובן, שהתעסקותם של נשיאי ישראל בטובת הרבים הו\"ע של ירידה. וכפי שמצינו ש\"אמר ר' יהושע בן לוי, ס' הלכות למדני ר\"י בן פדיי' . . וכולן נשתכחו ממני בשביל שהייתי עוסק בצרכי ציבור\"<sup data-n=\"1\">257</sup>.\nואם בנוגע לנשיאי ישראל אומר הבעש\"ט שזהו\"ע של ירידה – הרי כל-שכן בנוגע ליהודי שהוא <i>לא מיני' ולא מקצתי'</i> דהבעש\"ט ונשיאי ישראל, שעסקנותו הציבורית בשביל טובת הרבים (שכתוצאה מכך צריך להניח את תורתו ועבודתו) הו\"ע של <i>ירידה</i>.\nאלא שאעפ\"כ כדאי הדבר – כמובן מהנהגתם של נשיאי ישראל – מצד גודל המעלה שבהתעסקות בטובת הרבים, שבשביל מעלה זו כדאית הירידה.\nב. ויש לקשר זה עם פרשת השבוע – פרשת נצבים:\nאיתא בירושלמי<sup data-n=\"2\">258</sup>: \"משה הקדים ראשים לזקינים (כמ\"ש בהתחלת פרשתנו: \"אתם נצבים היום כולכם גו' ראשיכם גו' זקניכם גו'\"), יהושע הקדים זקינים לראשים (כמ\"ש<sup data-n=\"3\">259</sup> \"ויאסף יהושע גו' ויקרא לזקני ישראל ולראשיו גו'\")\". ואחד מהביאורים בזה (בירושלמי שם): \"משה על ידי שצפה ברוח הקודש שעתידין ישראל להיסתכר במלכיות (להסתגר ולהיות נמסרין ביד המלכיות<sup data-n=\"4\">260</sup>) וראשיהן עומדין על גביהן הקדים ראשים לזקינים\" (שאם אין ראשיהן משתדלין לפייס את המלכות אין כח ביד הזקנים ללמוד תורה{260}).\nופירוש הדברים:\n\"ראשים\" הם <i>פרנסי הציבור</i> (שמנהיגים את הציבור), ו\"זקינים\" הם <i>התלמידי חכמים</i> (כמאחז\"ל<sup data-n=\"5\">261</sup> \"אין זקן אלא מי שקנה חכמה\"){260}. ולכן, בזמן הבית, כשבנ\"י אינם מסורין ביד המלכיות, ת\"ח (\"זקינים\") הם נעלים יותר מפרנסי הציבור (\"ראשים\"), אבל בזמן הגלות, כשבנ\"י מסורין ביד המלכיות, ויש צורך בהשתדלותן של פרנסי הציבור, הרי הם – פרנסי הציבור – נעלים יותר מת\"ח.\nוזהו החילוק בין משה ליהושע: יהושע, שהי' \"ראש לכובשים\"<sup data-n=\"6\">262</sup>, שכבש את ארץ ישראל והכניס את בנ\"י לארץ – מעמד ומצב של <i>חירות</i> (היפך הגלות) – הקדים זקנים לראשים, בהתאם להמצב בדורו, שהת\"ח קודמים לפרנסי הציבור. אבל משה שדיבר (גם) אודות <i>זמן הגלות</i> – כידוע<sup data-n=\"7\">263</sup> שהכריתת ברית עם משה רבינו היתה על זמן הגלות<sup data-n=\"8\">264</sup> [ועל זה ביקש \"ונפלינו אני ועמך גו'\"<sup data-n=\"9\">265</sup>, שגם בזמן <i>הגלות</i> תהי' ההבדלה דבנ\"י כו'] – הקדים ראשים לזקנים, כי בזמן הגלות פרנסי הציבור קודמים לת\"ח.\nג. ונוסף על האמור לעיל שמצד גודל המעלה שבעסקנות ציבורית (ובפרט בזמן הגלות) כדאית גם הירידה שנעשית בלימוד התורה, הנה עוד זאת, שמעלה זו <i>מסלקת ומבטלת</i> את הירידה שבלימוד התורה.\nוהביאור בזה – ע\"פ הידוע<sup data-n=\"10\">266</sup> שע\"י קיום מצות הצדקה – צדקה גשמית ומכל-שכן צדקה רוחנית – \"נעשה מוחו ולבו זכים אלף פעמים ככה\":\nמובן וגם פשוט שהפעולה דנתינת הצדקה אינה מוסיפה ידיעה בתורה, ואדרבה כו', שהרי בשעה שעוסק בנתינת הצדקה אינו יכול לעסוק בלימוד התורה, ובמילא, ביחס ללימוד התורה ה\"ז לכאורה ענין של ירידה. אמנם, מעלתה של נתינת הצדקה שעל ידה נעשים מוחו ולבו זכים אלף פעמים ככה, כך, שכאשר יעסוק בתורה <i>שעה אחת</i> יצליח להספיק בלימודו בריבוי גדול כל כך שע\"ד הרגיל (לולי נתינת הצדקה) הי' זקוק ליגיעה במשך <i>אלף שעות</i>!\nונמצא, שאף שההתעסקות במצות הצדקה כשלעצמה היא <i>ירידה</i> ביחס ללימוד התורה, מ\"מ, גודל העילוי ש\"נעשה מוחו ולבו זכים אלף פעמים ככה\", בכחו גם <i>לבטל</i> את הירידה.\nד. ובנוגע אלינו:\nישנם כאלה החושבים אשר העובדה שכ\"ק מו\"ח אדמו\"ר שלחם למקומות מסויימים לפעול שם בהפצת התורה והיהדות, היא, לא לטובתם, כי אם, לטובת המקום שאליו נשלחו, ובשביל טובת המקום <i>מוותר</i> כ\"ק מו\"ח אדמו\"ר על טובתם הם. ועכ\"פ – חושבים הם – זוהי רק טובתם הרוחנית, ובשביל טובתם הרוחנית <i>מוותרים</i> על טובתם הגשמית.\nצריכים לדעת איפוא שהחלוקה בין טובתו לטובת הזולת (שזוהי טובה רק בשביל הזולת ולא בשבילו) היא – בדקות דדקות – ענין של <i>שניות</i> (היפך האחדות) ח\"ו, כי, הכוונה העליונה <i>אחת</i> היא, ואם זוהי כוונת השליחות שלו, ה\"ז גם <i>טובתו</i>. ועאכו\"כ שלא יתכן לחלק בין טובתו הרוחנית וטובתו הגשמית – כי, מצד אחדותו הפשוטה של הקב\"ה, גשמיות ורוחניות מתאימים זל\"ז.\nואף שבעיניו נראים הדברים באופן אחר (\"אים קוקט אויס אַנדערש\"), שכן, הוא \"רואה\" שבאם הי' נמצא במקום פלוני ופלוני והי' מתעסק בענין פלוני ופלוני הי' מרויח הרבה יותר – הרי, מי יודע אם במקרה ההוא לא הי' הכסף הולך ח\"ו בשביל עניני רפואה וכיו\"ב<sup data-n=\"11\">267</sup>. אבל זאת צריכים לדעת (\"וויסן דאַרף מען אָבער וויסן\"), שמצד אחדותו הפשוטה של הקב\"ה, גשמיות ורוחניות יחדיו ילכו<sup data-n=\"12\">268</sup>.",[["1","257","שמו\"ר פ\"ו, ב. וש\"נ."],["2","258","הוריות פ\"ג ה\"ה."],["3","259","יהושע כד, א."],["4","260","פני משה שם."],["5","261","קידושין לב, ב."],["6","262","פתיחתא דאסת\"ר יו\"ד."],["7","263","תיב\"ע עה\"פ תשא לד, יו\"ד. הובא ונת' בד\"ה הנה אנכי כורת ברית תר\"ל, תרנ\"ד (סה\"מ תר\"ל ע' קב ואילך, תרנ\"ד ע' קעד ואילך). ועוד."],["8","264","נוסף על הכריתת ברית עם אברהם שהיתה על זמן הבית, והכריתת ברית דנח שהיתה על כללות קיום העולם."],["9","265","תשא לג, טז."],["10","266","תו\"א בראשית א, ב."],["11","267","חסר קצת (<i>המו\"ל</i>)."],["12","268","משיחת ח\"י אלול תשי\"ב."]]],[300010960,"תלב\n\n<b>ה\"חסר\" בשבעת התורות</b>\nא. בהרשימה דשבעת התורות שאמר מורנו הבעש\"ט בח\"י אלול תרנ\"ב בגן עדן, נרשם בב' מקומות (בסיום תורה הג' ובסיום תורה הז') תיבת \"חסר\".\nוצ\"ע אם ה\"חסר\" אינו אלא בהרשימה, רשימת <i>השומעים</i> (בלתי מוגה), שלא זכרו את המשך דברי כ\"ק מו\"ח אדמו\"ר כשחזר על שבעת התורות<sup data-n=\"1\">269</sup>, או שה\"חסר\" הוא בהתגלות שבעת התורות ע\"י כ\"ק אדנ\"ע וכ\"ק מו\"ח אדמו\"ר.\nובכל אופן, כיון שבפועל נדפסה הרשימה עם תיבת \"חסר\", וידועה תורת הבעש\"ט<sup data-n=\"2\">270</sup> שכל דבר הוא בהשגחה פרטית ויש בו לימוד והוראה בעבודת ה', ובפרט בעניני תורה, ותורות שנאמרו בגן עדן כו' – בודאי שגם מתיבת \"חסר\" יש לימוד והוראה בעבודת ה'.\nב. ובהקדם ענין דוגמתו בספר התניא – שבסוף שער היחוד והאמונה נרשמה תיבת \"חסר\", וכך נדפס בדפוסים הראשונים של ספר התניא<sup data-n=\"3\">271</sup>. וכמ\"ש תלמידו הגדול של רבינו הזקן, הרה\"ג והרה\"ח כו' מהור\"ר אהרן הלוי מסטאראשעלי, בהקדמתו לספר שער היחוד והאמונה שלו: \"שער היחוד והאמונה . . לא הספיק הזמן בידו להשלימו כפי כוונתו ורצונו הקדוש\" (שזהו התוכן ד\"חסר\").\nואעפ\"כ, בכל דפוסי התניא שלאח\"ז הושמטה תיבת \"חסר\" – בודאי בידיעת והסכמת או הוראת רבותינו נשיאינו.\nויש לומר הביאור בזה – שע\"י הגילוי רב בתורת חסידות חב\"ד שגילו רבותינו נשיאינו לאחרי כתיבת והדפסת ספר התניא (כולל גם בביאור הענינים שבשער היחוד והאמונה) – <i>נשלם</i> ה\"חסר\", ולכן הושמטה תיבת \"חסר\" מהדפוסים <i>שלאח\"ז</i>.\nויש להביא ראי' ודוגמא לדבר בנגלה דתורה – \"א\"ר יהושע שמעתי כו' ואין לי לפרש (ע\"ד \"חסר\"), א\"ר עקיבא אני אפרש\"<sup data-n=\"4\">272</sup> (ע\"ד השלמת ה\"חסר\").\nג. ועפ\"ז יש לבאר גם בנדו\"ד:\nבכתיבת תיבת \"חסר\" מרומזת הכוונה <i>לעורר</i> (\"אַרויסרופן\") את יגיעת הלומד – מלמטה למעלה – כדי להוסיף <i>ולהשלים</i> את ה\"חסר\".\nוע\"ד מ\"ש<sup data-n=\"5\">273</sup> \"תן לחכם ויחכם עוד\"<sup data-n=\"6\">274</sup> – שנוסף על הענינים שנותנים לחכם, ובעין יפה (\"כל הנותן בעין יפה הוא נותן\"<sup data-n=\"7\">275</sup>), משאירים ענינים נוספים שיצטרך להתייגע עליהם בכח עצמו כדי להחכים בהם.\nולהעיר, שמצינו דוגמתו בסדר כללות הבריאה ע\"י הקב\"ה – שלאחרי שלימות הבריאה באופן ד\"טוב מאד\"<sup data-n=\"8\">276</sup>, כתיב<sup data-n=\"9\">277</sup> \"אשר ברא אלקים לעשות\", שפירושו \"<i>לתקן</i>\"<sup data-n=\"10\">278</sup>, היינו, שהקב\"ה משאיר <i>חסרון</i> כדי שיתוקן ע\"י עבודת האדם.\nועד\"ז בנדו\"ד, שאף שמגלים התורות, מ\"מ, משאירים ענינים מסויימים באופן ד\"חסר\", כדי שתהי' היגיעה בכח עצמו באופן ד\"ויחכם עוד\".\n[ויומתק יותר ע\"פ המבואר במק\"א<sup data-n=\"11\">279</sup> שבהתגלות שבעת התורות דהבעש\"ט ע\"י נשיאי חב\"ד מודגש החיבור דמלמעלה למטה (תורת החסידות הכללית) ומלמטה למעלה (תורת חסידות חב\"ד) – שבהתגלות התורות מלמעלה למטה באופן ד\"חסר\" מודגש הצורך בעבודה בכח עצמו מלמטה למעלה].\nואף שמי הוא זה ואיזהו אשר ערב לבו לגשת כו' להשלים את ה\"חסר\" שבשבעת התורות שאמר מורנו הבעש\"ט בגן עדן – הרי, לאחרי הגילוי רב בתורת חסידות חב\"ד שגילו רבותינו נשיאינו עד היום הזה, ישנה האפשרות לה\"יחכם עוד\" גם בנוגע לה\"חסר\" שבשבעת התורות<sup data-n=\"12\">280</sup>.\n**********",[["1","269","וברשימה אחרת נוסחא אחרת מתורה הז' (נדפסה לעיל ע' רפ הערה 17) – לא נרשם חסר (<i>המו\"ל</i>)."],["2","270","ראה לעיל סימן קעט ואילך. וש\"נ."],["3","271","בהוצאות: תקנ\"ז. תקס\"ה. תקס\"ו. תק\"פ. תקפ\"ו."],["4","272","פסחים צו, ב – במשנה."],["5","273","משלי ט, ט."],["6","274","ראה גם אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' שסד ואילך – בביאור השייכות דתורת אדה\"ז ותורת הבעש\"ט (ראה לעיל סימן תכ)."],["7","275","ראה ב\"ב נג, רע\"א. וש\"נ."],["8","276","בראשית א, לא."],["9","277","שם ב, ג."],["10","278","ראה ב\"ר פי\"א, ו ובפרש\"י."],["11","279","לעיל אות א'."],["12","280","משיחת ש\"פ תבוא ח\"י אלול תשמ\"ז."]]]]});
